create temporary table stay_i18n_desc (en text primary key, tr jsonb not null) on commit drop;
insert into stay_i18n_desc (en, tr) values
  ('{"root":{"children":[{"children":[{"detail":0,"format":1,"mode":"normal","style":"","text":"Ab Mirza Traditional Boutique Hotel","type":"text","version":1},{"detail":0,"format":0,"mode":"normal","style":"","text":" was inaugurated in 2023. Spanning two floors across three buildings, it features a total of 15 rooms designed as a beautiful, traditional residence. The elegant structures date back to the Pahlavi era; following their conversion into a boutique hotel, they underwent extensive renovations and restoration. The hotel’s exterior facade evokes the Qajar era, while the interior design showcases authentic Iranian-Islamic traditional architecture.","type":"text","version":1}],"direction":null,"format":"","indent":0,"type":"paragraph","version":1,"textFormat":0,"textStyle":""},{"children":[{"detail":0,"format":0,"mode":"normal","style":"","text":"The lighting and interior design of the rooms at Ab Mirza Boutique Hotel offer guests an unparalleled sense of tranquility. The property’s courtyard is a welcoming oasis, featuring delightful floral arrangements, traditional seating platforms (Takhts), and gazebos nestled beside ponds filled with colorful fish, providing a serene setting for breakfast and café services.","type":"text","version":1}],"direction":null,"format":"","indent":0,"type":"paragraph","version":1,"textFormat":0,"textStyle":""}],"direction":"ltr","format":"","indent":0,"type":"root","version":1,"textFormat":1}}', '{"tr-TR": "{\"root\":{\"children\":[{\"children\":[{\"detail\":0,\"format\":1,\"mode\":\"normal\",\"style\":\"\",\"text\":\"Ab Mirza Geleneksel Butik Otel\",\"type\":\"text\",\"version\":1},{\"detail\":0,\"format\":0,\"mode\":\"normal\",\"style\":\"\",\"text\":\" 2023''te açıldı. Üç binada iki kata yayılan otel, güzel ve geleneksel bir konak olarak tasarlanmış toplam 15 odaya sahiptir. Zarif yapılar Pehlevi dönemine uzanır; butik otele dönüştürülmelerinin ardından kapsamlı bir yenileme ve restorasyondan geçmiştir. Otelin dış cephesi Kaçar dönemini anımsatırken iç tasarımı özgün İran-İslam geleneksel mimarisini yansıtır.\",\"type\":\"text\",\"version\":1}],\"direction\":null,\"format\":\"\",\"indent\":0,\"type\":\"paragraph\",\"version\":1,\"textFormat\":0,\"textStyle\":\"\"},{\"children\":[{\"detail\":0,\"format\":0,\"mode\":\"normal\",\"style\":\"\",\"text\":\"Ab Mirza Butik Otel''in odalarındaki aydınlatma ve iç tasarım, misafirlere eşsiz bir huzur duygusu sunar. Tesisin avlusu; hoş çiçek düzenlemeleri, geleneksel oturma sekileri (taht) ve renkli balıklarla dolu havuzların kenarındaki çardaklarıyla davetkâr bir vahadır ve kahvaltı ile kafe hizmetleri için huzurlu bir ortam sağlar.\",\"type\":\"text\",\"version\":1}],\"direction\":null,\"format\":\"\",\"indent\":0,\"type\":\"paragraph\",\"version\":1,\"textFormat\":0,\"textStyle\":\"\"}],\"direction\":\"ltr\",\"format\":\"\",\"indent\":0,\"type\":\"root\",\"version\":1,\"textFormat\":1}}", "es-ES": "{\"root\":{\"children\":[{\"children\":[{\"detail\":0,\"format\":1,\"mode\":\"normal\",\"style\":\"\",\"text\":\"El Hotel Boutique Tradicional Ab Mirza\",\"type\":\"text\",\"version\":1},{\"detail\":0,\"format\":0,\"mode\":\"normal\",\"style\":\"\",\"text\":\" se inauguró en 2023. Repartido en dos plantas y tres edificios, cuenta con un total de 15 habitaciones concebidas como una hermosa residencia tradicional. Los elegantes edificios datan de la época Pahlavi; tras su conversión en hotel boutique, fueron objeto de amplias reformas y restauraciones. La fachada exterior del hotel evoca la época Qajar, mientras que el diseño interior muestra auténtica arquitectura tradicional iraní-islámica.\",\"type\":\"text\",\"version\":1}],\"direction\":null,\"format\":\"\",\"indent\":0,\"type\":\"paragraph\",\"version\":1,\"textFormat\":0,\"textStyle\":\"\"},{\"children\":[{\"detail\":0,\"format\":0,\"mode\":\"normal\",\"style\":\"\",\"text\":\"La iluminación y el diseño interior de las habitaciones del Hotel Boutique Ab Mirza ofrecen a los huéspedes una sensación de tranquilidad incomparable. El patio del establecimiento es un oasis acogedor, con encantadores arreglos florales, plataformas tradicionales para sentarse (takhts) y cenadores junto a estanques llenos de peces de colores, que ofrecen un entorno sereno para el desayuno y el servicio de cafetería.\",\"type\":\"text\",\"version\":1}],\"direction\":null,\"format\":\"\",\"indent\":0,\"type\":\"paragraph\",\"version\":1,\"textFormat\":0,\"textStyle\":\"\"}],\"direction\":\"ltr\",\"format\":\"\",\"indent\":0,\"type\":\"root\",\"version\":1,\"textFormat\":1}}", "ku-KU": "{\"root\":{\"children\":[{\"children\":[{\"detail\":0,\"format\":1,\"mode\":\"normal\",\"style\":\"\",\"text\":\"هوتێلی بوتیکی کۆنی ئاب میرزا\",\"type\":\"text\",\"version\":1},{\"detail\":0,\"format\":0,\"mode\":\"normal\",\"style\":\"\",\"text\":\" لە ساڵی 2023 کرایەوە. لە دوو نهۆم و سێ بینادا، کۆی گشتی 15 ژووری هەیە کە وەک نیشینگەیەکی جوان و کۆن دیزاین کراون. بینا شکۆدارەکانی دەگەڕێنەوە بۆ سەردەمی پەهلەوی؛ دوای گۆڕینیان بۆ هوتێلی بوتیک، نۆژەنکردنەوە و چاککردنەوەیەکی فراوانیان بەسەردا هات. ڕووکاری دەرەوەی هوتێلەکە سەردەمی قاجار دەهێنێتەوە بیر، لە کاتێکدا دیزاینی ناوەوەی تەلارسازیی کۆنی ڕەسەنی ئێرانی-ئیسلامی پیشان دەدات.\",\"type\":\"text\",\"version\":1}],\"direction\":null,\"format\":\"\",\"indent\":0,\"type\":\"paragraph\",\"version\":1,\"textFormat\":0,\"textStyle\":\"\"},{\"children\":[{\"detail\":0,\"format\":0,\"mode\":\"normal\",\"style\":\"\",\"text\":\"ڕووناکی و دیزاینی ناوەوەی ژوورەکانی هوتێلی بوتیکی ئاب میرزا هەستێکی ئارامیی بێوێنە بە میوانان دەبەخشن. حەوشەی ئەم شوێنە وەک باخچەیەکی دڵگیرە، بە گوڵ و ڕازاندنەوەی خۆش، تەختی دانیشتنی کۆن و کەپر لە تەنیشت حەوزەکانی پڕ لە ماسیی ڕەنگاوڕەنگ، کە ژینگەیەکی ئارام بۆ نانی بەیانی و خزمەتگوزاریی کافێ دابین دەکات.\",\"type\":\"text\",\"version\":1}],\"direction\":null,\"format\":\"\",\"indent\":0,\"type\":\"paragraph\",\"version\":1,\"textFormat\":0,\"textStyle\":\"\"}],\"direction\":\"ltr\",\"format\":\"\",\"indent\":0,\"type\":\"root\",\"version\":1,\"textFormat\":1}}", "de-DE": "{\"root\":{\"children\":[{\"children\":[{\"detail\":0,\"format\":1,\"mode\":\"normal\",\"style\":\"\",\"text\":\"Das traditionelle Boutiquehotel Ab Mirza\",\"type\":\"text\",\"version\":1},{\"detail\":0,\"format\":0,\"mode\":\"normal\",\"style\":\"\",\"text\":\" wurde 2023 eröffnet. Auf zwei Etagen in drei Gebäuden bietet es insgesamt 15 Zimmer, gestaltet als schöne, traditionelle Residenz. Die eleganten Gebäude stammen aus der Pahlavi-Zeit; nach ihrem Umbau zum Boutiquehotel wurden sie umfassend renoviert und restauriert. Die Außenfassade des Hotels erinnert an die Kadscharenzeit, während die Innengestaltung authentische traditionelle iranisch-islamische Architektur zeigt.\",\"type\":\"text\",\"version\":1}],\"direction\":null,\"format\":\"\",\"indent\":0,\"type\":\"paragraph\",\"version\":1,\"textFormat\":0,\"textStyle\":\"\"},{\"children\":[{\"detail\":0,\"format\":0,\"mode\":\"normal\",\"style\":\"\",\"text\":\"Beleuchtung und Innenausstattung der Zimmer im Boutiquehotel Ab Mirza schenken den Gästen ein unvergleichliches Gefühl der Ruhe. Der Innenhof ist eine einladende Oase mit herrlichem Blumenschmuck, traditionellen Sitzpodesten (Takhts) und Pavillons an Teichen voller bunter Fische – ein friedlicher Rahmen für Frühstück und Café.\",\"type\":\"text\",\"version\":1}],\"direction\":null,\"format\":\"\",\"indent\":0,\"type\":\"paragraph\",\"version\":1,\"textFormat\":0,\"textStyle\":\"\"}],\"direction\":\"ltr\",\"format\":\"\",\"indent\":0,\"type\":\"root\",\"version\":1,\"textFormat\":1}}", "fr-FR": "{\"root\":{\"children\":[{\"children\":[{\"detail\":0,\"format\":1,\"mode\":\"normal\",\"style\":\"\",\"text\":\"L’hôtel-boutique traditionnel Ab Mirza\",\"type\":\"text\",\"version\":1},{\"detail\":0,\"format\":0,\"mode\":\"normal\",\"style\":\"\",\"text\":\" a été inauguré en 2023. Réparti sur deux étages dans trois bâtiments, il compte au total 15 chambres conçues comme une belle demeure traditionnelle. Les élégants bâtiments datent de l’époque Pahlavi ; après leur transformation en hôtel-boutique, ils ont fait l’objet d’importants travaux de rénovation et de restauration. La façade extérieure de l’hôtel évoque l’époque qajare, tandis que la décoration intérieure met en valeur une architecture traditionnelle irano-islamique authentique.\",\"type\":\"text\",\"version\":1}],\"direction\":null,\"format\":\"\",\"indent\":0,\"type\":\"paragraph\",\"version\":1,\"textFormat\":0,\"textStyle\":\"\"},{\"children\":[{\"detail\":0,\"format\":0,\"mode\":\"normal\",\"style\":\"\",\"text\":\"L’éclairage et la décoration intérieure des chambres de l’hôtel-boutique Ab Mirza offrent aux hôtes un sentiment de sérénité incomparable. La cour de l’établissement est une oasis accueillante, avec de ravissantes compositions florales, des banquettes traditionnelles (takhts) et des gloriettes nichées au bord de bassins peuplés de poissons colorés : un cadre paisible pour le petit-déjeuner et le service de café.\",\"type\":\"text\",\"version\":1}],\"direction\":null,\"format\":\"\",\"indent\":0,\"type\":\"paragraph\",\"version\":1,\"textFormat\":0,\"textStyle\":\"\"}],\"direction\":\"ltr\",\"format\":\"\",\"indent\":0,\"type\":\"root\",\"version\":1,\"textFormat\":1}}", "ru-RU": "{\"root\":{\"children\":[{\"children\":[{\"detail\":0,\"format\":1,\"mode\":\"normal\",\"style\":\"\",\"text\":\"Традиционный бутик-отель «Аб Мирза»\",\"type\":\"text\",\"version\":1},{\"detail\":0,\"format\":0,\"mode\":\"normal\",\"style\":\"\",\"text\":\" открылся в 2023 году. Он занимает два этажа в трёх зданиях и насчитывает 15 номеров, оформленных как красивая традиционная резиденция. Изящные здания относятся к эпохе Пехлеви; после переоборудования в бутик-отель они прошли масштабную реконструкцию и реставрацию. Фасад отеля напоминает о каджарской эпохе, а интерьеры демонстрируют подлинную традиционную ирано-исламскую архитектуру.\",\"type\":\"text\",\"version\":1}],\"direction\":null,\"format\":\"\",\"indent\":0,\"type\":\"paragraph\",\"version\":1,\"textFormat\":0,\"textStyle\":\"\"},{\"children\":[{\"detail\":0,\"format\":0,\"mode\":\"normal\",\"style\":\"\",\"text\":\"Освещение и интерьер номеров бутик-отеля «Аб Мирза» дарят гостям ни с чем не сравнимое ощущение покоя. Внутренний двор — уютный оазис с чудесными цветочными композициями, традиционными помостами для сидения (тахтами) и беседками у прудов с разноцветными рыбками: безмятежное место для завтрака и кафе.\",\"type\":\"text\",\"version\":1}],\"direction\":null,\"format\":\"\",\"indent\":0,\"type\":\"paragraph\",\"version\":1,\"textFormat\":0,\"textStyle\":\"\"}],\"direction\":\"ltr\",\"format\":\"\",\"indent\":0,\"type\":\"root\",\"version\":1,\"textFormat\":1}}", "tg-TJ": "{\"root\":{\"children\":[{\"children\":[{\"detail\":0,\"format\":1,\"mode\":\"normal\",\"style\":\"\",\"text\":\"Меҳмонхонаи бутикии анъанавии «Об Мирзо»\",\"type\":\"text\",\"version\":1},{\"detail\":0,\"format\":0,\"mode\":\"normal\",\"style\":\"\",\"text\":\" соли 2023 кушода шуд. Он дар ду ошёнаи се бино ҷойгир буда, ҳамагӣ 15 ҳуҷра дорад, ки ҳамчун манзили зебои анъанавӣ тарҳрезӣ шудаанд. Биноҳои зебои он ба даврони Паҳлавӣ тааллуқ доранд; пас аз табдил ёфтан ба меҳмонхонаи бутикӣ онҳо таъмиру барқарорсозии васеъ гузаштанд. Намои берунии меҳмонхона даврони Қоҷорро ба ёд меорад, ороиши дохилӣ бошад, меъмории аслии анъанавии эронию исломиро намоиш медиҳад.\",\"type\":\"text\",\"version\":1}],\"direction\":null,\"format\":\"\",\"indent\":0,\"type\":\"paragraph\",\"version\":1,\"textFormat\":0,\"textStyle\":\"\"},{\"children\":[{\"detail\":0,\"format\":0,\"mode\":\"normal\",\"style\":\"\",\"text\":\"Равшанӣ ва ороиши дохилии ҳуҷраҳои меҳмонхонаи бутикии «Об Мирзо» ба меҳмонон ҳисси бемислу монанди оромиш мебахшад. Ҳавлии меҳмонхона гӯшаи дилкаше бо гулороиҳои зебо, суфаҳои анъанавӣ (тахтҳо) ва шийпонҳо дар канори ҳавзҳои пур аз моҳиёни рангоранг аст, ки барои наҳорӣ ва хизматрасонии қаҳвахона фазои ором фароҳам меорад.\",\"type\":\"text\",\"version\":1}],\"direction\":null,\"format\":\"\",\"indent\":0,\"type\":\"paragraph\",\"version\":1,\"textFormat\":0,\"textStyle\":\"\"}],\"direction\":\"ltr\",\"format\":\"\",\"indent\":0,\"type\":\"root\",\"version\":1,\"textFormat\":1}}", "zh-CN": "{\"root\":{\"children\":[{\"children\":[{\"detail\":0,\"format\":1,\"mode\":\"normal\",\"style\":\"\",\"text\":\"阿布米尔扎传统精品酒店\",\"type\":\"text\",\"version\":1},{\"detail\":0,\"format\":0,\"mode\":\"normal\",\"style\":\"\",\"text\":\" 于2023年开业，由三栋建筑组成，共两层，设有15间客房，是一处优美的传统风格住所。这些典雅的建筑可追溯至巴列维王朝时期；改建为精品酒店后，经过了大规模的翻新与修复。酒店外立面令人联想到恺加王朝时期，室内设计则展现了正宗的伊朗-伊斯兰传统建筑风格。\",\"type\":\"text\",\"version\":1}],\"direction\":null,\"format\":\"\",\"indent\":0,\"type\":\"paragraph\",\"version\":1,\"textFormat\":0,\"textStyle\":\"\"},{\"children\":[{\"detail\":0,\"format\":0,\"mode\":\"normal\",\"style\":\"\",\"text\":\"阿布米尔扎精品酒店客房的灯光与室内设计为宾客带来无与伦比的宁静感。酒店庭院宛如一片温馨的绿洲，点缀着赏心悦目的花卉，设有传统坐榻（塔赫特）以及池塘边的凉亭，池中游弋着五彩斑斓的鱼儿，为享用早餐和咖啡提供了宁静的环境。\",\"type\":\"text\",\"version\":1}],\"direction\":null,\"format\":\"\",\"indent\":0,\"type\":\"paragraph\",\"version\":1,\"textFormat\":0,\"textStyle\":\"\"}],\"direction\":\"ltr\",\"format\":\"\",\"indent\":0,\"type\":\"root\",\"version\":1,\"textFormat\":1}}"}'::jsonb),
  ('{"root":{"children":[{"children":[{"detail":0,"format":0,"mode":"normal","style":"","text":"Al-Reza Madinah Hotel, the closest five-star hotel to the holy shrine of Imam Reza (AS) from the entrance of Shirazi Street, was opened in 2013 with an exceptionally beautiful environment, authentic Iranian architecture, and excellent design. With an 18-story structure and 325 modern suites and rooms, the hotel offers special amenities that will surely bring you complete satisfaction during your stay. Moreover, its prime location and proximity to the holy shrine double the joy of your pilgrimage. With an experienced and well-trained team, Al-Reza Madinah Hotel is proud to host you, our dear pilgrims and travelers.","type":"text","version":1}],"direction":null,"format":"","indent":0,"type":"paragraph","version":1,"textFormat":0,"textStyle":""}],"direction":"ltr","format":"","indent":0,"type":"root","version":1}}', '{"tr-TR": "{\"root\":{\"children\":[{\"children\":[{\"detail\":0,\"format\":0,\"mode\":\"normal\",\"style\":\"\",\"text\":\"Şirazi Caddesi girişinden İmam Rıza (a.s.) Türbesi''ne en yakın beş yıldızlı otel olan Al-Reza Madinah Oteli, 2013 yılında son derece güzel bir ortam, özgün İran mimarisi ve mükemmel bir tasarımla açıldı. 18 katlı yapısı ve 325 modern süit ve odasıyla otel, konaklamanız boyunca sizi tamamen memnun edecek özel olanaklar sunar. Ayrıca ayrıcalıklı konumu ve kutsal türbeye yakınlığı ziyaretinizin sevincini ikiye katlar. Deneyimli ve iyi eğitimli ekibiyle Al-Reza Madinah Oteli, siz değerli hacıları ve yolcuları ağırlamaktan gurur duyar.\",\"type\":\"text\",\"version\":1}],\"direction\":null,\"format\":\"\",\"indent\":0,\"type\":\"paragraph\",\"version\":1,\"textFormat\":0,\"textStyle\":\"\"}],\"direction\":\"ltr\",\"format\":\"\",\"indent\":0,\"type\":\"root\",\"version\":1}}", "es-ES": "{\"root\":{\"children\":[{\"children\":[{\"detail\":0,\"format\":0,\"mode\":\"normal\",\"style\":\"\",\"text\":\"El Hotel Al-Reza Madinah, el hotel de cinco estrellas más cercano al santuario del Imam Reza (la paz sea con él) desde la entrada de la calle Shirazi, abrió en 2013 con un entorno excepcionalmente bello, auténtica arquitectura iraní y un diseño excelente. Con una estructura de 18 plantas y 325 suites y habitaciones modernas, el hotel ofrece servicios especiales que sin duda le brindarán plena satisfacción durante su estancia. Además, su ubicación privilegiada y su proximidad al santuario duplican la alegría de su peregrinación. Con un equipo experimentado y bien formado, el Hotel Al-Reza Madinah se enorgullece de recibirle a usted, nuestro querido peregrino y viajero.\",\"type\":\"text\",\"version\":1}],\"direction\":null,\"format\":\"\",\"indent\":0,\"type\":\"paragraph\",\"version\":1,\"textFormat\":0,\"textStyle\":\"\"}],\"direction\":\"ltr\",\"format\":\"\",\"indent\":0,\"type\":\"root\",\"version\":1}}", "ku-KU": "{\"root\":{\"children\":[{\"children\":[{\"detail\":0,\"format\":0,\"mode\":\"normal\",\"style\":\"\",\"text\":\"هوتێلی مەدینەتولڕەزا، نزیکترین هوتێلی پێنج ئەستێرە لە حەرەمی پیرۆزی ئیمام ڕەزا (د.خ) لە دەروازەی شەقامی شیرازییەوە، لە ساڵی 2013 کرایەوە، بە ژینگەیەکی یەکجار جوان، تەلارسازیی ڕەسەنی ئێرانی و دیزاینێکی نایاب. ئەم هوتێلە بە بینایەکی 18 نهۆمی و 325 سویت و ژووری مۆدێرنەوە، ئاسانکاریی تایبەت پێشکەش دەکات کە بێگومان لە ماوەی مانەوەتدا ڕەزامەندیی تەواوت بۆ دەهێنێت. هەروەها، شوێنە نایابەکەی و نزیکییەکەی لە حەرەمی پیرۆز خۆشیی زیارەتەکەت دوو هێندە دەکات. هوتێلی مەدینەتولڕەزا بە تیمێکی شارەزا و ڕاهێنراوەوە، شانازی دەکات بە میوانداریی ئێوەی زائیر و گەشتیاری بەڕێز.\",\"type\":\"text\",\"version\":1}],\"direction\":null,\"format\":\"\",\"indent\":0,\"type\":\"paragraph\",\"version\":1,\"textFormat\":0,\"textStyle\":\"\"}],\"direction\":\"ltr\",\"format\":\"\",\"indent\":0,\"type\":\"root\",\"version\":1}}", "de-DE": "{\"root\":{\"children\":[{\"children\":[{\"detail\":0,\"format\":0,\"mode\":\"normal\",\"style\":\"\",\"text\":\"Das Al-Reza Madinah Hotel, das vom Eingang an der Schirazi-Straße aus nächstgelegene Fünf-Sterne-Hotel zum heiligen Schrein des Imam Reza (Friede sei mit ihm), wurde 2013 mit einem außergewöhnlich schönen Ambiente, authentischer iranischer Architektur und hervorragendem Design eröffnet. Mit 18 Stockwerken und 325 modernen Suiten und Zimmern bietet das Hotel besondere Annehmlichkeiten, die Ihren Aufenthalt rundum angenehm machen. Zudem verdoppeln die erstklassige Lage und die Nähe zum heiligen Schrein die Freude Ihrer Pilgerreise. Mit einem erfahrenen und gut geschulten Team freut sich das Al-Reza Madinah Hotel, Sie, unsere geschätzten Pilger und Reisenden, zu beherbergen.\",\"type\":\"text\",\"version\":1}],\"direction\":null,\"format\":\"\",\"indent\":0,\"type\":\"paragraph\",\"version\":1,\"textFormat\":0,\"textStyle\":\"\"}],\"direction\":\"ltr\",\"format\":\"\",\"indent\":0,\"type\":\"root\",\"version\":1}}", "fr-FR": "{\"root\":{\"children\":[{\"children\":[{\"detail\":0,\"format\":0,\"mode\":\"normal\",\"style\":\"\",\"text\":\"L’hôtel Al-Reza Madinah, l’hôtel cinq étoiles le plus proche du saint sanctuaire de l’Imam Reza (que la paix soit sur lui) depuis l’entrée de la rue Shirazi, a ouvert ses portes en 2013 dans un cadre exceptionnellement beau, avec une architecture iranienne authentique et un excellent design. Avec ses 18 étages et ses 325 suites et chambres modernes, l’hôtel propose des équipements spéciaux qui vous apporteront une entière satisfaction pendant votre séjour. De plus, son emplacement privilégié et sa proximité avec le saint sanctuaire doublent la joie de votre pèlerinage. Avec une équipe expérimentée et bien formée, l’hôtel Al-Reza Madinah est fier de vous accueillir, chers pèlerins et voyageurs.\",\"type\":\"text\",\"version\":1}],\"direction\":null,\"format\":\"\",\"indent\":0,\"type\":\"paragraph\",\"version\":1,\"textFormat\":0,\"textStyle\":\"\"}],\"direction\":\"ltr\",\"format\":\"\",\"indent\":0,\"type\":\"root\",\"version\":1}}", "ru-RU": "{\"root\":{\"children\":[{\"children\":[{\"detail\":0,\"format\":0,\"mode\":\"normal\",\"style\":\"\",\"text\":\"Отель «Аль-Реза Мадина» — ближайший к священному мавзолею имама Резы (мир ему) пятизвёздочный отель со стороны входа с улицы Ширази — открылся в 2013 году; его отличают исключительно красивая обстановка, подлинная иранская архитектура и превосходный дизайн. В 18-этажном здании 325 современных люксов и номеров, а особые удобства отеля непременно сделают ваше пребывание полностью комфортным. Кроме того, выгодное расположение и близость к святыне вдвойне умножают радость паломничества. Опытная и хорошо обученная команда отеля «Аль-Реза Мадина» с гордостью принимает вас, дорогие паломники и путешественники.\",\"type\":\"text\",\"version\":1}],\"direction\":null,\"format\":\"\",\"indent\":0,\"type\":\"paragraph\",\"version\":1,\"textFormat\":0,\"textStyle\":\"\"}],\"direction\":\"ltr\",\"format\":\"\",\"indent\":0,\"type\":\"root\",\"version\":1}}", "tg-TJ": "{\"root\":{\"children\":[{\"children\":[{\"detail\":0,\"format\":0,\"mode\":\"normal\",\"style\":\"\",\"text\":\"Меҳмонхонаи «Мадинаи Ар-Ризо», наздиктарин меҳмонхонаи панҷситора ба Ҳарами муқаддаси Имом Ризо (алайҳиссалом) аз даромади кӯчаи Шерозӣ, соли 2013 бо муҳити бениҳоят зебо, меъмории аслии эронӣ ва тарҳи олӣ кушода шуд. Ин меҳмонхона бо бинои 18-ошёна ва 325 сюиту ҳуҷраи замонавӣ шароити махсусе пешниҳод мекунад, ки бешубҳа шуморо дар давоми иқомат комилан қонеъ мегардонад. Илова бар ин, мавқеи беҳтарин ва наздикӣ ба Ҳарами муқаддас шодии зиёрати шуморо дучанд мекунад. Меҳмонхонаи «Мадинаи Ар-Ризо» бо дастаи ботаҷриба ва хуб омӯзонидашуда аз пазироии шумо, зоирону мусофирони азиз, ифтихор дорад.\",\"type\":\"text\",\"version\":1}],\"direction\":null,\"format\":\"\",\"indent\":0,\"type\":\"paragraph\",\"version\":1,\"textFormat\":0,\"textStyle\":\"\"}],\"direction\":\"ltr\",\"format\":\"\",\"indent\":0,\"type\":\"root\",\"version\":1}}", "zh-CN": "{\"root\":{\"children\":[{\"children\":[{\"detail\":0,\"format\":0,\"mode\":\"normal\",\"style\":\"\",\"text\":\"礼萨麦地那酒店是从设拉齐街入口前往伊玛目礼萨（愿主赐其平安）圣陵距离最近的五星级酒店，于2013年开业，环境极为优美，采用正宗的伊朗建筑风格，设计出色。酒店楼高18层，拥有325间现代化套房和客房，提供的特色设施定能让您在入住期间完全满意。此外，酒店地理位置优越，紧邻圣陵，让您的朝圣之旅倍添喜悦。礼萨麦地那酒店拥有一支经验丰富、训练有素的团队，竭诚欢迎尊贵的朝圣者和旅客。\",\"type\":\"text\",\"version\":1}],\"direction\":null,\"format\":\"\",\"indent\":0,\"type\":\"paragraph\",\"version\":1,\"textFormat\":0,\"textStyle\":\"\"}],\"direction\":\"ltr\",\"format\":\"\",\"indent\":0,\"type\":\"root\",\"version\":1}}"}'::jsonb),
  ('{"root":{"children":[{"children":[{"detail":0,"format":0,"mode":"normal","style":"","text":"Almas Hotel Mashhad opened in 2013 and was renovated in 2015 to improve the quality of services. This hotel is located in the vicinity of the Holy Shrine of Imam Reza (AS) on Imam Reza Street. The four-star Almas Hotel, with various rooms and equipped with the most modern amenities and facilities, featuring modern design and architecture, commemorates Iranian hospitality in a pleasant atmosphere. Among other features of this complex, one can mention the proximity to Reza Bazaar and 17 Shahrivar shopping centers, accessible in a very short time without the need for transportation. The hotel staff are proudly ready to host you, the pilgrims of the Holy Shrine of Ali ibn Musa al-Reza (AS).","type":"text","version":1}],"direction":null,"format":"","indent":0,"type":"paragraph","version":1,"textFormat":0,"textStyle":""},{"children":[],"direction":null,"format":"","indent":0,"type":"heading","version":1,"tag":"h3"}],"direction":"ltr","format":"","indent":0,"type":"root","version":1}}', '{"tr-TR": "{\"root\":{\"children\":[{\"children\":[{\"detail\":0,\"format\":0,\"mode\":\"normal\",\"style\":\"\",\"text\":\"Almas Otel Meşhed 2013''te açıldı ve hizmet kalitesini artırmak için 2015''te yenilendi. Otel, İmam Rıza Caddesi''nde, İmam Rıza (a.s.) Türbesi''nin yakınında yer alır. Çeşitli odaları, en modern olanak ve donanımları, modern tasarımı ve mimarisiyle dört yıldızlı Almas Otel, hoş bir atmosferde İran misafirperverliğini yaşatır. Kompleksin diğer özellikleri arasında, ulaşım aracına gerek kalmadan çok kısa sürede ulaşılabilen Rıza Çarşısı''na ve 17 Şehriver alışveriş merkezlerine yakınlığı sayılabilir. Otel personeli, siz Ali bin Musa er-Rıza (a.s.) Türbesi''nin ziyaretçilerini ağırlamaya gururla hazırdır.\",\"type\":\"text\",\"version\":1}],\"direction\":null,\"format\":\"\",\"indent\":0,\"type\":\"paragraph\",\"version\":1,\"textFormat\":0,\"textStyle\":\"\"},{\"children\":[],\"direction\":null,\"format\":\"\",\"indent\":0,\"type\":\"heading\",\"version\":1,\"tag\":\"h3\"}],\"direction\":\"ltr\",\"format\":\"\",\"indent\":0,\"type\":\"root\",\"version\":1}}", "es-ES": "{\"root\":{\"children\":[{\"children\":[{\"detail\":0,\"format\":0,\"mode\":\"normal\",\"style\":\"\",\"text\":\"El Hotel Almas Mashhad abrió en 2013 y se renovó en 2015 para mejorar la calidad de sus servicios. Este hotel se encuentra cerca del Santuario del Imam Reza (la paz sea con él), en la calle Imam Reza. El Hotel Almas, de cuatro estrellas, con habitaciones variadas y equipado con los servicios e instalaciones más modernos, y con un diseño y una arquitectura modernos, rinde homenaje a la hospitalidad iraní en un ambiente agradable. Entre otras características del complejo destaca su proximidad al Bazar Reza y a los centros comerciales 17 Shahrivar, a los que se llega en muy poco tiempo sin necesidad de transporte. El personal del hotel está orgullosamente dispuesto a recibirle a usted, peregrino del Santuario de Ali ibn Musa al-Reza (la paz sea con él).\",\"type\":\"text\",\"version\":1}],\"direction\":null,\"format\":\"\",\"indent\":0,\"type\":\"paragraph\",\"version\":1,\"textFormat\":0,\"textStyle\":\"\"},{\"children\":[],\"direction\":null,\"format\":\"\",\"indent\":0,\"type\":\"heading\",\"version\":1,\"tag\":\"h3\"}],\"direction\":\"ltr\",\"format\":\"\",\"indent\":0,\"type\":\"root\",\"version\":1}}", "ku-KU": "{\"root\":{\"children\":[{\"children\":[{\"detail\":0,\"format\":0,\"mode\":\"normal\",\"style\":\"\",\"text\":\"هوتێلی ئەلماسی مەشهەد لە ساڵی 2013 کرایەوە و لە ساڵی 2015 بۆ باشترکردنی کوالیتیی خزمەتگوزارییەکان نۆژەن کرایەوە. ئەم هوتێلە لە دراوسێیەتیی حەرەمی پیرۆزی ئیمام ڕەزا (د.خ) لە شەقامی ئیمام ڕەزا هەڵکەوتووە. هوتێلی چوار ئەستێرەی ئەلماس، بە ژووری جۆراوجۆر و پڕچەک بە مۆدێرنترین ئاسانکاری و کەرەستەکان، و بە دیزاین و تەلارسازیی مۆدێرن، میوانداریی ئێرانی لە کەشێکی خۆشدا زیندوو دەکاتەوە. لە تایبەتمەندییەکانی تری ئەم کۆمەڵگەیە دەتوانین ئاماژە بە نزیکی لە بازاڕی ڕەزا و ناوەندەکانی بازاڕکردنی 17ی شەهریوەر بکەین، کە لە ماوەیەکی زۆر کورتدا و بێ پێویستی بە هاتوچۆ دەگەیتە پێیان. ستافی هوتێلەکە بە شانازییەوە ئامادەن میوانداریی ئێوەی زائیرانی حەرەمی پیرۆزی عەلی کوڕی مووسا ئەلڕەزا (د.خ) بکەن.\",\"type\":\"text\",\"version\":1}],\"direction\":null,\"format\":\"\",\"indent\":0,\"type\":\"paragraph\",\"version\":1,\"textFormat\":0,\"textStyle\":\"\"},{\"children\":[],\"direction\":null,\"format\":\"\",\"indent\":0,\"type\":\"heading\",\"version\":1,\"tag\":\"h3\"}],\"direction\":\"ltr\",\"format\":\"\",\"indent\":0,\"type\":\"root\",\"version\":1}}", "de-DE": "{\"root\":{\"children\":[{\"children\":[{\"detail\":0,\"format\":0,\"mode\":\"normal\",\"style\":\"\",\"text\":\"Das Almas Hotel Maschhad wurde 2013 eröffnet und 2015 renoviert, um die Servicequalität zu verbessern. Das Hotel liegt in der Nähe des heiligen Schreins des Imam Reza (Friede sei mit ihm) an der Imam-Reza-Straße. Das Vier-Sterne-Hotel Almas mit verschiedenen Zimmertypen, modernster Ausstattung sowie modernem Design und moderner Architektur lässt in angenehmer Atmosphäre die iranische Gastfreundschaft aufleben. Zu den weiteren Vorzügen des Komplexes zählt die Nähe zum Reza-Basar und zu den Einkaufszentren an der 17-Schahriwar-Straße, die in kürzester Zeit ohne Verkehrsmittel erreichbar sind. Das Hotelpersonal freut sich, Sie, die Pilger des heiligen Schreins von Ali ibn Musa al-Reza (Friede sei mit ihm), zu beherbergen.\",\"type\":\"text\",\"version\":1}],\"direction\":null,\"format\":\"\",\"indent\":0,\"type\":\"paragraph\",\"version\":1,\"textFormat\":0,\"textStyle\":\"\"},{\"children\":[],\"direction\":null,\"format\":\"\",\"indent\":0,\"type\":\"heading\",\"version\":1,\"tag\":\"h3\"}],\"direction\":\"ltr\",\"format\":\"\",\"indent\":0,\"type\":\"root\",\"version\":1}}", "fr-FR": "{\"root\":{\"children\":[{\"children\":[{\"detail\":0,\"format\":0,\"mode\":\"normal\",\"style\":\"\",\"text\":\"L’hôtel Almas Mashhad a ouvert en 2013 et a été rénové en 2015 afin d’améliorer la qualité de ses services. Il est situé à proximité du saint sanctuaire de l’Imam Reza (que la paix soit sur lui), dans la rue Imam Reza. L’hôtel quatre étoiles Almas, avec ses différents types de chambres dotées des équipements les plus modernes, ainsi que son design et son architecture contemporains, perpétue l’hospitalité iranienne dans une atmosphère agréable. Parmi les autres atouts de ce complexe, citons la proximité du bazar Reza et des centres commerciaux de la rue 17 Shahrivar, accessibles en très peu de temps sans moyen de transport. Le personnel de l’hôtel est fier de vous accueillir, pèlerins du saint sanctuaire d’Ali ibn Musa al-Reza (que la paix soit sur lui).\",\"type\":\"text\",\"version\":1}],\"direction\":null,\"format\":\"\",\"indent\":0,\"type\":\"paragraph\",\"version\":1,\"textFormat\":0,\"textStyle\":\"\"},{\"children\":[],\"direction\":null,\"format\":\"\",\"indent\":0,\"type\":\"heading\",\"version\":1,\"tag\":\"h3\"}],\"direction\":\"ltr\",\"format\":\"\",\"indent\":0,\"type\":\"root\",\"version\":1}}", "ru-RU": "{\"root\":{\"children\":[{\"children\":[{\"detail\":0,\"format\":0,\"mode\":\"normal\",\"style\":\"\",\"text\":\"Отель «Алмас» в Мешхеде открылся в 2013 году и в 2015 году был реконструирован для повышения качества обслуживания. Отель расположен рядом со священным мавзолеем имама Резы (мир ему) на улице Имама Резы. Четырёхзвёздочный отель «Алмас» с разнообразными номерами, оснащёнными самыми современными удобствами, с современным дизайном и архитектурой, воплощает иранское гостеприимство в приятной атмосфере. Среди других особенностей комплекса — близость к базару Реза и торговым центрам «17 Шахривар», до которых можно очень быстро дойти без транспорта. Персонал отеля с гордостью готов принять вас, паломников священного мавзолея Али ибн Мусы ар-Резы (мир ему).\",\"type\":\"text\",\"version\":1}],\"direction\":null,\"format\":\"\",\"indent\":0,\"type\":\"paragraph\",\"version\":1,\"textFormat\":0,\"textStyle\":\"\"},{\"children\":[],\"direction\":null,\"format\":\"\",\"indent\":0,\"type\":\"heading\",\"version\":1,\"tag\":\"h3\"}],\"direction\":\"ltr\",\"format\":\"\",\"indent\":0,\"type\":\"root\",\"version\":1}}", "tg-TJ": "{\"root\":{\"children\":[{\"children\":[{\"detail\":0,\"format\":0,\"mode\":\"normal\",\"style\":\"\",\"text\":\"Меҳмонхонаи «Алмос»-и Машҳад соли 2013 кушода шуд ва соли 2015 барои баланд бардоштани сифати хизматрасонӣ таъмир гардид. Ин меҳмонхона дар ҳамсоягии Ҳарами муқаддаси Имом Ризо (алайҳиссалом) дар кӯчаи Имом Ризо ҷойгир аст. Меҳмонхонаи чорситораи «Алмос» бо ҳуҷраҳои гуногун, ки бо замонавитарин шароиту таҷҳизот муҷаҳҳаз буда, тарҳу меъмории муосир доранд, меҳмоннавозии эрониро дар фазои гуворо зинда мекунад. Аз дигар хусусиятҳои ин маҷмаа наздикӣ ба Бозори Ризо ва марказҳои савдои «17 Шаҳривар» аст, ки бе ниёз ба нақлиёт дар муддати хеле кӯтоҳ ба онҳо расидан мумкин аст. Кормандони меҳмонхона бо ифтихор омодаанд шуморо, зоирони Ҳарами муқаддаси Алӣ ибни Мусо ар-Ризо (алайҳиссалом), пазироӣ кунанд.\",\"type\":\"text\",\"version\":1}],\"direction\":null,\"format\":\"\",\"indent\":0,\"type\":\"paragraph\",\"version\":1,\"textFormat\":0,\"textStyle\":\"\"},{\"children\":[],\"direction\":null,\"format\":\"\",\"indent\":0,\"type\":\"heading\",\"version\":1,\"tag\":\"h3\"}],\"direction\":\"ltr\",\"format\":\"\",\"indent\":0,\"type\":\"root\",\"version\":1}}", "zh-CN": "{\"root\":{\"children\":[{\"children\":[{\"detail\":0,\"format\":0,\"mode\":\"normal\",\"style\":\"\",\"text\":\"马什哈德阿尔玛斯酒店于2013年开业，并于2015年进行翻新以提升服务质量。酒店位于伊玛目礼萨街，毗邻伊玛目礼萨（愿主赐其平安）圣陵。这家四星级阿尔玛斯酒店拥有多种类型的客房，配备最现代化的设施，设计和建筑风格时尚，在宜人的氛围中传承伊朗式的热情好客。酒店的另一大特色是靠近礼萨巴扎和十七沙赫里瓦尔购物中心，无需乘车即可在很短时间内到达。酒店员工竭诚欢迎前来朝拜阿里·伊本·穆萨·礼萨（愿主赐其平安）圣陵的朝圣者。\",\"type\":\"text\",\"version\":1}],\"direction\":null,\"format\":\"\",\"indent\":0,\"type\":\"paragraph\",\"version\":1,\"textFormat\":0,\"textStyle\":\"\"},{\"children\":[],\"direction\":null,\"format\":\"\",\"indent\":0,\"type\":\"heading\",\"version\":1,\"tag\":\"h3\"}],\"direction\":\"ltr\",\"format\":\"\",\"indent\":0,\"type\":\"root\",\"version\":1}}"}'::jsonb),
  ('{"root":{"children":[{"children":[{"detail":0,"format":0,"mode":"normal","style":"","text":"The 5-star, luxury Almas 2 Hotel, part of the Almas Hotel Group, opened in March 2017. With 217 rooms and special amenities, this 25-story hotel is inspired by the distinct architecture of various nations, featuring diverse styles such as Ancient Iranian, Russian, Turkish, Roman, African, Arabic, Persian, and Safavid, showcasing a museum of international arts. Almas 2 Hotel, with its experienced and trained staff, is proudly ready to host you, our dear guests.","type":"text","version":1}],"direction":null,"format":"","indent":0,"type":"paragraph","version":1,"textFormat":0,"textStyle":""},{"children":[],"direction":null,"format":"","indent":0,"type":"heading","version":1,"tag":"h3"}],"direction":"ltr","format":"","indent":0,"type":"root","version":1}}', '{"tr-TR": "{\"root\":{\"children\":[{\"children\":[{\"detail\":0,\"format\":0,\"mode\":\"normal\",\"style\":\"\",\"text\":\"Almas Otel Grubu''na ait 5 yıldızlı lüks Almas 2 Otel, Mart 2017''de açıldı. 217 odası ve özel olanaklarıyla 25 katlı bu otel, farklı milletlerin kendine özgü mimarisinden esinlenmiştir; Antik İran, Rus, Türk, Roma, Afrika, Arap, Fars ve Safevi gibi çeşitli üsluplarıyla adeta bir uluslararası sanatlar müzesi sunar. Deneyimli ve eğitimli personeliyle Almas 2 Otel, siz değerli misafirlerimizi gururla ağırlamaya hazırdır.\",\"type\":\"text\",\"version\":1}],\"direction\":null,\"format\":\"\",\"indent\":0,\"type\":\"paragraph\",\"version\":1,\"textFormat\":0,\"textStyle\":\"\"},{\"children\":[],\"direction\":null,\"format\":\"\",\"indent\":0,\"type\":\"heading\",\"version\":1,\"tag\":\"h3\"}],\"direction\":\"ltr\",\"format\":\"\",\"indent\":0,\"type\":\"root\",\"version\":1}}", "es-ES": "{\"root\":{\"children\":[{\"children\":[{\"detail\":0,\"format\":0,\"mode\":\"normal\",\"style\":\"\",\"text\":\"El lujoso Hotel Almas 2, de 5 estrellas y perteneciente al Grupo Hotelero Almas, abrió en marzo de 2017. Con 217 habitaciones y servicios especiales, este hotel de 25 plantas se inspira en la arquitectura característica de distintas naciones, con estilos tan diversos como el iraní antiguo, ruso, turco, romano, africano, árabe, persa y safávida, que lo convierten en un museo de artes internacionales. El Hotel Almas 2, con su personal experimentado y formado, está orgullosamente dispuesto a recibirle a usted, nuestro querido huésped.\",\"type\":\"text\",\"version\":1}],\"direction\":null,\"format\":\"\",\"indent\":0,\"type\":\"paragraph\",\"version\":1,\"textFormat\":0,\"textStyle\":\"\"},{\"children\":[],\"direction\":null,\"format\":\"\",\"indent\":0,\"type\":\"heading\",\"version\":1,\"tag\":\"h3\"}],\"direction\":\"ltr\",\"format\":\"\",\"indent\":0,\"type\":\"root\",\"version\":1}}", "ku-KU": "{\"root\":{\"children\":[{\"children\":[{\"detail\":0,\"format\":0,\"mode\":\"normal\",\"style\":\"\",\"text\":\"هوتێلی پێنج ئەستێرە و لۆکسی ئەلماس 2، سەر بە گرووپی هوتێلەکانی ئەلماس، لە مارتی 2017 کرایەوە. ئەم هوتێلە 25 نهۆمییە بە 217 ژوور و ئاسانکاریی تایبەتەوە، ئیلهامی لە تەلارسازیی جیاوازی نەتەوە جۆراوجۆرەکان وەرگرتووە و شێوازی جیاوازی وەک ئێرانی کۆن، ڕووسی، تورکی، ڕۆمانی، ئەفریقی، عەرەبی، فارسی و سەفەوی لەخۆ دەگرێت، و مۆزەخانەیەک لە هونەرە نێودەوڵەتییەکان نمایش دەکات. هوتێلی ئەلماس 2 بە ستافە شارەزا و ڕاهێنراوەکەیەوە، بە شانازییەوە ئامادەیە میوانداریی ئێوەی میوانی بەڕێز بکات.\",\"type\":\"text\",\"version\":1}],\"direction\":null,\"format\":\"\",\"indent\":0,\"type\":\"paragraph\",\"version\":1,\"textFormat\":0,\"textStyle\":\"\"},{\"children\":[],\"direction\":null,\"format\":\"\",\"indent\":0,\"type\":\"heading\",\"version\":1,\"tag\":\"h3\"}],\"direction\":\"ltr\",\"format\":\"\",\"indent\":0,\"type\":\"root\",\"version\":1}}", "de-DE": "{\"root\":{\"children\":[{\"children\":[{\"detail\":0,\"format\":0,\"mode\":\"normal\",\"style\":\"\",\"text\":\"Das luxuriöse 5-Sterne-Hotel Almas 2, Teil der Almas Hotel Group, wurde im März 2017 eröffnet. Mit 217 Zimmern und besonderen Annehmlichkeiten ist das 25-stöckige Hotel von der unverwechselbaren Architektur verschiedener Völker inspiriert und vereint Stile wie altiranisch, russisch, türkisch, römisch, afrikanisch, arabisch, persisch und safawidisch – ein Museum internationaler Kunst. Das Almas 2 Hotel mit seinem erfahrenen und geschulten Personal freut sich, Sie, unsere geschätzten Gäste, zu beherbergen.\",\"type\":\"text\",\"version\":1}],\"direction\":null,\"format\":\"\",\"indent\":0,\"type\":\"paragraph\",\"version\":1,\"textFormat\":0,\"textStyle\":\"\"},{\"children\":[],\"direction\":null,\"format\":\"\",\"indent\":0,\"type\":\"heading\",\"version\":1,\"tag\":\"h3\"}],\"direction\":\"ltr\",\"format\":\"\",\"indent\":0,\"type\":\"root\",\"version\":1}}", "fr-FR": "{\"root\":{\"children\":[{\"children\":[{\"detail\":0,\"format\":0,\"mode\":\"normal\",\"style\":\"\",\"text\":\"L’hôtel de luxe 5 étoiles Almas 2, qui fait partie du groupe Almas Hotel, a ouvert en mars 2017. Avec 217 chambres et des équipements spéciaux, cet hôtel de 25 étages s’inspire de l’architecture singulière de différents peuples et réunit des styles variés — iranien antique, russe, turc, romain, africain, arabe, persan et safavide — tel un musée des arts du monde. L’hôtel Almas 2, avec son personnel expérimenté et qualifié, est fier de vous accueillir, chers hôtes.\",\"type\":\"text\",\"version\":1}],\"direction\":null,\"format\":\"\",\"indent\":0,\"type\":\"paragraph\",\"version\":1,\"textFormat\":0,\"textStyle\":\"\"},{\"children\":[],\"direction\":null,\"format\":\"\",\"indent\":0,\"type\":\"heading\",\"version\":1,\"tag\":\"h3\"}],\"direction\":\"ltr\",\"format\":\"\",\"indent\":0,\"type\":\"root\",\"version\":1}}", "ru-RU": "{\"root\":{\"children\":[{\"children\":[{\"detail\":0,\"format\":0,\"mode\":\"normal\",\"style\":\"\",\"text\":\"Роскошный пятизвёздочный отель «Алмас 2», входящий в сеть отелей «Алмас», открылся в марте 2017 года. В 25-этажном отеле 217 номеров и особые удобства; его оформление вдохновлено самобытной архитектурой разных народов и сочетает разнообразные стили — древнеиранский, русский, турецкий, римский, африканский, арабский, персидский и сефевидский, — превращая отель в своего рода музей мирового искусства. Опытный и обученный персонал отеля «Алмас 2» с гордостью готов принять вас, дорогие гости.\",\"type\":\"text\",\"version\":1}],\"direction\":null,\"format\":\"\",\"indent\":0,\"type\":\"paragraph\",\"version\":1,\"textFormat\":0,\"textStyle\":\"\"},{\"children\":[],\"direction\":null,\"format\":\"\",\"indent\":0,\"type\":\"heading\",\"version\":1,\"tag\":\"h3\"}],\"direction\":\"ltr\",\"format\":\"\",\"indent\":0,\"type\":\"root\",\"version\":1}}", "tg-TJ": "{\"root\":{\"children\":[{\"children\":[{\"detail\":0,\"format\":0,\"mode\":\"normal\",\"style\":\"\",\"text\":\"Меҳмонхонаи панҷситора ва боҳашамати «Алмос 2» аз гурӯҳи меҳмонхонаҳои «Алмос» моҳи марти соли 2017 кушода шуд. Ин меҳмонхонаи 25-ошёна бо 217 ҳуҷра ва шароити махсус аз меъмории хоси халқҳои гуногун илҳом гирифта, услубҳои гуногун, аз ҷумла эронии бостонӣ, русӣ, туркӣ, румӣ, африқоӣ, арабӣ, форсӣ ва сафавиро дар бар мегирад ва ба мисли осорхонаи санъати ҷаҳонӣ аст. Меҳмонхонаи «Алмос 2» бо кормандони ботаҷриба ва омӯзонидашуда бо ифтихор омода аст шуморо, меҳмонони азиз, пазироӣ кунад.\",\"type\":\"text\",\"version\":1}],\"direction\":null,\"format\":\"\",\"indent\":0,\"type\":\"paragraph\",\"version\":1,\"textFormat\":0,\"textStyle\":\"\"},{\"children\":[],\"direction\":null,\"format\":\"\",\"indent\":0,\"type\":\"heading\",\"version\":1,\"tag\":\"h3\"}],\"direction\":\"ltr\",\"format\":\"\",\"indent\":0,\"type\":\"root\",\"version\":1}}", "zh-CN": "{\"root\":{\"children\":[{\"children\":[{\"detail\":0,\"format\":0,\"mode\":\"normal\",\"style\":\"\",\"text\":\"豪华五星级阿尔玛斯2号酒店隶属阿尔玛斯酒店集团，于2017年3月开业。这家25层的酒店拥有217间客房和特色设施，其设计灵感来自不同民族的独特建筑，融合了古伊朗、俄罗斯、土耳其、罗马、非洲、阿拉伯、波斯和萨法维等多种风格，宛如一座国际艺术博物馆。阿尔玛斯2号酒店拥有经验丰富、训练有素的员工，竭诚欢迎各位尊贵的宾客。\",\"type\":\"text\",\"version\":1}],\"direction\":null,\"format\":\"\",\"indent\":0,\"type\":\"paragraph\",\"version\":1,\"textFormat\":0,\"textStyle\":\"\"},{\"children\":[],\"direction\":null,\"format\":\"\",\"indent\":0,\"type\":\"heading\",\"version\":1,\"tag\":\"h3\"}],\"direction\":\"ltr\",\"format\":\"\",\"indent\":0,\"type\":\"root\",\"version\":1}}"}'::jsonb),
  ('{"root":{"children":[{"children":[{"detail":0,"format":0,"mode":"normal","style":"","text":"This center was established with ten suites equipped with general treatment and care equipment and ICU for long-term patient stays, so that patients can receive medical treatment and care in a home-like environment alongside their family members.","type":"text","version":1}],"direction":null,"format":"","indent":0,"type":"paragraph","version":1,"textFormat":0,"textStyle":""}],"direction":"ltr","format":"","indent":0,"type":"root","version":1}}', '{"tr-TR": "{\"root\":{\"children\":[{\"children\":[{\"detail\":0,\"format\":0,\"mode\":\"normal\",\"style\":\"\",\"text\":\"Bu merkez, uzun süreli hasta konaklamaları için genel tedavi ve bakım ekipmanlarıyla donatılmış on süit ve yoğun bakım ünitesiyle kurulmuştur; böylece hastalar, aile üyeleriyle birlikte ev ortamında tıbbi tedavi ve bakım alabilir.\",\"type\":\"text\",\"version\":1}],\"direction\":null,\"format\":\"\",\"indent\":0,\"type\":\"paragraph\",\"version\":1,\"textFormat\":0,\"textStyle\":\"\"}],\"direction\":\"ltr\",\"format\":\"\",\"indent\":0,\"type\":\"root\",\"version\":1}}", "es-ES": "{\"root\":{\"children\":[{\"children\":[{\"detail\":0,\"format\":0,\"mode\":\"normal\",\"style\":\"\",\"text\":\"Este centro se creó con diez suites equipadas con material de tratamiento y cuidados generales y UCI para estancias prolongadas de pacientes, de modo que puedan recibir tratamiento médico y cuidados en un entorno hogareño junto a sus familiares.\",\"type\":\"text\",\"version\":1}],\"direction\":null,\"format\":\"\",\"indent\":0,\"type\":\"paragraph\",\"version\":1,\"textFormat\":0,\"textStyle\":\"\"}],\"direction\":\"ltr\",\"format\":\"\",\"indent\":0,\"type\":\"root\",\"version\":1}}", "ku-KU": "{\"root\":{\"children\":[{\"children\":[{\"detail\":0,\"format\":0,\"mode\":\"normal\",\"style\":\"\",\"text\":\"ئەم ناوەندە بە دە سویتی پڕچەک بە کەرەستەی چارەسەر و چاودێریی گشتی و ICU بۆ مانەوەی درێژخایەنی نەخۆشەکان دامەزرا، بۆ ئەوەی نەخۆشەکان لە ژینگەیەکی وەک ماڵدا و لە تەنیشت ئەندامانی خێزانەکەیان چارەسەر و چاودێریی پزیشکی وەربگرن.\",\"type\":\"text\",\"version\":1}],\"direction\":null,\"format\":\"\",\"indent\":0,\"type\":\"paragraph\",\"version\":1,\"textFormat\":0,\"textStyle\":\"\"}],\"direction\":\"ltr\",\"format\":\"\",\"indent\":0,\"type\":\"root\",\"version\":1}}", "de-DE": "{\"root\":{\"children\":[{\"children\":[{\"detail\":0,\"format\":0,\"mode\":\"normal\",\"style\":\"\",\"text\":\"Diese Einrichtung wurde mit zehn Suiten gegründet, die mit allgemeiner Behandlungs- und Pflegeausstattung sowie Intensivstation für Langzeitaufenthalte von Patienten ausgestattet sind, damit Patienten in einer wohnlichen Umgebung an der Seite ihrer Angehörigen medizinisch behandelt und gepflegt werden können.\",\"type\":\"text\",\"version\":1}],\"direction\":null,\"format\":\"\",\"indent\":0,\"type\":\"paragraph\",\"version\":1,\"textFormat\":0,\"textStyle\":\"\"}],\"direction\":\"ltr\",\"format\":\"\",\"indent\":0,\"type\":\"root\",\"version\":1}}", "fr-FR": "{\"root\":{\"children\":[{\"children\":[{\"detail\":0,\"format\":0,\"mode\":\"normal\",\"style\":\"\",\"text\":\"Ce centre a été créé avec dix suites dotées d’équipements de soins et de traitement généraux ainsi que de soins intensifs pour les séjours de longue durée, afin que les patients puissent recevoir des soins médicaux dans un environnement chaleureux, aux côtés de leurs proches.\",\"type\":\"text\",\"version\":1}],\"direction\":null,\"format\":\"\",\"indent\":0,\"type\":\"paragraph\",\"version\":1,\"textFormat\":0,\"textStyle\":\"\"}],\"direction\":\"ltr\",\"format\":\"\",\"indent\":0,\"type\":\"root\",\"version\":1}}", "ru-RU": "{\"root\":{\"children\":[{\"children\":[{\"detail\":0,\"format\":0,\"mode\":\"normal\",\"style\":\"\",\"text\":\"Центр создан с десятью люксами, оснащёнными оборудованием для общего лечения и ухода, а также реанимационным оборудованием (ОРИТ) для длительного пребывания пациентов, чтобы они могли получать лечение и медицинский уход в домашней обстановке рядом с членами семьи.\",\"type\":\"text\",\"version\":1}],\"direction\":null,\"format\":\"\",\"indent\":0,\"type\":\"paragraph\",\"version\":1,\"textFormat\":0,\"textStyle\":\"\"}],\"direction\":\"ltr\",\"format\":\"\",\"indent\":0,\"type\":\"root\",\"version\":1}}", "tg-TJ": "{\"root\":{\"children\":[{\"children\":[{\"detail\":0,\"format\":0,\"mode\":\"normal\",\"style\":\"\",\"text\":\"Ин марказ бо даҳ сюит, ки бо таҷҳизоти табобат ва нигоҳубини умумӣ ва эҳёгарӣ (ICU) муҷаҳҳаз шудаанд, барои иқомати дарозмуддати беморон таъсис ёфтааст, то беморон дар муҳити хонагӣ дар канори аъзои оилаашон табобат ва нигоҳубини тиббӣ гиранд.\",\"type\":\"text\",\"version\":1}],\"direction\":null,\"format\":\"\",\"indent\":0,\"type\":\"paragraph\",\"version\":1,\"textFormat\":0,\"textStyle\":\"\"}],\"direction\":\"ltr\",\"format\":\"\",\"indent\":0,\"type\":\"root\",\"version\":1}}", "zh-CN": "{\"root\":{\"children\":[{\"children\":[{\"detail\":0,\"format\":0,\"mode\":\"normal\",\"style\":\"\",\"text\":\"本中心设有十间配备一般治疗与护理设备及ICU的套房，供患者长期入住，使患者能在家人陪伴下，于居家般的环境中接受治疗和医疗护理。\",\"type\":\"text\",\"version\":1}],\"direction\":null,\"format\":\"\",\"indent\":0,\"type\":\"paragraph\",\"version\":1,\"textFormat\":0,\"textStyle\":\"\"}],\"direction\":\"ltr\",\"format\":\"\",\"indent\":0,\"type\":\"root\",\"version\":1}}"}'::jsonb),
  ('{"root":{"children":[{"children":[{"detail":0,"format":1,"mode":"normal","style":"","text":"Firooze Toos Hotel (Tüs Turquoise Hotel) in Mashhad","type":"text","version":1},{"detail":0,"format":0,"mode":"normal","style":"","text":" is a three-star hotel located on Nawab Safavi Street in the city of Mashhad. Built in 2020, the hotel is only 600 meters from the entrance of Nawab Safavi to the holy shrine of Imam Reza (AS), making it easily accessible by a short walk. The hotel’s location also provides excellent access to Mashhad’s metro stations and railway station. The hotel features a total of 49 rooms and suites across 6 floors, offering city and shrine views. Elevators are available to reach the upper floors. The rooms are equipped with amenities such as free internet, television, air conditioning and heating systems, an air conditioner, a mini-bar (for a fee), a safe deposit box, a wardrobe, a tea maker, and furniture. The bathrooms are equipped with a shower, toiletries, a hairdryer, and either a traditional Iranian or a Western-style toilet.","type":"text","version":1}],"direction":null,"format":"","indent":0,"type":"paragraph","version":1,"textFormat":0,"textStyle":""}],"direction":"ltr","format":"","indent":0,"type":"root","version":1,"textFormat":1}}', '{"tr-TR": "{\"root\":{\"children\":[{\"children\":[{\"detail\":0,\"format\":1,\"mode\":\"normal\",\"style\":\"\",\"text\":\"Meşhed''deki Firooze Toos Oteli (Tus Turkuaz Oteli)\",\"type\":\"text\",\"version\":1},{\"detail\":0,\"format\":0,\"mode\":\"normal\",\"style\":\"\",\"text\":\" Meşhed şehrinde Navvab Safevi Caddesi''nde yer alan üç yıldızlı bir oteldir. 2020''de inşa edilen otel, Navvab Safevi girişinden İmam Rıza (a.s.) Türbesi''ne yalnızca 600 metre uzaklıktadır ve kısa bir yürüyüşle kolayca ulaşılabilir. Otelin konumu ayrıca Meşhed''in metro istasyonlarına ve tren istasyonuna mükemmel erişim sağlar. Otel, 6 katta şehir ve türbe manzaralı toplam 49 oda ve süite sahiptir. Üst katlara çıkmak için asansörler mevcuttur. Odalarda ücretsiz internet, televizyon, klima ve ısıtma sistemleri, vantilatörlü soğutucu, mini bar (ücretli), kasa, gardırop, çay makinesi ve mobilya gibi olanaklar bulunur. Banyolarda duş, banyo malzemeleri, saç kurutma makinesi ve alaturka ya da alafranga tuvalet bulunur.\",\"type\":\"text\",\"version\":1}],\"direction\":null,\"format\":\"\",\"indent\":0,\"type\":\"paragraph\",\"version\":1,\"textFormat\":0,\"textStyle\":\"\"}],\"direction\":\"ltr\",\"format\":\"\",\"indent\":0,\"type\":\"root\",\"version\":1,\"textFormat\":1}}", "es-ES": "{\"root\":{\"children\":[{\"children\":[{\"detail\":0,\"format\":1,\"mode\":\"normal\",\"style\":\"\",\"text\":\"El Hotel Firooze Toos (Hotel Turquesa de Tus) de Mashhad\",\"type\":\"text\",\"version\":1},{\"detail\":0,\"format\":0,\"mode\":\"normal\",\"style\":\"\",\"text\":\" es un hotel de tres estrellas situado en la calle Navab Safavi, en la ciudad de Mashhad. Construido en 2020, el hotel está a solo 600 metros de la entrada de Navab Safavi al santuario del Imam Reza (la paz sea con él), por lo que se llega fácilmente con un breve paseo. Su ubicación también ofrece un acceso excelente a las estaciones de metro y a la estación de tren de Mashhad. El hotel cuenta con un total de 49 habitaciones y suites repartidas en 6 plantas, con vistas a la ciudad y al santuario. Dispone de ascensores para acceder a las plantas superiores. Las habitaciones están equipadas con internet gratuito, televisión, sistemas de aire acondicionado y calefacción, un climatizador evaporativo, minibar (de pago), caja fuerte, armario, hervidor para té y mobiliario. Los baños disponen de ducha, artículos de aseo, secador de pelo e inodoro tradicional iraní u occidental.\",\"type\":\"text\",\"version\":1}],\"direction\":null,\"format\":\"\",\"indent\":0,\"type\":\"paragraph\",\"version\":1,\"textFormat\":0,\"textStyle\":\"\"}],\"direction\":\"ltr\",\"format\":\"\",\"indent\":0,\"type\":\"root\",\"version\":1,\"textFormat\":1}}", "ku-KU": "{\"root\":{\"children\":[{\"children\":[{\"detail\":0,\"format\":1,\"mode\":\"normal\",\"style\":\"\",\"text\":\"هوتێلی فیرۆزەی تووس (Tüs Turquoise Hotel) لە مەشهەد\",\"type\":\"text\",\"version\":1},{\"detail\":0,\"format\":0,\"mode\":\"normal\",\"style\":\"\",\"text\":\" هوتێلێکی سێ ئەستێرەیە لە شەقامی نەوابی سەفەویی شاری مەشهەد. ئەم هوتێلە لە ساڵی 2020 دروست کراوە و تەنها 600 مەتر لە دەروازەی نەوابی سەفەوی بۆ حەرەمی پیرۆزی ئیمام ڕەزا (د.خ) دوورە، بۆیە بە پیاسەیەکی کورت بە ئاسانی دەگەیتە حەرەم. شوێنی هوتێلەکە هەروەها دەستڕاگەیشتنێکی نایاب بە وێستگەکانی مێترۆی مەشهەد و وێستگەی شەمەندەفەر دابین دەکات. هوتێلەکە کۆی گشتی 49 ژوور و سویتی لە 6 نهۆمدا هەیە، بە دیمەنی شار و حەرەم. ئاسانسۆر بۆ گەیشتن بە نهۆمەکانی سەرەوە بەردەستە. ژوورەکان بە ئاسانکاریی وەک ئینتەرنێتی بەخۆڕایی، تەلەڤیزیۆن، سیستەمی فێنککەرەوە و گەرمکەرەوە، کولەر، مینی-بار (بە پارە)، سندوقی ئەمانەت، کەنتۆر، ئامێری چا دروستکردن و کەلوپەلی ناوماڵ پڕچەک کراون. گەرماوەکان شاوەر، کەرەستەی خاوێنی، ئامێری قژ وشککردنەوە و تەوالێتی ئێرانی یان فەرەنگییان تێدایە.\",\"type\":\"text\",\"version\":1}],\"direction\":null,\"format\":\"\",\"indent\":0,\"type\":\"paragraph\",\"version\":1,\"textFormat\":0,\"textStyle\":\"\"}],\"direction\":\"ltr\",\"format\":\"\",\"indent\":0,\"type\":\"root\",\"version\":1,\"textFormat\":1}}", "de-DE": "{\"root\":{\"children\":[{\"children\":[{\"detail\":0,\"format\":1,\"mode\":\"normal\",\"style\":\"\",\"text\":\"Das Firooze Toos Hotel (Türkis-Hotel Tus) in Maschhad\",\"type\":\"text\",\"version\":1},{\"detail\":0,\"format\":0,\"mode\":\"normal\",\"style\":\"\",\"text\":\" ist ein Drei-Sterne-Hotel an der Nawab-Safavi-Straße in Maschhad. Das 2020 erbaute Hotel liegt nur 600 Meter vom Eingang Nawab Safavi des heiligen Schreins des Imam Reza (Friede sei mit ihm) entfernt und ist so bequem zu Fuß erreichbar. Die Lage bietet zudem eine hervorragende Anbindung an die Metrostationen und den Bahnhof von Maschhad. Das Hotel verfügt über insgesamt 49 Zimmer und Suiten auf 6 Etagen mit Stadt- und Schreinblick. Aufzüge führen in die oberen Etagen. Die Zimmer sind unter anderem mit kostenfreiem Internet, Fernseher, Klima- und Heizungsanlage, einem Klimagerät, einer Minibar (gegen Gebühr), einem Safe, einem Kleiderschrank, einem Teekocher und Möbeln ausgestattet. Die Badezimmer verfügen über eine Dusche, Pflegeprodukte, einen Haartrockner und entweder eine traditionelle iranische oder eine westliche Toilette.\",\"type\":\"text\",\"version\":1}],\"direction\":null,\"format\":\"\",\"indent\":0,\"type\":\"paragraph\",\"version\":1,\"textFormat\":0,\"textStyle\":\"\"}],\"direction\":\"ltr\",\"format\":\"\",\"indent\":0,\"type\":\"root\",\"version\":1,\"textFormat\":1}}", "fr-FR": "{\"root\":{\"children\":[{\"children\":[{\"detail\":0,\"format\":1,\"mode\":\"normal\",\"style\":\"\",\"text\":\"L’hôtel Firooze Toos (Hôtel Turquoise de Tus) à Mashhad\",\"type\":\"text\",\"version\":1},{\"detail\":0,\"format\":0,\"mode\":\"normal\",\"style\":\"\",\"text\":\" est un hôtel trois étoiles situé dans la rue Nawab Safavi, à Mashhad. Construit en 2020, l’hôtel n’est qu’à 600 mètres de l’entrée Nawab Safavi du saint sanctuaire de l’Imam Reza (que la paix soit sur lui), ce qui permet de s’y rendre facilement à pied. Son emplacement offre également un excellent accès aux stations de métro et à la gare de Mashhad. L’hôtel compte au total 49 chambres et suites réparties sur 6 étages, avec vue sur la ville et sur le sanctuaire. Des ascenseurs desservent les étages supérieurs. Les chambres sont équipées notamment d’une connexion Internet gratuite, d’une télévision, de systèmes de climatisation et de chauffage, d’un climatiseur, d’un minibar (payant), d’un coffre-fort, d’une armoire, d’une bouilloire et de mobilier. Les salles de bains disposent d’une douche, d’articles de toilette, d’un sèche-cheveux et de toilettes soit à la turque, soit à l’occidentale.\",\"type\":\"text\",\"version\":1}],\"direction\":null,\"format\":\"\",\"indent\":0,\"type\":\"paragraph\",\"version\":1,\"textFormat\":0,\"textStyle\":\"\"}],\"direction\":\"ltr\",\"format\":\"\",\"indent\":0,\"type\":\"root\",\"version\":1,\"textFormat\":1}}", "ru-RU": "{\"root\":{\"children\":[{\"children\":[{\"detail\":0,\"format\":1,\"mode\":\"normal\",\"style\":\"\",\"text\":\"Отель «Фирузе Тус» (Бирюза Туса) в Мешхеде\",\"type\":\"text\",\"version\":1},{\"detail\":0,\"format\":0,\"mode\":\"normal\",\"style\":\"\",\"text\":\" — трёхзвёздочный отель на улице Наваб-Сафави в Мешхеде. Построенный в 2020 году, отель находится всего в 600 метрах от входа Наваб-Сафави в священный мавзолей имама Резы (мир ему), куда легко дойти пешком. Расположение отеля также обеспечивает отличный доступ к станциям метро и железнодорожному вокзалу Мешхеда. В отеле 49 номеров и люксов на 6 этажах с видом на город и святыню. На верхние этажи можно подняться на лифте. Номера оснащены бесплатным интернетом, телевизором, системами кондиционирования и отопления, кондиционером, мини-баром (платно), сейфом, шкафом, чайником и мебелью. В ванных комнатах есть душ, туалетные принадлежности, фен и традиционный иранский или европейский унитаз.\",\"type\":\"text\",\"version\":1}],\"direction\":null,\"format\":\"\",\"indent\":0,\"type\":\"paragraph\",\"version\":1,\"textFormat\":0,\"textStyle\":\"\"}],\"direction\":\"ltr\",\"format\":\"\",\"indent\":0,\"type\":\"root\",\"version\":1,\"textFormat\":1}}", "tg-TJ": "{\"root\":{\"children\":[{\"children\":[{\"detail\":0,\"format\":1,\"mode\":\"normal\",\"style\":\"\",\"text\":\"Меҳмонхонаи «Фирӯзаи Тӯс» дар Машҳад\",\"type\":\"text\",\"version\":1},{\"detail\":0,\"format\":0,\"mode\":\"normal\",\"style\":\"\",\"text\":\" меҳмонхонаи сеситорае мебошад, ки дар кӯчаи Навоб Сафавии шаҳри Машҳад ҷойгир аст. Ин меҳмонхона соли 2020 сохта шуда, ҳамагӣ 600 метр аз даромади Навоб Сафавии Ҳарами муқаддаси Имом Ризо (алайҳиссалом) дур аст ва бо пиёдагардии кӯтоҳ ба он расидан осон аст. Мавқеи меҳмонхона инчунин дастрасии хубро ба истгоҳҳои метро ва истгоҳи роҳи оҳани Машҳад таъмин мекунад. Меҳмонхона дар 6 ошёна ҳамагӣ 49 ҳуҷра ва сюит бо манзараи шаҳр ва Ҳарам дорад. Барои баромадан ба ошёнаҳои боло лифт мавҷуд аст. Ҳуҷраҳо бо интернети ройгон, телевизор, системаҳои кондитсионер ва гармидиҳӣ, ҳавосардкунак, минибар (пулакӣ), сейф, ҷевон, чойҷӯшак ва мебел муҷаҳҳаз мебошанд. Ҳаммомҳо душ, лавозимоти беҳдоштӣ, мӯйхушккунак ва ҳоҷатхонаи анъанавии эронӣ ё аврупоӣ доранд.\",\"type\":\"text\",\"version\":1}],\"direction\":null,\"format\":\"\",\"indent\":0,\"type\":\"paragraph\",\"version\":1,\"textFormat\":0,\"textStyle\":\"\"}],\"direction\":\"ltr\",\"format\":\"\",\"indent\":0,\"type\":\"root\",\"version\":1,\"textFormat\":1}}", "zh-CN": "{\"root\":{\"children\":[{\"children\":[{\"detail\":0,\"format\":1,\"mode\":\"normal\",\"style\":\"\",\"text\":\"马什哈德菲鲁泽图斯酒店（图斯绿松石酒店）\",\"type\":\"text\",\"version\":1},{\"detail\":0,\"format\":0,\"mode\":\"normal\",\"style\":\"\",\"text\":\" 是一家三星级酒店，位于马什哈德市纳瓦布·萨法维街。酒店建于2020年，距伊玛目礼萨（愿主赐其平安）圣陵的纳瓦布·萨法维入口仅600米，步行片刻即可到达。酒店的地理位置也便于前往马什哈德的各个地铁站和火车站。酒店共6层，设有49间客房和套房，可欣赏城市景观和圣陵景观，并配有电梯通往高层。客房配备免费网络、电视、冷暖空调系统、空调、迷你吧（收费）、保险箱、衣柜、泡茶设备和家具等设施。浴室配有淋浴、洗漱用品、吹风机，以及伊朗传统蹲式马桶或西式坐式马桶。\",\"type\":\"text\",\"version\":1}],\"direction\":null,\"format\":\"\",\"indent\":0,\"type\":\"paragraph\",\"version\":1,\"textFormat\":0,\"textStyle\":\"\"}],\"direction\":\"ltr\",\"format\":\"\",\"indent\":0,\"type\":\"root\",\"version\":1,\"textFormat\":1}}"}'::jsonb),
  ('{"root":{"children":[{"children":[{"detail":0,"format":0,"mode":"normal","style":"","text":"Harand Hotel, with more than ten years of experience, is one of the hotels built near the holy shrine of Imam Reza (peace be upon him), and was renovated in 2014. Among the advantages of this hotel are its proximity to shopping centers, commercial complexes, and the Haft-e Shahrivar Bazaar. Harand Hotel, with experienced and trained staff, is ready to welcome you, dear guests.","type":"text","version":1}],"direction":null,"format":"","indent":0,"type":"paragraph","version":1,"textFormat":0,"textStyle":""},{"children":[],"direction":null,"format":"","indent":0,"type":"heading","version":1,"tag":"h3"}],"direction":"ltr","format":"","indent":0,"type":"root","version":1}}', '{"tr-TR": "{\"root\":{\"children\":[{\"children\":[{\"detail\":0,\"format\":0,\"mode\":\"normal\",\"style\":\"\",\"text\":\"On yılı aşkın deneyime sahip Harand Oteli, İmam Rıza (a.s.) Türbesi yakınında inşa edilmiş otellerden biridir ve 2014''te yenilenmiştir. Bu otelin avantajları arasında alışveriş merkezlerine, ticari komplekslere ve Heft-i Şehriver Çarşısı''na yakınlığı sayılabilir. Deneyimli ve eğitimli personeliyle Harand Oteli, siz değerli misafirlerini ağırlamaya hazırdır.\",\"type\":\"text\",\"version\":1}],\"direction\":null,\"format\":\"\",\"indent\":0,\"type\":\"paragraph\",\"version\":1,\"textFormat\":0,\"textStyle\":\"\"},{\"children\":[],\"direction\":null,\"format\":\"\",\"indent\":0,\"type\":\"heading\",\"version\":1,\"tag\":\"h3\"}],\"direction\":\"ltr\",\"format\":\"\",\"indent\":0,\"type\":\"root\",\"version\":1}}", "es-ES": "{\"root\":{\"children\":[{\"children\":[{\"detail\":0,\"format\":0,\"mode\":\"normal\",\"style\":\"\",\"text\":\"El Hotel Harand, con más de diez años de experiencia, es uno de los hoteles construidos cerca del santuario del Imam Reza (la paz sea con él) y fue renovado en 2014. Entre las ventajas de este hotel se encuentra su proximidad a centros comerciales, complejos comerciales y el Bazar Haft-e Shahrivar. El Hotel Harand, con un personal experimentado y formado, está listo para recibirle a usted, querido huésped.\",\"type\":\"text\",\"version\":1}],\"direction\":null,\"format\":\"\",\"indent\":0,\"type\":\"paragraph\",\"version\":1,\"textFormat\":0,\"textStyle\":\"\"},{\"children\":[],\"direction\":null,\"format\":\"\",\"indent\":0,\"type\":\"heading\",\"version\":1,\"tag\":\"h3\"}],\"direction\":\"ltr\",\"format\":\"\",\"indent\":0,\"type\":\"root\",\"version\":1}}", "ku-KU": "{\"root\":{\"children\":[{\"children\":[{\"detail\":0,\"format\":0,\"mode\":\"normal\",\"style\":\"\",\"text\":\"هوتێلی هەرەند، بە زیاتر لە دە ساڵ ئەزموونەوە، یەکێکە لەو هوتێلانەی لە نزیک حەرەمی پیرۆزی ئیمام ڕەزا (د.خ) دروست کراون و لە ساڵی 2014 نۆژەن کرایەوە. لە سوودەکانی ئەم هوتێلە نزیکییەتی لە ناوەندەکانی بازاڕکردن، کۆمەڵگە بازرگانییەکان و بازاڕی حەفتی شەهریوەر. هوتێلی هەرەند بە ستافێکی شارەزا و ڕاهێنراوەوە، ئامادەیە پێشوازی لە ئێوەی میوانی بەڕێز بکات.\",\"type\":\"text\",\"version\":1}],\"direction\":null,\"format\":\"\",\"indent\":0,\"type\":\"paragraph\",\"version\":1,\"textFormat\":0,\"textStyle\":\"\"},{\"children\":[],\"direction\":null,\"format\":\"\",\"indent\":0,\"type\":\"heading\",\"version\":1,\"tag\":\"h3\"}],\"direction\":\"ltr\",\"format\":\"\",\"indent\":0,\"type\":\"root\",\"version\":1}}", "de-DE": "{\"root\":{\"children\":[{\"children\":[{\"detail\":0,\"format\":0,\"mode\":\"normal\",\"style\":\"\",\"text\":\"Das Harand Hotel blickt auf mehr als zehn Jahre Erfahrung zurück, gehört zu den Hotels nahe dem heiligen Schrein des Imam Reza (Friede sei mit ihm) und wurde 2014 renoviert. Zu den Vorzügen dieses Hotels zählt die Nähe zu Einkaufszentren, Geschäftskomplexen und dem Haft-e-Schahriwar-Basar. Das Harand Hotel mit seinem erfahrenen und geschulten Personal freut sich, Sie, liebe Gäste, willkommen zu heißen.\",\"type\":\"text\",\"version\":1}],\"direction\":null,\"format\":\"\",\"indent\":0,\"type\":\"paragraph\",\"version\":1,\"textFormat\":0,\"textStyle\":\"\"},{\"children\":[],\"direction\":null,\"format\":\"\",\"indent\":0,\"type\":\"heading\",\"version\":1,\"tag\":\"h3\"}],\"direction\":\"ltr\",\"format\":\"\",\"indent\":0,\"type\":\"root\",\"version\":1}}", "fr-FR": "{\"root\":{\"children\":[{\"children\":[{\"detail\":0,\"format\":0,\"mode\":\"normal\",\"style\":\"\",\"text\":\"L’hôtel Harand, fort de plus de dix ans d’expérience, fait partie des hôtels construits près du saint sanctuaire de l’Imam Reza (que la paix soit sur lui) et a été rénové en 2014. Parmi ses atouts figure sa proximité avec les centres commerciaux, les complexes commerciaux et le bazar Haft-e Shahrivar. L’hôtel Harand, avec son personnel expérimenté et qualifié, est prêt à vous accueillir, chers hôtes.\",\"type\":\"text\",\"version\":1}],\"direction\":null,\"format\":\"\",\"indent\":0,\"type\":\"paragraph\",\"version\":1,\"textFormat\":0,\"textStyle\":\"\"},{\"children\":[],\"direction\":null,\"format\":\"\",\"indent\":0,\"type\":\"heading\",\"version\":1,\"tag\":\"h3\"}],\"direction\":\"ltr\",\"format\":\"\",\"indent\":0,\"type\":\"root\",\"version\":1}}", "ru-RU": "{\"root\":{\"children\":[{\"children\":[{\"detail\":0,\"format\":0,\"mode\":\"normal\",\"style\":\"\",\"text\":\"Отель «Харанд», работающий более десяти лет, — один из отелей, построенных рядом со священным мавзолеем имама Резы (мир ему); в 2014 году он был реконструирован. Среди преимуществ отеля — близость к торговым центрам, коммерческим комплексам и базару Хафт-е Шахривар. Опытный и обученный персонал отеля «Харанд» готов встретить вас, дорогие гости.\",\"type\":\"text\",\"version\":1}],\"direction\":null,\"format\":\"\",\"indent\":0,\"type\":\"paragraph\",\"version\":1,\"textFormat\":0,\"textStyle\":\"\"},{\"children\":[],\"direction\":null,\"format\":\"\",\"indent\":0,\"type\":\"heading\",\"version\":1,\"tag\":\"h3\"}],\"direction\":\"ltr\",\"format\":\"\",\"indent\":0,\"type\":\"root\",\"version\":1}}", "tg-TJ": "{\"root\":{\"children\":[{\"children\":[{\"detail\":0,\"format\":0,\"mode\":\"normal\",\"style\":\"\",\"text\":\"Меҳмонхонаи «Ҳаранд» бо беш аз даҳ сол таҷриба яке аз меҳмонхонаҳоест, ки дар наздикии Ҳарами муқаддаси Имом Ризо (алайҳиссалом) сохта шудааст ва соли 2014 таъмир гардид. Аз бартариҳои ин меҳмонхона наздикӣ ба марказҳои савдо, маҷмааҳои тиҷоратӣ ва Бозори Ҳафти Шаҳривар мебошад. Меҳмонхонаи «Ҳаранд» бо кормандони ботаҷриба ва омӯзонидашуда омода аст шуморо, меҳмонони азиз, истиқбол гирад.\",\"type\":\"text\",\"version\":1}],\"direction\":null,\"format\":\"\",\"indent\":0,\"type\":\"paragraph\",\"version\":1,\"textFormat\":0,\"textStyle\":\"\"},{\"children\":[],\"direction\":null,\"format\":\"\",\"indent\":0,\"type\":\"heading\",\"version\":1,\"tag\":\"h3\"}],\"direction\":\"ltr\",\"format\":\"\",\"indent\":0,\"type\":\"root\",\"version\":1}}", "zh-CN": "{\"root\":{\"children\":[{\"children\":[{\"detail\":0,\"format\":0,\"mode\":\"normal\",\"style\":\"\",\"text\":\"哈兰德酒店拥有十余年经营经验，是伊玛目礼萨（愿主赐其平安）圣陵附近建造的酒店之一，并于2014年进行了翻新。本酒店的优势之一是靠近购物中心、商业综合体和十七沙赫里瓦尔巴扎。哈兰德酒店拥有经验丰富、训练有素的员工，竭诚欢迎各位尊贵的宾客。\",\"type\":\"text\",\"version\":1}],\"direction\":null,\"format\":\"\",\"indent\":0,\"type\":\"paragraph\",\"version\":1,\"textFormat\":0,\"textStyle\":\"\"},{\"children\":[],\"direction\":null,\"format\":\"\",\"indent\":0,\"type\":\"heading\",\"version\":1,\"tag\":\"h3\"}],\"direction\":\"ltr\",\"format\":\"\",\"indent\":0,\"type\":\"root\",\"version\":1}}"}'::jsonb),
  ('{"root":{"children":[{"children":[{"detail":0,"format":0,"mode":"normal","style":"","text":"Javaher Shargh Hotel in Mashhad was opened in 2014, in the vicinity of the holy shrine of Imam Reza (peace be upon him). This hotel complex consists of 7 floors and 53 rooms, offering desirable amenities in accordance with hospitality industry standards.","type":"text","version":1}],"direction":null,"format":"start","indent":0,"type":"paragraph","version":1,"textFormat":0,"textStyle":""},{"children":[{"detail":0,"format":0,"mode":"normal","style":"","text":"Located on one of the main streets leading to the holy shrine, the hotel provides guests with easy access to the shrine and also places them close to major shopping centers such as Reza Bazaar and Haft-e Shahrivar Bazaar.","type":"text","version":1}],"direction":null,"format":"start","indent":0,"type":"paragraph","version":1,"textFormat":0,"textStyle":""},{"children":[{"detail":0,"format":0,"mode":"normal","style":"","text":"The staff of Javaher Shargh Hotel are proud to welcome and host our valued guests and pilgrims.","type":"text","version":1}],"direction":null,"format":"start","indent":0,"type":"paragraph","version":1,"textFormat":0,"textStyle":""}],"direction":"ltr","format":"","indent":0,"type":"root","version":1}}', '{"tr-TR": "{\"root\":{\"children\":[{\"children\":[{\"detail\":0,\"format\":0,\"mode\":\"normal\",\"style\":\"\",\"text\":\"Meşhed''deki Javaher Shargh Oteli, 2014 yılında İmam Rıza (a.s.) Türbesi''nin yakınında açıldı. 7 kat ve 53 odadan oluşan bu otel kompleksi, otelcilik sektörü standartlarına uygun cazip olanaklar sunar.\",\"type\":\"text\",\"version\":1}],\"direction\":null,\"format\":\"start\",\"indent\":0,\"type\":\"paragraph\",\"version\":1,\"textFormat\":0,\"textStyle\":\"\"},{\"children\":[{\"detail\":0,\"format\":0,\"mode\":\"normal\",\"style\":\"\",\"text\":\"Kutsal türbeye giden ana caddelerden birinde yer alan otel, misafirlerine türbeye kolay erişim sağlar ve onları Rıza Çarşısı ve Heft-i Şehriver Çarşısı gibi büyük alışveriş merkezlerine de yakın tutar.\",\"type\":\"text\",\"version\":1}],\"direction\":null,\"format\":\"start\",\"indent\":0,\"type\":\"paragraph\",\"version\":1,\"textFormat\":0,\"textStyle\":\"\"},{\"children\":[{\"detail\":0,\"format\":0,\"mode\":\"normal\",\"style\":\"\",\"text\":\"Javaher Shargh Oteli personeli, değerli misafirlerimizi ve hacıları karşılamaktan ve ağırlamaktan gurur duyar.\",\"type\":\"text\",\"version\":1}],\"direction\":null,\"format\":\"start\",\"indent\":0,\"type\":\"paragraph\",\"version\":1,\"textFormat\":0,\"textStyle\":\"\"}],\"direction\":\"ltr\",\"format\":\"\",\"indent\":0,\"type\":\"root\",\"version\":1}}", "es-ES": "{\"root\":{\"children\":[{\"children\":[{\"detail\":0,\"format\":0,\"mode\":\"normal\",\"style\":\"\",\"text\":\"El Hotel Javaher Shargh de Mashhad abrió en 2014 cerca del santuario del Imam Reza (la paz sea con él). Este complejo hotelero consta de 7 plantas y 53 habitaciones, y ofrece servicios atractivos conforme a los estándares del sector hotelero.\",\"type\":\"text\",\"version\":1}],\"direction\":null,\"format\":\"start\",\"indent\":0,\"type\":\"paragraph\",\"version\":1,\"textFormat\":0,\"textStyle\":\"\"},{\"children\":[{\"detail\":0,\"format\":0,\"mode\":\"normal\",\"style\":\"\",\"text\":\"Situado en una de las calles principales que conducen al santuario, el hotel ofrece a los huéspedes un fácil acceso al santuario y los sitúa cerca de grandes centros comerciales como el Bazar Reza y el Bazar Haft-e Shahrivar.\",\"type\":\"text\",\"version\":1}],\"direction\":null,\"format\":\"start\",\"indent\":0,\"type\":\"paragraph\",\"version\":1,\"textFormat\":0,\"textStyle\":\"\"},{\"children\":[{\"detail\":0,\"format\":0,\"mode\":\"normal\",\"style\":\"\",\"text\":\"El personal del Hotel Javaher Shargh se enorgullece de dar la bienvenida y recibir a nuestros apreciados huéspedes y peregrinos.\",\"type\":\"text\",\"version\":1}],\"direction\":null,\"format\":\"start\",\"indent\":0,\"type\":\"paragraph\",\"version\":1,\"textFormat\":0,\"textStyle\":\"\"}],\"direction\":\"ltr\",\"format\":\"\",\"indent\":0,\"type\":\"root\",\"version\":1}}", "ku-KU": "{\"root\":{\"children\":[{\"children\":[{\"detail\":0,\"format\":0,\"mode\":\"normal\",\"style\":\"\",\"text\":\"هوتێلی جەواهیری شەرقی مەشهەد لە ساڵی 2014 لە دراوسێیەتیی حەرەمی پیرۆزی ئیمام ڕەزا (د.خ) کرایەوە. ئەم کۆمەڵگە هوتێلییە لە 7 نهۆم و 53 ژوور پێکهاتووە و ئاسانکاریی گونجاو بەپێی ستانداردەکانی پیشەسازیی هوتێلداری پێشکەش دەکات.\",\"type\":\"text\",\"version\":1}],\"direction\":null,\"format\":\"start\",\"indent\":0,\"type\":\"paragraph\",\"version\":1,\"textFormat\":0,\"textStyle\":\"\"},{\"children\":[{\"detail\":0,\"format\":0,\"mode\":\"normal\",\"style\":\"\",\"text\":\"هوتێلەکە لە یەکێک لە شەقامە سەرەکییەکانی ڕێگای حەرەمی پیرۆزدا هەڵکەوتووە، بۆیە میوانان بە ئاسانی دەگەنە حەرەم و هەروەها نزیکن لە ناوەندە گەورەکانی بازاڕکردن وەک بازاڕی ڕەزا و بازاڕی حەفتی شەهریوەر.\",\"type\":\"text\",\"version\":1}],\"direction\":null,\"format\":\"start\",\"indent\":0,\"type\":\"paragraph\",\"version\":1,\"textFormat\":0,\"textStyle\":\"\"},{\"children\":[{\"detail\":0,\"format\":0,\"mode\":\"normal\",\"style\":\"\",\"text\":\"ستافی هوتێلی جەواهیری شەرق شانازی دەکەن بە پێشوازی و میوانداریی میوانان و زائیرانی بەڕێزمان.\",\"type\":\"text\",\"version\":1}],\"direction\":null,\"format\":\"start\",\"indent\":0,\"type\":\"paragraph\",\"version\":1,\"textFormat\":0,\"textStyle\":\"\"}],\"direction\":\"ltr\",\"format\":\"\",\"indent\":0,\"type\":\"root\",\"version\":1}}", "de-DE": "{\"root\":{\"children\":[{\"children\":[{\"detail\":0,\"format\":0,\"mode\":\"normal\",\"style\":\"\",\"text\":\"Das Javaher Shargh Hotel in Maschhad wurde 2014 in der Nähe des heiligen Schreins des Imam Reza (Friede sei mit ihm) eröffnet. Der Hotelkomplex umfasst 7 Etagen und 53 Zimmer und bietet angenehme Annehmlichkeiten gemäß den Standards der Hotellerie.\",\"type\":\"text\",\"version\":1}],\"direction\":null,\"format\":\"start\",\"indent\":0,\"type\":\"paragraph\",\"version\":1,\"textFormat\":0,\"textStyle\":\"\"},{\"children\":[{\"detail\":0,\"format\":0,\"mode\":\"normal\",\"style\":\"\",\"text\":\"Dank seiner Lage an einer der Hauptstraßen, die zum heiligen Schrein führen, haben die Gäste einen bequemen Zugang zum Schrein und sind zugleich nahe an großen Einkaufszentren wie dem Reza-Basar und dem Haft-e-Schahriwar-Basar.\",\"type\":\"text\",\"version\":1}],\"direction\":null,\"format\":\"start\",\"indent\":0,\"type\":\"paragraph\",\"version\":1,\"textFormat\":0,\"textStyle\":\"\"},{\"children\":[{\"detail\":0,\"format\":0,\"mode\":\"normal\",\"style\":\"\",\"text\":\"Das Team des Javaher Shargh Hotels freut sich, unsere geschätzten Gäste und Pilger willkommen zu heißen und zu beherbergen.\",\"type\":\"text\",\"version\":1}],\"direction\":null,\"format\":\"start\",\"indent\":0,\"type\":\"paragraph\",\"version\":1,\"textFormat\":0,\"textStyle\":\"\"}],\"direction\":\"ltr\",\"format\":\"\",\"indent\":0,\"type\":\"root\",\"version\":1}}", "fr-FR": "{\"root\":{\"children\":[{\"children\":[{\"detail\":0,\"format\":0,\"mode\":\"normal\",\"style\":\"\",\"text\":\"L’hôtel Javaher Shargh à Mashhad a ouvert en 2014 à proximité du saint sanctuaire de l’Imam Reza (que la paix soit sur lui). Ce complexe hôtelier compte 7 étages et 53 chambres et offre des équipements agréables conformes aux normes de l’hôtellerie.\",\"type\":\"text\",\"version\":1}],\"direction\":null,\"format\":\"start\",\"indent\":0,\"type\":\"paragraph\",\"version\":1,\"textFormat\":0,\"textStyle\":\"\"},{\"children\":[{\"detail\":0,\"format\":0,\"mode\":\"normal\",\"style\":\"\",\"text\":\"Situé sur l’une des principales rues menant au saint sanctuaire, l’hôtel offre à ses hôtes un accès facile au sanctuaire et les place également à proximité de grands centres commerciaux comme le bazar Reza et le bazar Haft-e Shahrivar.\",\"type\":\"text\",\"version\":1}],\"direction\":null,\"format\":\"start\",\"indent\":0,\"type\":\"paragraph\",\"version\":1,\"textFormat\":0,\"textStyle\":\"\"},{\"children\":[{\"detail\":0,\"format\":0,\"mode\":\"normal\",\"style\":\"\",\"text\":\"Le personnel de l’hôtel Javaher Shargh est fier d’accueillir nos chers hôtes et pèlerins.\",\"type\":\"text\",\"version\":1}],\"direction\":null,\"format\":\"start\",\"indent\":0,\"type\":\"paragraph\",\"version\":1,\"textFormat\":0,\"textStyle\":\"\"}],\"direction\":\"ltr\",\"format\":\"\",\"indent\":0,\"type\":\"root\",\"version\":1}}", "ru-RU": "{\"root\":{\"children\":[{\"children\":[{\"detail\":0,\"format\":0,\"mode\":\"normal\",\"style\":\"\",\"text\":\"Отель «Джавахер Шарг» в Мешхеде открылся в 2014 году рядом со священным мавзолеем имама Резы (мир ему). Комплекс состоит из 7 этажей и 53 номеров и предлагает хорошие удобства в соответствии со стандартами гостиничной индустрии.\",\"type\":\"text\",\"version\":1}],\"direction\":null,\"format\":\"start\",\"indent\":0,\"type\":\"paragraph\",\"version\":1,\"textFormat\":0,\"textStyle\":\"\"},{\"children\":[{\"detail\":0,\"format\":0,\"mode\":\"normal\",\"style\":\"\",\"text\":\"Отель расположен на одной из главных улиц, ведущих к святыне, поэтому гости легко добираются до мавзолея, а рядом находятся крупные торговые центры, такие как базар Реза и базар Хафт-е Шахривар.\",\"type\":\"text\",\"version\":1}],\"direction\":null,\"format\":\"start\",\"indent\":0,\"type\":\"paragraph\",\"version\":1,\"textFormat\":0,\"textStyle\":\"\"},{\"children\":[{\"detail\":0,\"format\":0,\"mode\":\"normal\",\"style\":\"\",\"text\":\"Персонал отеля «Джавахер Шарг» с гордостью встречает и принимает наших дорогих гостей и паломников.\",\"type\":\"text\",\"version\":1}],\"direction\":null,\"format\":\"start\",\"indent\":0,\"type\":\"paragraph\",\"version\":1,\"textFormat\":0,\"textStyle\":\"\"}],\"direction\":\"ltr\",\"format\":\"\",\"indent\":0,\"type\":\"root\",\"version\":1}}", "tg-TJ": "{\"root\":{\"children\":[{\"children\":[{\"detail\":0,\"format\":0,\"mode\":\"normal\",\"style\":\"\",\"text\":\"Меҳмонхонаи «Ҷавоҳири Шарқ» дар Машҳад соли 2014 дар ҳамсоягии Ҳарами муқаддаси Имом Ризо (алайҳиссалом) кушода шуд. Ин маҷмаа аз 7 ошёна ва 53 ҳуҷра иборат буда, шароити мувофиқ ба стандартҳои соҳаи меҳмондориро пешниҳод мекунад.\",\"type\":\"text\",\"version\":1}],\"direction\":null,\"format\":\"start\",\"indent\":0,\"type\":\"paragraph\",\"version\":1,\"textFormat\":0,\"textStyle\":\"\"},{\"children\":[{\"detail\":0,\"format\":0,\"mode\":\"normal\",\"style\":\"\",\"text\":\"Меҳмонхона дар яке аз кӯчаҳои асосие, ки ба Ҳарам мебаранд, ҷойгир буда, ба меҳмонон дастрасии осон ба Ҳарамро фароҳам меорад ва онҳоро ба марказҳои бузурги савдо, монанди Бозори Ризо ва Бозори Ҳафти Шаҳривар, наздик мегардонад.\",\"type\":\"text\",\"version\":1}],\"direction\":null,\"format\":\"start\",\"indent\":0,\"type\":\"paragraph\",\"version\":1,\"textFormat\":0,\"textStyle\":\"\"},{\"children\":[{\"detail\":0,\"format\":0,\"mode\":\"normal\",\"style\":\"\",\"text\":\"Кормандони меҳмонхонаи «Ҷавоҳири Шарқ» аз истиқбол ва пазироии меҳмонону зоирони гиромии мо ифтихор доранд.\",\"type\":\"text\",\"version\":1}],\"direction\":null,\"format\":\"start\",\"indent\":0,\"type\":\"paragraph\",\"version\":1,\"textFormat\":0,\"textStyle\":\"\"}],\"direction\":\"ltr\",\"format\":\"\",\"indent\":0,\"type\":\"root\",\"version\":1}}", "zh-CN": "{\"root\":{\"children\":[{\"children\":[{\"detail\":0,\"format\":0,\"mode\":\"normal\",\"style\":\"\",\"text\":\"马什哈德贾瓦赫沙尔格酒店于2014年开业，毗邻伊玛目礼萨（愿主赐其平安）圣陵。酒店共7层，设有53间客房，提供符合酒店业标准的完善设施。\",\"type\":\"text\",\"version\":1}],\"direction\":null,\"format\":\"start\",\"indent\":0,\"type\":\"paragraph\",\"version\":1,\"textFormat\":0,\"textStyle\":\"\"},{\"children\":[{\"detail\":0,\"format\":0,\"mode\":\"normal\",\"style\":\"\",\"text\":\"酒店位于通往圣陵的主要街道之一，宾客可便捷前往圣陵，同时靠近礼萨巴扎和十七沙赫里瓦尔巴扎等大型购物中心。\",\"type\":\"text\",\"version\":1}],\"direction\":null,\"format\":\"start\",\"indent\":0,\"type\":\"paragraph\",\"version\":1,\"textFormat\":0,\"textStyle\":\"\"},{\"children\":[{\"detail\":0,\"format\":0,\"mode\":\"normal\",\"style\":\"\",\"text\":\"贾瓦赫沙尔格酒店全体员工竭诚欢迎并接待各位尊贵的宾客和朝圣者。\",\"type\":\"text\",\"version\":1}],\"direction\":null,\"format\":\"start\",\"indent\":0,\"type\":\"paragraph\",\"version\":1,\"textFormat\":0,\"textStyle\":\"\"}],\"direction\":\"ltr\",\"format\":\"\",\"indent\":0,\"type\":\"root\",\"version\":1}}"}'::jsonb),
  ('{"root":{"children":[{"children":[{"detail":0,"format":0,"mode":"normal","style":"","text":"The two-star Javaheri Hotel in Mashhad is located on Imam Reza Street. The complex was opened in 1979 and underwent a complete renovation in 2015. Among its best advantages are its proximity to the holy shrine of Imam Reza and easy access to commercial and shopping centers. The Javaheri Hotel, with 5 rooms and 65 accommodation units and experienced and trained staff, is ready to serve you dear guests of His Holiness, the Eighth Imam (peace be upon him).","type":"text","version":1}],"direction":null,"format":"","indent":0,"type":"paragraph","version":1,"textFormat":0,"textStyle":""}],"direction":"ltr","format":"","indent":0,"type":"root","version":1}}', '{"tr-TR": "{\"root\":{\"children\":[{\"children\":[{\"detail\":0,\"format\":0,\"mode\":\"normal\",\"style\":\"\",\"text\":\"İki yıldızlı Javaheri Oteli, Meşhed''de İmam Rıza Caddesi''nde yer alır. Kompleks 1979''da açıldı ve 2015''te tamamen yenilendi. En büyük avantajları arasında İmam Rıza Türbesi''ne yakınlığı ve ticari merkezlere ve alışveriş merkezlerine kolay erişimi sayılabilir. 5 oda ve 65 konaklama birimi ile deneyimli ve eğitimli personeliyle Javaheri Oteli, Hz. Sekizinci İmam''ın (a.s.) siz değerli misafirlerine hizmet etmeye hazırdır.\",\"type\":\"text\",\"version\":1}],\"direction\":null,\"format\":\"\",\"indent\":0,\"type\":\"paragraph\",\"version\":1,\"textFormat\":0,\"textStyle\":\"\"}],\"direction\":\"ltr\",\"format\":\"\",\"indent\":0,\"type\":\"root\",\"version\":1}}", "es-ES": "{\"root\":{\"children\":[{\"children\":[{\"detail\":0,\"format\":0,\"mode\":\"normal\",\"style\":\"\",\"text\":\"El Hotel Javaheri, de dos estrellas, se encuentra en la calle Imam Reza de Mashhad. El complejo abrió en 1979 y se renovó por completo en 2015. Entre sus mejores ventajas están su proximidad al santuario del Imam Reza y el fácil acceso a centros comerciales y de negocios. El Hotel Javaheri, con 5 habitaciones y 65 unidades de alojamiento y un personal experimentado y formado, está listo para atenderle a usted, querido huésped de Su Santidad el Octavo Imam (la paz sea con él).\",\"type\":\"text\",\"version\":1}],\"direction\":null,\"format\":\"\",\"indent\":0,\"type\":\"paragraph\",\"version\":1,\"textFormat\":0,\"textStyle\":\"\"}],\"direction\":\"ltr\",\"format\":\"\",\"indent\":0,\"type\":\"root\",\"version\":1}}", "ku-KU": "{\"root\":{\"children\":[{\"children\":[{\"detail\":0,\"format\":0,\"mode\":\"normal\",\"style\":\"\",\"text\":\"هوتێلی دوو ئەستێرەی جەواهیری لە مەشهەد لە شەقامی ئیمام ڕەزا هەڵکەوتووە. ئەم کۆمەڵگەیە لە ساڵی 1979 کرایەوە و لە ساڵی 2015 بە تەواوی نۆژەن کرایەوە. لە باشترین سوودەکانی نزیکییەتی لە حەرەمی پیرۆزی ئیمام ڕەزا و دەستڕاگەیشتنی ئاسان بە ناوەندە بازرگانی و بازاڕکردنەکان. هوتێلی جەواهیری بە 5 ژوور و 65 یەکەی مانەوە و ستافێکی شارەزا و ڕاهێنراوەوە، ئامادەیە خزمەتی ئێوەی میوانی بەڕێزی حەزرەتی ئیمامی هەشتەم (د.خ) بکات.\",\"type\":\"text\",\"version\":1}],\"direction\":null,\"format\":\"\",\"indent\":0,\"type\":\"paragraph\",\"version\":1,\"textFormat\":0,\"textStyle\":\"\"}],\"direction\":\"ltr\",\"format\":\"\",\"indent\":0,\"type\":\"root\",\"version\":1}}", "de-DE": "{\"root\":{\"children\":[{\"children\":[{\"detail\":0,\"format\":0,\"mode\":\"normal\",\"style\":\"\",\"text\":\"Das Zwei-Sterne-Hotel Javaheri in Maschhad liegt an der Imam-Reza-Straße. Der Komplex wurde 1979 eröffnet und 2015 vollständig renoviert. Zu seinen größten Vorzügen zählen die Nähe zum heiligen Schrein des Imam Reza und der bequeme Zugang zu Geschäfts- und Einkaufszentren. Das Javaheri Hotel mit 5 Zimmern und 65 Wohneinheiten sowie erfahrenem und geschultem Personal steht Ihnen, liebe Gäste Seiner Heiligkeit, des Achten Imams (Friede sei mit ihm), gern zu Diensten.\",\"type\":\"text\",\"version\":1}],\"direction\":null,\"format\":\"\",\"indent\":0,\"type\":\"paragraph\",\"version\":1,\"textFormat\":0,\"textStyle\":\"\"}],\"direction\":\"ltr\",\"format\":\"\",\"indent\":0,\"type\":\"root\",\"version\":1}}", "fr-FR": "{\"root\":{\"children\":[{\"children\":[{\"detail\":0,\"format\":0,\"mode\":\"normal\",\"style\":\"\",\"text\":\"L’hôtel deux étoiles Javaheri à Mashhad est situé dans la rue Imam Reza. Le complexe a ouvert en 1979 et a été entièrement rénové en 2015. Parmi ses meilleurs atouts figurent sa proximité avec le saint sanctuaire de l’Imam Reza et un accès facile aux centres commerciaux. L’hôtel Javaheri, avec 5 chambres et 65 unités d’hébergement ainsi qu’un personnel expérimenté et qualifié, est prêt à vous servir, chers hôtes de Sa Sainteté le huitième Imam (que la paix soit sur lui).\",\"type\":\"text\",\"version\":1}],\"direction\":null,\"format\":\"\",\"indent\":0,\"type\":\"paragraph\",\"version\":1,\"textFormat\":0,\"textStyle\":\"\"}],\"direction\":\"ltr\",\"format\":\"\",\"indent\":0,\"type\":\"root\",\"version\":1}}", "ru-RU": "{\"root\":{\"children\":[{\"children\":[{\"detail\":0,\"format\":0,\"mode\":\"normal\",\"style\":\"\",\"text\":\"Двухзвёздочный отель «Джавахери» в Мешхеде расположен на улице Имама Резы. Комплекс открылся в 1979 году и в 2015 году прошёл полную реконструкцию. Среди его главных преимуществ — близость к священному мавзолею имама Резы и удобный доступ к коммерческим и торговым центрам. Отель «Джавахери» с 5 номерами и 65 жилыми единицами и опытным, обученным персоналом готов служить вам, дорогие гости восьмого имама (мир ему).\",\"type\":\"text\",\"version\":1}],\"direction\":null,\"format\":\"\",\"indent\":0,\"type\":\"paragraph\",\"version\":1,\"textFormat\":0,\"textStyle\":\"\"}],\"direction\":\"ltr\",\"format\":\"\",\"indent\":0,\"type\":\"root\",\"version\":1}}", "tg-TJ": "{\"root\":{\"children\":[{\"children\":[{\"detail\":0,\"format\":0,\"mode\":\"normal\",\"style\":\"\",\"text\":\"Меҳмонхонаи дуситораи «Ҷавоҳирӣ» дар Машҳад дар кӯчаи Имом Ризо ҷойгир аст. Ин маҷмаа соли 1979 кушода шуда, соли 2015 пурра таъмир гардид. Аз беҳтарин бартариҳои он наздикӣ ба Ҳарами муқаддаси Имом Ризо ва дастрасии осон ба марказҳои тиҷоратию савдо мебошад. Меҳмонхонаи «Ҷавоҳирӣ» бо 5 ҳуҷра ва 65 воҳиди иқоматӣ ва кормандони ботаҷрибаву омӯзонидашуда омода аст ба шумо, меҳмонони азизи Ҳазрати Имоми ҳаштум (алайҳиссалом), хизмат кунад.\",\"type\":\"text\",\"version\":1}],\"direction\":null,\"format\":\"\",\"indent\":0,\"type\":\"paragraph\",\"version\":1,\"textFormat\":0,\"textStyle\":\"\"}],\"direction\":\"ltr\",\"format\":\"\",\"indent\":0,\"type\":\"root\",\"version\":1}}", "zh-CN": "{\"root\":{\"children\":[{\"children\":[{\"detail\":0,\"format\":0,\"mode\":\"normal\",\"style\":\"\",\"text\":\"马什哈德二星级贾瓦赫里酒店位于伊玛目礼萨街。酒店于1979年开业，2015年进行了全面翻新。其最大优势之一是靠近伊玛目礼萨圣陵，前往商业和购物中心十分便捷。贾瓦赫里酒店拥有5间客房和65个住宿单元，以及经验丰富、训练有素的员工，竭诚为第八伊玛目（愿主赐其平安）的尊贵来宾服务。\",\"type\":\"text\",\"version\":1}],\"direction\":null,\"format\":\"\",\"indent\":0,\"type\":\"paragraph\",\"version\":1,\"textFormat\":0,\"textStyle\":\"\"}],\"direction\":\"ltr\",\"format\":\"\",\"indent\":0,\"type\":\"root\",\"version\":1}}"}'::jsonb),
  ('{"root":{"children":[{"children":[{"detail":0,"format":0,"mode":"normal","style":"","text":"The two-star Khavar Hotel is located in the best part of Mashhad city, a short distance from the holy shrine of His Holiness, Imam Reza (peace be upon him), on Imam Reza Street. It was opened in 1978 and its last renovation was completed in 2018. Proximity to shopping centers is one of the advantages of this hotel. The Khavar Hotel, with its suitable amenities and experienced and trained staff, is proud to welcome and serve you, dear guests of His Holiness, Imam Reza (peace be upon him).","type":"text","version":1}],"direction":null,"format":"","indent":0,"type":"paragraph","version":1,"textFormat":0,"textStyle":""}],"direction":"ltr","format":"","indent":0,"type":"root","version":1}}', '{"tr-TR": "{\"root\":{\"children\":[{\"children\":[{\"detail\":0,\"format\":0,\"mode\":\"normal\",\"style\":\"\",\"text\":\"İki yıldızlı Khavar Oteli, Meşhed şehrinin en iyi bölgesinde, Hz. İmam Rıza (a.s.) Türbesi''ne kısa bir mesafede, İmam Rıza Caddesi''nde yer alır. 1978''de açılan otelin son yenilemesi 2018''de tamamlanmıştır. Alışveriş merkezlerine yakınlık bu otelin avantajlarından biridir. Uygun olanakları ve deneyimli, eğitimli personeliyle Khavar Oteli, Hz. İmam Rıza''nın (a.s.) siz değerli misafirlerini karşılamaktan ve onlara hizmet etmekten gurur duyar.\",\"type\":\"text\",\"version\":1}],\"direction\":null,\"format\":\"\",\"indent\":0,\"type\":\"paragraph\",\"version\":1,\"textFormat\":0,\"textStyle\":\"\"}],\"direction\":\"ltr\",\"format\":\"\",\"indent\":0,\"type\":\"root\",\"version\":1}}", "es-ES": "{\"root\":{\"children\":[{\"children\":[{\"detail\":0,\"format\":0,\"mode\":\"normal\",\"style\":\"\",\"text\":\"El Hotel Khavar, de dos estrellas, se encuentra en la mejor zona de la ciudad de Mashhad, a poca distancia del santuario de Su Santidad el Imam Reza (la paz sea con él), en la calle Imam Reza. Abrió en 1978 y su última renovación se completó en 2018. La proximidad a centros comerciales es una de las ventajas de este hotel. El Hotel Khavar, con servicios adecuados y un personal experimentado y formado, se enorgullece de recibirle y atenderle a usted, querido huésped de Su Santidad el Imam Reza (la paz sea con él).\",\"type\":\"text\",\"version\":1}],\"direction\":null,\"format\":\"\",\"indent\":0,\"type\":\"paragraph\",\"version\":1,\"textFormat\":0,\"textStyle\":\"\"}],\"direction\":\"ltr\",\"format\":\"\",\"indent\":0,\"type\":\"root\",\"version\":1}}", "ku-KU": "{\"root\":{\"children\":[{\"children\":[{\"detail\":0,\"format\":0,\"mode\":\"normal\",\"style\":\"\",\"text\":\"هوتێلی دوو ئەستێرەی خاوەر لە باشترین بەشی شاری مەشهەد، لە دوورییەکی کەم لە حەرەمی پیرۆزی حەزرەتی ئیمام ڕەزا (د.خ)، لە شەقامی ئیمام ڕەزا هەڵکەوتووە. لە ساڵی 1978 کرایەوە و دوایین نۆژەنکردنەوەی لە ساڵی 2018 تەواو بوو. نزیکی لە ناوەندەکانی بازاڕکردن یەکێکە لە سوودەکانی ئەم هوتێلە. هوتێلی خاوەر بە ئاسانکاریی گونجاو و ستافێکی شارەزا و ڕاهێنراوەوە، شانازی دەکات بە پێشوازی و خزمەتکردنی ئێوەی میوانی بەڕێزی حەزرەتی ئیمام ڕەزا (د.خ).\",\"type\":\"text\",\"version\":1}],\"direction\":null,\"format\":\"\",\"indent\":0,\"type\":\"paragraph\",\"version\":1,\"textFormat\":0,\"textStyle\":\"\"}],\"direction\":\"ltr\",\"format\":\"\",\"indent\":0,\"type\":\"root\",\"version\":1}}", "de-DE": "{\"root\":{\"children\":[{\"children\":[{\"detail\":0,\"format\":0,\"mode\":\"normal\",\"style\":\"\",\"text\":\"Das Zwei-Sterne-Hotel Khavar liegt in der besten Gegend von Maschhad, nicht weit vom heiligen Schrein Seiner Heiligkeit Imam Reza (Friede sei mit ihm), an der Imam-Reza-Straße. Es wurde 1978 eröffnet, und die letzte Renovierung wurde 2018 abgeschlossen. Die Nähe zu Einkaufszentren ist einer der Vorzüge dieses Hotels. Das Khavar Hotel mit seiner passenden Ausstattung und seinem erfahrenen und geschulten Personal freut sich, Sie, liebe Gäste Seiner Heiligkeit Imam Reza (Friede sei mit ihm), willkommen zu heißen und zu bedienen.\",\"type\":\"text\",\"version\":1}],\"direction\":null,\"format\":\"\",\"indent\":0,\"type\":\"paragraph\",\"version\":1,\"textFormat\":0,\"textStyle\":\"\"}],\"direction\":\"ltr\",\"format\":\"\",\"indent\":0,\"type\":\"root\",\"version\":1}}", "fr-FR": "{\"root\":{\"children\":[{\"children\":[{\"detail\":0,\"format\":0,\"mode\":\"normal\",\"style\":\"\",\"text\":\"L’hôtel deux étoiles Khavar est situé dans le meilleur quartier de Mashhad, à courte distance du saint sanctuaire de Sa Sainteté l’Imam Reza (que la paix soit sur lui), dans la rue Imam Reza. Il a ouvert en 1978 et sa dernière rénovation s’est achevée en 2018. La proximité des centres commerciaux est l’un des atouts de cet hôtel. L’hôtel Khavar, avec ses équipements adaptés et son personnel expérimenté et qualifié, est fier de vous accueillir et de vous servir, chers hôtes de Sa Sainteté l’Imam Reza (que la paix soit sur lui).\",\"type\":\"text\",\"version\":1}],\"direction\":null,\"format\":\"\",\"indent\":0,\"type\":\"paragraph\",\"version\":1,\"textFormat\":0,\"textStyle\":\"\"}],\"direction\":\"ltr\",\"format\":\"\",\"indent\":0,\"type\":\"root\",\"version\":1}}", "ru-RU": "{\"root\":{\"children\":[{\"children\":[{\"detail\":0,\"format\":0,\"mode\":\"normal\",\"style\":\"\",\"text\":\"Двухзвёздочный отель «Хавар» расположен в лучшей части Мешхеда, недалеко от священного мавзолея имама Резы (мир ему), на улице Имама Резы. Он открылся в 1978 году, а последняя реконструкция завершилась в 2018 году. Одно из преимуществ отеля — близость к торговым центрам. Отель «Хавар» с подходящими удобствами и опытным, обученным персоналом с гордостью встречает и обслуживает вас, дорогие гости имама Резы (мир ему).\",\"type\":\"text\",\"version\":1}],\"direction\":null,\"format\":\"\",\"indent\":0,\"type\":\"paragraph\",\"version\":1,\"textFormat\":0,\"textStyle\":\"\"}],\"direction\":\"ltr\",\"format\":\"\",\"indent\":0,\"type\":\"root\",\"version\":1}}", "tg-TJ": "{\"root\":{\"children\":[{\"children\":[{\"detail\":0,\"format\":0,\"mode\":\"normal\",\"style\":\"\",\"text\":\"Меҳмонхонаи дуситораи «Ховар» дар беҳтарин қисми шаҳри Машҳад, дар масофаи наздик аз Ҳарами муқаддаси Ҳазрати Имом Ризо (алайҳиссалом), дар кӯчаи Имом Ризо ҷойгир аст. Он соли 1978 кушода шуда, охирин таъмири он соли 2018 анҷом ёфт. Наздикӣ ба марказҳои савдо яке аз бартариҳои ин меҳмонхона аст. Меҳмонхонаи «Ховар» бо шароити мувофиқ ва кормандони ботаҷрибаву омӯзонидашуда аз истиқбол ва хизмат ба шумо, меҳмонони азизи Ҳазрати Имом Ризо (алайҳиссалом), ифтихор дорад.\",\"type\":\"text\",\"version\":1}],\"direction\":null,\"format\":\"\",\"indent\":0,\"type\":\"paragraph\",\"version\":1,\"textFormat\":0,\"textStyle\":\"\"}],\"direction\":\"ltr\",\"format\":\"\",\"indent\":0,\"type\":\"root\",\"version\":1}}", "zh-CN": "{\"root\":{\"children\":[{\"children\":[{\"detail\":0,\"format\":0,\"mode\":\"normal\",\"style\":\"\",\"text\":\"二星级哈瓦尔酒店位于马什哈德市最佳地段的伊玛目礼萨街，距伊玛目礼萨（愿主赐其平安）圣陵仅咫尺之遥。酒店于1978年开业，最近一次翻新于2018年完成。靠近购物中心是本酒店的优势之一。哈瓦尔酒店设施完善，员工经验丰富、训练有素，竭诚欢迎并服务伊玛目礼萨（愿主赐其平安）的尊贵来宾。\",\"type\":\"text\",\"version\":1}],\"direction\":null,\"format\":\"\",\"indent\":0,\"type\":\"paragraph\",\"version\":1,\"textFormat\":0,\"textStyle\":\"\"}],\"direction\":\"ltr\",\"format\":\"\",\"indent\":0,\"type\":\"root\",\"version\":1}}"}'::jsonb),
  ('{"root":{"children":[{"children":[{"detail":0,"format":0,"mode":"normal","style":"","text":"If you are looking for a stylish, comfortable, and centrally located accommodation near the Holy Shrine of Imam Reza (AS), Mohammadi Shahan Hotel Apartment is one of your best choices. This hotel is perfectly situated on Navab Safavi 11 Street in Mashhad. With just a pleasant 4-minute walk, you can reach the Holy Shrine, allowing you to enjoy the pilgrimage without worrying about traffic or crowds.","type":"text","version":1}],"direction":null,"format":"","indent":0,"type":"paragraph","version":1,"textFormat":0,"textStyle":""},{"children":[{"detail":0,"format":0,"mode":"normal","style":"","text":"The property features private open parking for guests’ convenience and clean, well-equipped rooms with a capacity of 2 to 4 people, making it perfect for families and groups. All rooms are furnished with amenities such as a hairdryer, vanity table, wardrobe, and free high-speed Wi-Fi, ensuring a completely comfortable stay.","type":"text","version":1}],"direction":null,"format":"","indent":0,"type":"paragraph","version":1,"textFormat":0,"textStyle":""},{"children":[{"detail":0,"format":0,"mode":"normal","style":"","text":"The hotel restaurant offers a delicious and pleasant experience with a breakfast buffet and à la carte lunch and dinner options. The variety and high quality of the food mean you can enjoy fresh, healthy meals in a peaceful environment without needing to leave the hotel.","type":"text","version":1}],"direction":null,"format":"","indent":0,"type":"paragraph","version":1,"textFormat":0,"textStyle":""},{"children":[{"detail":0,"format":0,"mode":"normal","style":"","text":"To book this hotel apartment, you can simply visit the “Zavaran” website, pay the deposit, and confirm your reservation with peace of mind before starting your pilgrimage.","type":"text","version":1}],"direction":null,"format":"","indent":0,"type":"paragraph","version":1,"textFormat":0,"textStyle":""}],"direction":"ltr","format":"","indent":0,"type":"root","version":1}}', '{"tr-TR": "{\"root\":{\"children\":[{\"children\":[{\"detail\":0,\"format\":0,\"mode\":\"normal\",\"style\":\"\",\"text\":\"İmam Rıza (a.s.) Türbesi yakınında şık, konforlu ve merkezi bir konaklama arıyorsanız Mohammadi Shahan Apart Otel en iyi seçeneklerinizden biridir. Otel, Meşhed''de Navvab Safevi 11 Sokağı''nda ideal bir konumdadır. Yalnızca 4 dakikalık keyifli bir yürüyüşle türbeye ulaşabilir, trafik ya da kalabalık derdi olmadan ziyaretinizin tadını çıkarabilirsiniz.\",\"type\":\"text\",\"version\":1}],\"direction\":null,\"format\":\"\",\"indent\":0,\"type\":\"paragraph\",\"version\":1,\"textFormat\":0,\"textStyle\":\"\"},{\"children\":[{\"detail\":0,\"format\":0,\"mode\":\"normal\",\"style\":\"\",\"text\":\"Tesiste misafirlerin rahatı için özel açık otopark ile 2 ila 4 kişilik temiz ve iyi donanımlı odalar bulunur; bu da tesisi aileler ve gruplar için ideal kılar. Tüm odalarda saç kurutma makinesi, makyaj masası, gardırop ve ücretsiz yüksek hızlı Wi-Fi gibi olanaklar bulunur ve tamamen konforlu bir konaklama sağlar.\",\"type\":\"text\",\"version\":1}],\"direction\":null,\"format\":\"\",\"indent\":0,\"type\":\"paragraph\",\"version\":1,\"textFormat\":0,\"textStyle\":\"\"},{\"children\":[{\"detail\":0,\"format\":0,\"mode\":\"normal\",\"style\":\"\",\"text\":\"Otel restoranı, açık büfe kahvaltı ve alakart öğle ve akşam yemeği seçenekleriyle lezzetli ve keyifli bir deneyim sunar. Yemeklerin çeşitliliği ve yüksek kalitesi sayesinde otelden ayrılmanıza gerek kalmadan huzurlu bir ortamda taze ve sağlıklı yemeklerin tadını çıkarabilirsiniz.\",\"type\":\"text\",\"version\":1}],\"direction\":null,\"format\":\"\",\"indent\":0,\"type\":\"paragraph\",\"version\":1,\"textFormat\":0,\"textStyle\":\"\"},{\"children\":[{\"detail\":0,\"format\":0,\"mode\":\"normal\",\"style\":\"\",\"text\":\"Bu apart oteli ayırtmak için “Zavaran” web sitesini ziyaret edip ön ödemeyi yapmanız ve ziyaretinize başlamadan önce rezervasyonunuzu gönül rahatlığıyla onaylamanız yeterlidir.\",\"type\":\"text\",\"version\":1}],\"direction\":null,\"format\":\"\",\"indent\":0,\"type\":\"paragraph\",\"version\":1,\"textFormat\":0,\"textStyle\":\"\"}],\"direction\":\"ltr\",\"format\":\"\",\"indent\":0,\"type\":\"root\",\"version\":1}}", "es-ES": "{\"root\":{\"children\":[{\"children\":[{\"detail\":0,\"format\":0,\"mode\":\"normal\",\"style\":\"\",\"text\":\"Si buscas un alojamiento elegante, cómodo y céntrico cerca del Santuario del Imam Reza (la paz sea con él), el Apartahotel Mohammadi Shahan es una de tus mejores opciones. Este hotel está perfectamente situado en la calle Navab Safavi 11 de Mashhad. Con solo un agradable paseo de 4 minutos llegarás al Santuario, para que disfrutes de la peregrinación sin preocuparte por el tráfico ni las multitudes.\",\"type\":\"text\",\"version\":1}],\"direction\":null,\"format\":\"\",\"indent\":0,\"type\":\"paragraph\",\"version\":1,\"textFormat\":0,\"textStyle\":\"\"},{\"children\":[{\"detail\":0,\"format\":0,\"mode\":\"normal\",\"style\":\"\",\"text\":\"El establecimiento dispone de parking privado al aire libre para comodidad de los huéspedes y de habitaciones limpias y bien equipadas con capacidad para 2 a 4 personas, ideales para familias y grupos. Todas las habitaciones cuentan con secador de pelo, tocador, armario y Wi-Fi de alta velocidad gratuito, para garantizar una estancia totalmente cómoda.\",\"type\":\"text\",\"version\":1}],\"direction\":null,\"format\":\"\",\"indent\":0,\"type\":\"paragraph\",\"version\":1,\"textFormat\":0,\"textStyle\":\"\"},{\"children\":[{\"detail\":0,\"format\":0,\"mode\":\"normal\",\"style\":\"\",\"text\":\"El restaurante del hotel ofrece una experiencia deliciosa y agradable con desayuno bufé y almuerzo y cena a la carta. La variedad y la alta calidad de la comida te permiten disfrutar de platos frescos y saludables en un entorno tranquilo sin necesidad de salir del hotel.\",\"type\":\"text\",\"version\":1}],\"direction\":null,\"format\":\"\",\"indent\":0,\"type\":\"paragraph\",\"version\":1,\"textFormat\":0,\"textStyle\":\"\"},{\"children\":[{\"detail\":0,\"format\":0,\"mode\":\"normal\",\"style\":\"\",\"text\":\"Para reservar este apartahotel, solo tienes que visitar el sitio web «Zavaran», pagar el depósito y confirmar tu reserva con total tranquilidad antes de comenzar tu peregrinación.\",\"type\":\"text\",\"version\":1}],\"direction\":null,\"format\":\"\",\"indent\":0,\"type\":\"paragraph\",\"version\":1,\"textFormat\":0,\"textStyle\":\"\"}],\"direction\":\"ltr\",\"format\":\"\",\"indent\":0,\"type\":\"root\",\"version\":1}}", "ku-KU": "{\"root\":{\"children\":[{\"children\":[{\"detail\":0,\"format\":0,\"mode\":\"normal\",\"style\":\"\",\"text\":\"ئەگەر بەدوای شوێنێکی مانەوەی شیک، ئاسوودە و لە ناوەنددا لە نزیک حەرەمی پیرۆزی ئیمام ڕەزا (د.خ) دەگەڕێیت، شوقەی هوتێلی محەممەدی شاهان یەکێکە لە باشترین هەڵبژاردەکانت. ئەم هوتێلە لە شوێنێکی نایابدا لە شەقامی نەوابی سەفەوی 11 لە مەشهەد هەڵکەوتووە. تەنها بە 4 خولەک پیاسەیەکی خۆش دەگەیتە حەرەمی پیرۆز، و دەتوانیت بێ نیگەرانی لە هاتوچۆ و قەرەباڵغی چێژ لە زیارەت ببینیت.\",\"type\":\"text\",\"version\":1}],\"direction\":null,\"format\":\"\",\"indent\":0,\"type\":\"paragraph\",\"version\":1,\"textFormat\":0,\"textStyle\":\"\"},{\"children\":[{\"detail\":0,\"format\":0,\"mode\":\"normal\",\"style\":\"\",\"text\":\"ئەم شوێنە پارکینگی کراوەی تایبەتی بۆ ئاسوودەیی میوانان هەیە و ژووری خاوێن و پڕچەک بە توانای 2 تا 4 کەس، کە بۆ خێزان و گرووپەکان گونجاوە. هەموو ژوورەکان بە ئاسانکاریی وەک ئامێری قژ وشککردنەوە، مێزی ئارایشت، کەنتۆر و وایفایی خێرای بەخۆڕایی پڕچەک کراون، بۆ ئەوەی مانەوەیەکی تەواو ئاسوودەت هەبێت.\",\"type\":\"text\",\"version\":1}],\"direction\":null,\"format\":\"\",\"indent\":0,\"type\":\"paragraph\",\"version\":1,\"textFormat\":0,\"textStyle\":\"\"},{\"children\":[{\"detail\":0,\"format\":0,\"mode\":\"normal\",\"style\":\"\",\"text\":\"ڕێستۆرانتی هوتێلەکە ئەزموونێکی بەتام و خۆش پێشکەش دەکات بە بوفەی نانی بەیانی و هەڵبژاردنی لیستی خواردن بۆ نانی نیوەڕۆ و ئێوارە. جۆراوجۆری و کوالیتیی بەرزی خواردنەکان وا دەکەن بتوانیت لە ژینگەیەکی ئارامدا چێژ لە خواردنی تازە و تەندروست ببینیت بێ ئەوەی پێویست بکات هوتێلەکە جێبهێڵیت.\",\"type\":\"text\",\"version\":1}],\"direction\":null,\"format\":\"\",\"indent\":0,\"type\":\"paragraph\",\"version\":1,\"textFormat\":0,\"textStyle\":\"\"},{\"children\":[{\"detail\":0,\"format\":0,\"mode\":\"normal\",\"style\":\"\",\"text\":\"بۆ حجزکردنی ئەم شوقە هوتێلییە، دەتوانیت بە سادەیی سەردانی ماڵپەڕی «Zavaran» بکەیت، پێشەکی پارە بدەیت و پێش دەستپێکردنی زیارەتەکەت بە دڵنیاییەوە حجزەکەت پشتڕاست بکەیتەوە.\",\"type\":\"text\",\"version\":1}],\"direction\":null,\"format\":\"\",\"indent\":0,\"type\":\"paragraph\",\"version\":1,\"textFormat\":0,\"textStyle\":\"\"}],\"direction\":\"ltr\",\"format\":\"\",\"indent\":0,\"type\":\"root\",\"version\":1}}", "de-DE": "{\"root\":{\"children\":[{\"children\":[{\"detail\":0,\"format\":0,\"mode\":\"normal\",\"style\":\"\",\"text\":\"Wenn Sie eine stilvolle, komfortable und zentral gelegene Unterkunft nahe dem heiligen Schrein des Imam Reza (Friede sei mit ihm) suchen, ist das Aparthotel Mohammadi Shahan eine Ihrer besten Optionen. Das Hotel liegt ideal an der Navab-Safavi-11-Straße in Maschhad. Nach nur 4 angenehmen Gehminuten erreichen Sie den heiligen Schrein und können die Pilgerfahrt ohne Sorge um Verkehr oder Gedränge genießen.\",\"type\":\"text\",\"version\":1}],\"direction\":null,\"format\":\"\",\"indent\":0,\"type\":\"paragraph\",\"version\":1,\"textFormat\":0,\"textStyle\":\"\"},{\"children\":[{\"detail\":0,\"format\":0,\"mode\":\"normal\",\"style\":\"\",\"text\":\"Die Unterkunft bietet einen privaten Parkplatz im Freien für die Gäste sowie saubere, gut ausgestattete Zimmer für 2 bis 4 Personen – ideal für Familien und Gruppen. Alle Zimmer verfügen unter anderem über Haartrockner, Schminktisch, Kleiderschrank und kostenfreies Highspeed-WLAN für einen rundum komfortablen Aufenthalt.\",\"type\":\"text\",\"version\":1}],\"direction\":null,\"format\":\"\",\"indent\":0,\"type\":\"paragraph\",\"version\":1,\"textFormat\":0,\"textStyle\":\"\"},{\"children\":[{\"detail\":0,\"format\":0,\"mode\":\"normal\",\"style\":\"\",\"text\":\"Das Hotelrestaurant bietet ein köstliches und angenehmes Erlebnis mit Frühstücksbuffet sowie Mittag- und Abendessen à la carte. Dank der Vielfalt und hohen Qualität der Speisen genießen Sie frische, gesunde Mahlzeiten in ruhiger Umgebung, ohne das Hotel verlassen zu müssen.\",\"type\":\"text\",\"version\":1}],\"direction\":null,\"format\":\"\",\"indent\":0,\"type\":\"paragraph\",\"version\":1,\"textFormat\":0,\"textStyle\":\"\"},{\"children\":[{\"detail\":0,\"format\":0,\"mode\":\"normal\",\"style\":\"\",\"text\":\"Um dieses Aparthotel zu buchen, besuchen Sie einfach die Website „Zavaran“, leisten die Anzahlung und bestätigen Ihre Reservierung ganz beruhigt vor Beginn Ihrer Pilgerreise.\",\"type\":\"text\",\"version\":1}],\"direction\":null,\"format\":\"\",\"indent\":0,\"type\":\"paragraph\",\"version\":1,\"textFormat\":0,\"textStyle\":\"\"}],\"direction\":\"ltr\",\"format\":\"\",\"indent\":0,\"type\":\"root\",\"version\":1}}", "fr-FR": "{\"root\":{\"children\":[{\"children\":[{\"detail\":0,\"format\":0,\"mode\":\"normal\",\"style\":\"\",\"text\":\"Si vous cherchez un hébergement élégant, confortable et central près du saint sanctuaire de l’Imam Reza (que la paix soit sur lui), l’appart’hôtel Mohammadi Shahan est l’un de vos meilleurs choix. L’hôtel est idéalement situé dans la rue Navab Safavi 11, à Mashhad. Une agréable promenade de 4 minutes seulement vous mène au saint sanctuaire, pour profiter du pèlerinage sans vous soucier de la circulation ni de la foule.\",\"type\":\"text\",\"version\":1}],\"direction\":null,\"format\":\"\",\"indent\":0,\"type\":\"paragraph\",\"version\":1,\"textFormat\":0,\"textStyle\":\"\"},{\"children\":[{\"detail\":0,\"format\":0,\"mode\":\"normal\",\"style\":\"\",\"text\":\"L’établissement dispose d’un parking privé en plein air pour le confort des clients et de chambres propres et bien équipées pouvant accueillir de 2 à 4 personnes, idéales pour les familles et les groupes. Toutes les chambres sont équipées notamment d’un sèche-cheveux, d’une coiffeuse, d’une armoire et d’une connexion Wi-Fi haut débit gratuite, pour un séjour en tout confort.\",\"type\":\"text\",\"version\":1}],\"direction\":null,\"format\":\"\",\"indent\":0,\"type\":\"paragraph\",\"version\":1,\"textFormat\":0,\"textStyle\":\"\"},{\"children\":[{\"detail\":0,\"format\":0,\"mode\":\"normal\",\"style\":\"\",\"text\":\"Le restaurant de l’hôtel offre une expérience savoureuse et agréable avec un petit-déjeuner buffet ainsi que des déjeuners et dîners à la carte. Grâce à la variété et à la grande qualité des plats, vous pouvez savourer des repas frais et sains dans un cadre paisible, sans avoir à quitter l’hôtel.\",\"type\":\"text\",\"version\":1}],\"direction\":null,\"format\":\"\",\"indent\":0,\"type\":\"paragraph\",\"version\":1,\"textFormat\":0,\"textStyle\":\"\"},{\"children\":[{\"detail\":0,\"format\":0,\"mode\":\"normal\",\"style\":\"\",\"text\":\"Pour réserver cet appart’hôtel, il vous suffit de vous rendre sur le site « Zavaran », de verser l’acompte et de confirmer votre réservation en toute sérénité avant de commencer votre pèlerinage.\",\"type\":\"text\",\"version\":1}],\"direction\":null,\"format\":\"\",\"indent\":0,\"type\":\"paragraph\",\"version\":1,\"textFormat\":0,\"textStyle\":\"\"}],\"direction\":\"ltr\",\"format\":\"\",\"indent\":0,\"type\":\"root\",\"version\":1}}", "ru-RU": "{\"root\":{\"children\":[{\"children\":[{\"detail\":0,\"format\":0,\"mode\":\"normal\",\"style\":\"\",\"text\":\"Если вы ищете стильное и комфортное жильё в удобном месте рядом со священным мавзолеем имама Резы (мир ему), апарт-отель «Мохаммади Шахан» — один из лучших вариантов. Отель удачно расположен на улице Наваб-Сафави 11 в Мешхеде. Всего за 4 минуты приятной прогулки вы дойдёте до святыни и сможете совершить паломничество, не беспокоясь о пробках и толпах.\",\"type\":\"text\",\"version\":1}],\"direction\":null,\"format\":\"\",\"indent\":0,\"type\":\"paragraph\",\"version\":1,\"textFormat\":0,\"textStyle\":\"\"},{\"children\":[{\"detail\":0,\"format\":0,\"mode\":\"normal\",\"style\":\"\",\"text\":\"Для удобства гостей есть собственная открытая парковка, а чистые, хорошо оборудованные номера вместимостью от 2 до 4 человек идеально подходят для семей и групп. Во всех номерах есть фен, туалетный столик, шкаф и бесплатный высокоскоростной Wi-Fi, что делает пребывание полностью комфортным.\",\"type\":\"text\",\"version\":1}],\"direction\":null,\"format\":\"\",\"indent\":0,\"type\":\"paragraph\",\"version\":1,\"textFormat\":0,\"textStyle\":\"\"},{\"children\":[{\"detail\":0,\"format\":0,\"mode\":\"normal\",\"style\":\"\",\"text\":\"Ресторан отеля предлагает вкусную и приятную трапезу: завтрак «шведский стол», а также обеды и ужины по меню. Благодаря разнообразию и высокому качеству блюд вы можете наслаждаться свежей, полезной едой в спокойной обстановке, не выходя из отеля.\",\"type\":\"text\",\"version\":1}],\"direction\":null,\"format\":\"\",\"indent\":0,\"type\":\"paragraph\",\"version\":1,\"textFormat\":0,\"textStyle\":\"\"},{\"children\":[{\"detail\":0,\"format\":0,\"mode\":\"normal\",\"style\":\"\",\"text\":\"Чтобы забронировать этот апарт-отель, достаточно зайти на сайт «Заваран», внести предоплату и спокойно подтвердить бронирование перед началом паломничества.\",\"type\":\"text\",\"version\":1}],\"direction\":null,\"format\":\"\",\"indent\":0,\"type\":\"paragraph\",\"version\":1,\"textFormat\":0,\"textStyle\":\"\"}],\"direction\":\"ltr\",\"format\":\"\",\"indent\":0,\"type\":\"root\",\"version\":1}}", "tg-TJ": "{\"root\":{\"children\":[{\"children\":[{\"detail\":0,\"format\":0,\"mode\":\"normal\",\"style\":\"\",\"text\":\"Агар шумо манзили шик, бароҳат ва дар марказ ҷойгиршударо дар наздикии Ҳарами муқаддаси Имом Ризо (алайҳиссалом) ҷустуҷӯ кунед, апарт-меҳмонхонаи «Муҳаммадии Шоҳон» яке аз беҳтарин интихобҳои шумост. Ин меҳмонхона дар ҷои хеле мувофиқ, дар кӯчаи Навоб Сафавии 11-и Машҳад ҷойгир аст. Танҳо бо 4 дақиқа пиёдагардии гуворо шумо ба Ҳарами муқаддас мерасед ва метавонед бе ташвиши тирбандӣ ва издиҳом аз зиёрат баҳра баред.\",\"type\":\"text\",\"version\":1}],\"direction\":null,\"format\":\"\",\"indent\":0,\"type\":\"paragraph\",\"version\":1,\"textFormat\":0,\"textStyle\":\"\"},{\"children\":[{\"detail\":0,\"format\":0,\"mode\":\"normal\",\"style\":\"\",\"text\":\"Барои роҳати меҳмонон таваққуфгоҳи кушодаи хусусӣ ва ҳуҷраҳои тоза ва хуб муҷаҳҳаз барои 2 то 4 нафар мавҷуданд, ки барои оилаҳо ва гурӯҳҳо комиланд. Ҳамаи ҳуҷраҳо бо мӯйхушккунак, мизи ороиш, ҷевон ва Wi-Fi-и ройгони баландсуръат муҷаҳҳаз буда, иқомати комилан бароҳатро таъмин мекунанд.\",\"type\":\"text\",\"version\":1}],\"direction\":null,\"format\":\"\",\"indent\":0,\"type\":\"paragraph\",\"version\":1,\"textFormat\":0,\"textStyle\":\"\"},{\"children\":[{\"detail\":0,\"format\":0,\"mode\":\"normal\",\"style\":\"\",\"text\":\"Тарабхонаи меҳмонхона бо наҳории шведӣ ва хӯроки нисфирӯзию шом аз рӯйи меню таҷрибаи болаззат ва гуворо пешниҳод мекунад. Гуногунӣ ва сифати баланди таомҳо имкон медиҳад, ки бе тарки меҳмонхона дар муҳити ором аз хӯрокҳои тоза ва солим баҳра баред.\",\"type\":\"text\",\"version\":1}],\"direction\":null,\"format\":\"\",\"indent\":0,\"type\":\"paragraph\",\"version\":1,\"textFormat\":0,\"textStyle\":\"\"},{\"children\":[{\"detail\":0,\"format\":0,\"mode\":\"normal\",\"style\":\"\",\"text\":\"Барои фармоиш додани ин апарт-меҳмонхона кофист ба сомонаи «Зоирон» ворид шавед, пешпардохтро супоред ва пеш аз оғози зиёрат бо хотири ҷамъ фармоиши худро тасдиқ кунед.\",\"type\":\"text\",\"version\":1}],\"direction\":null,\"format\":\"\",\"indent\":0,\"type\":\"paragraph\",\"version\":1,\"textFormat\":0,\"textStyle\":\"\"}],\"direction\":\"ltr\",\"format\":\"\",\"indent\":0,\"type\":\"root\",\"version\":1}}", "zh-CN": "{\"root\":{\"children\":[{\"children\":[{\"detail\":0,\"format\":0,\"mode\":\"normal\",\"style\":\"\",\"text\":\"如果您正在寻找一处时尚、舒适、位置便利且靠近伊玛目礼萨（愿主赐其平安）圣陵的住宿，穆罕默迪沙汉酒店式公寓是您的最佳选择之一。酒店地理位置绝佳，位于马什哈德纳瓦布·萨法维11街。只需惬意步行4分钟即可到达圣陵，让您安心朝拜，无需担心交通拥堵或人潮拥挤。\",\"type\":\"text\",\"version\":1}],\"direction\":null,\"format\":\"\",\"indent\":0,\"type\":\"paragraph\",\"version\":1,\"textFormat\":0,\"textStyle\":\"\"},{\"children\":[{\"detail\":0,\"format\":0,\"mode\":\"normal\",\"style\":\"\",\"text\":\"酒店为方便宾客提供私人露天停车场，客房干净整洁、设施齐全，可容纳2至4人，非常适合家庭和团体入住。所有客房均配备吹风机、梳妆台、衣柜和免费高速Wi-Fi等设施，确保您住得完全舒适。\",\"type\":\"text\",\"version\":1}],\"direction\":null,\"format\":\"\",\"indent\":0,\"type\":\"paragraph\",\"version\":1,\"textFormat\":0,\"textStyle\":\"\"},{\"children\":[{\"detail\":0,\"format\":0,\"mode\":\"normal\",\"style\":\"\",\"text\":\"酒店餐厅提供自助早餐以及点菜式午餐和晚餐，带来美味愉悦的用餐体验。菜品丰富、品质上乘，无需离开酒店，即可在宁静的环境中享用新鲜健康的餐食。\",\"type\":\"text\",\"version\":1}],\"direction\":null,\"format\":\"\",\"indent\":0,\"type\":\"paragraph\",\"version\":1,\"textFormat\":0,\"textStyle\":\"\"},{\"children\":[{\"detail\":0,\"format\":0,\"mode\":\"normal\",\"style\":\"\",\"text\":\"如需预订这家酒店式公寓，只需访问“Zavaran”网站，支付定金，即可在开始朝圣之旅前放心确认预订。\",\"type\":\"text\",\"version\":1}],\"direction\":null,\"format\":\"\",\"indent\":0,\"type\":\"paragraph\",\"version\":1,\"textFormat\":0,\"textStyle\":\"\"}],\"direction\":\"ltr\",\"format\":\"\",\"indent\":0,\"type\":\"root\",\"version\":1}}"}'::jsonb),
  ('{"root":{"children":[{"children":[{"detail":0,"format":1,"mode":"normal","style":"","text":"Qasr International Hotel Mashhad","type":"text","version":1},{"detail":0,"format":0,"mode":"normal","style":"","text":" is one of the oldest and most renowned five-star hotels near the Holy Shrine. Operating since 1977 at the beginning of Imam Reza Street, it has always been a top choice for pilgrims due to its distinctive architecture and luxurious interiors. Recently renovated, the hotel now offers over 200 accommodation units, ranging from single and double rooms to luxury suites, Presidential suites, honeymoon suites, and rooms with decor inspired by various eras of Iranian history. Its proximity to the Holy Shrine, Reza Bazaar, and 17 Shahrivar Bazaar ensures easy access for pilgrims, making it a premier choice for Mashhad hotel reservations.","type":"text","version":1}],"direction":null,"format":"","indent":0,"type":"paragraph","version":1,"textFormat":0,"textStyle":""},{"children":[{"detail":0,"format":0,"mode":"normal","style":"","text":"The hotel boasts a wide range of amenities. The wellness center includes a swimming pool, sauna, jacuzzi, and a traditional bath, alongside massage rooms and fitness facilities for relaxation and physical activity. For dining, guests can enjoy various environments, including Persian, international, traditional, and fast-food restaurants, as well as a 24-hour coffee shop. Additional facilities such as a children’s amusement park, souvenir shops, an exchange office, taxi services, parking, and tour services complete the experience. Guests frequently commend the hotel’s internal organization, excellent service, and professional staff.","type":"text","version":1}],"direction":null,"format":"","indent":0,"type":"paragraph","version":1,"textFormat":0,"textStyle":""},{"children":[{"detail":0,"format":0,"mode":"normal","style":"","text":"Given its prime location, comprehensive amenities, and luxurious atmosphere, Qasr International Hotel is a reliable choice for travelers seeking high-end, peaceful accommodation near the Holy Shrine.","type":"text","version":1}],"direction":null,"format":"","indent":0,"type":"paragraph","version":1,"textFormat":0,"textStyle":""}],"direction":"ltr","format":"","indent":0,"type":"root","version":1,"textFormat":1}}', '{"tr-TR": "{\"root\":{\"children\":[{\"children\":[{\"detail\":0,\"format\":1,\"mode\":\"normal\",\"style\":\"\",\"text\":\"Meşhed Qasr Uluslararası Oteli\",\"type\":\"text\",\"version\":1},{\"detail\":0,\"format\":0,\"mode\":\"normal\",\"style\":\"\",\"text\":\" Kutsal Türbe yakınındaki en eski ve en tanınmış beş yıldızlı otellerden biridir. 1977''den beri İmam Rıza Caddesi''nin başında hizmet veren otel, kendine özgü mimarisi ve lüks iç mekânlarıyla her zaman hacıların gözde tercihi olmuştur. Yakın zamanda yenilenen otel, bugün tek ve çift kişilik odalardan lüks süitlere, başkanlık süitlerine, balayı süitlerine ve İran tarihinin farklı dönemlerinden esinlenen dekorasyona sahip odalara kadar 200''den fazla konaklama birimi sunar. Kutsal Türbe''ye, Rıza Çarşısı''na ve 17 Şehriver Çarşısı''na yakınlığı hacılara kolay erişim sağlar ve oteli Meşhed otel rezervasyonları için başlıca tercihlerden biri yapar.\",\"type\":\"text\",\"version\":1}],\"direction\":null,\"format\":\"\",\"indent\":0,\"type\":\"paragraph\",\"version\":1,\"textFormat\":0,\"textStyle\":\"\"},{\"children\":[{\"detail\":0,\"format\":0,\"mode\":\"normal\",\"style\":\"\",\"text\":\"Otel çok çeşitli olanaklara sahiptir. Sağlıklı yaşam merkezinde yüzme havuzu, sauna, jakuzi ve geleneksel hamamın yanı sıra dinlenme ve fiziksel aktivite için masaj odaları ve fitness olanakları bulunur. Yemek için misafirler İran mutfağı, uluslararası, geleneksel ve fast food restoranları ile 24 saat açık bir kafe dahil çeşitli ortamların tadını çıkarabilir. Çocuk oyun parkı, hediyelik eşya dükkânları, döviz bürosu, taksi hizmetleri, otopark ve tur hizmetleri gibi ek olanaklar deneyimi tamamlar. Misafirler otelin iç düzenini, mükemmel hizmetini ve profesyonel personelini sıklıkla övmektedir.\",\"type\":\"text\",\"version\":1}],\"direction\":null,\"format\":\"\",\"indent\":0,\"type\":\"paragraph\",\"version\":1,\"textFormat\":0,\"textStyle\":\"\"},{\"children\":[{\"detail\":0,\"format\":0,\"mode\":\"normal\",\"style\":\"\",\"text\":\"Ayrıcalıklı konumu, kapsamlı olanakları ve lüks atmosferiyle Qasr Uluslararası Oteli, Kutsal Türbe yakınında üst düzey ve huzurlu bir konaklama arayan yolcular için güvenilir bir seçimdir.\",\"type\":\"text\",\"version\":1}],\"direction\":null,\"format\":\"\",\"indent\":0,\"type\":\"paragraph\",\"version\":1,\"textFormat\":0,\"textStyle\":\"\"}],\"direction\":\"ltr\",\"format\":\"\",\"indent\":0,\"type\":\"root\",\"version\":1,\"textFormat\":1}}", "es-ES": "{\"root\":{\"children\":[{\"children\":[{\"detail\":0,\"format\":1,\"mode\":\"normal\",\"style\":\"\",\"text\":\"El Hotel Internacional Qasr de Mashhad\",\"type\":\"text\",\"version\":1},{\"detail\":0,\"format\":0,\"mode\":\"normal\",\"style\":\"\",\"text\":\" es uno de los hoteles de cinco estrellas más antiguos y reconocidos cerca del Santuario. En funcionamiento desde 1977 al comienzo de la calle Imam Reza, siempre ha sido una de las opciones preferidas de los peregrinos por su arquitectura singular y sus lujosos interiores. Recientemente renovado, el hotel ofrece ahora más de 200 unidades de alojamiento, desde habitaciones individuales y dobles hasta suites de lujo, suites presidenciales, suites nupciales y habitaciones con una decoración inspirada en distintas épocas de la historia de Irán. Su proximidad al Santuario, al Bazar Reza y al Bazar 17 Shahrivar facilita el acceso a los peregrinos y lo convierte en una opción destacada para reservar hotel en Mashhad.\",\"type\":\"text\",\"version\":1}],\"direction\":null,\"format\":\"\",\"indent\":0,\"type\":\"paragraph\",\"version\":1,\"textFormat\":0,\"textStyle\":\"\"},{\"children\":[{\"detail\":0,\"format\":0,\"mode\":\"normal\",\"style\":\"\",\"text\":\"El hotel cuenta con una amplia gama de servicios. El centro de bienestar incluye piscina, sauna, jacuzzi y baño tradicional, además de salas de masaje e instalaciones de fitness para relajarse y hacer ejercicio. Para comer, los huéspedes pueden disfrutar de distintos ambientes, como restaurantes persas, internacionales, tradicionales y de comida rápida, así como una cafetería abierta las 24 horas. Otros servicios, como un parque infantil, tiendas de recuerdos, oficina de cambio, servicio de taxi, parking y servicio de excursiones, completan la experiencia. Los huéspedes elogian con frecuencia la organización interna del hotel, su excelente servicio y su personal profesional.\",\"type\":\"text\",\"version\":1}],\"direction\":null,\"format\":\"\",\"indent\":0,\"type\":\"paragraph\",\"version\":1,\"textFormat\":0,\"textStyle\":\"\"},{\"children\":[{\"detail\":0,\"format\":0,\"mode\":\"normal\",\"style\":\"\",\"text\":\"Por su ubicación privilegiada, sus completos servicios y su ambiente lujoso, el Hotel Internacional Qasr es una opción fiable para viajeros que buscan un alojamiento tranquilo y de alta gama cerca del Santuario.\",\"type\":\"text\",\"version\":1}],\"direction\":null,\"format\":\"\",\"indent\":0,\"type\":\"paragraph\",\"version\":1,\"textFormat\":0,\"textStyle\":\"\"}],\"direction\":\"ltr\",\"format\":\"\",\"indent\":0,\"type\":\"root\",\"version\":1,\"textFormat\":1}}", "ku-KU": "{\"root\":{\"children\":[{\"children\":[{\"detail\":0,\"format\":1,\"mode\":\"normal\",\"style\":\"\",\"text\":\"هوتێلی نێودەوڵەتیی قەسری مەشهەد\",\"type\":\"text\",\"version\":1},{\"detail\":0,\"format\":0,\"mode\":\"normal\",\"style\":\"\",\"text\":\" یەکێکە لە کۆنترین و ناودارترین هوتێلە پێنج ئەستێرەکانی نزیک حەرەمی پیرۆز. لە ساڵی 1977ەوە لە سەرەتای شەقامی ئیمام ڕەزا کار دەکات و بەهۆی تەلارسازیی جیاواز و ناوەوەی لۆکسییەوە هەمیشە هەڵبژاردەی سەرەکیی زائیران بووە. هوتێلەکە بەم دواییە نۆژەن کراوەتەوە و ئێستا زیاتر لە 200 یەکەی مانەوە پێشکەش دەکات، لە ژووری یەک کەسی و دوو کەسییەوە تا سویتی لۆکس، سویتی سەرۆکایەتی، سویتی مانگی هەنگوین و ژوورگەلێک کە ڕازاندنەوەیان ئیلهامی لە سەردەمە جیاوازەکانی مێژووی ئێران وەرگرتووە. نزیکیی لە حەرەمی پیرۆز، بازاڕی ڕەزا و بازاڕی 17ی شەهریوەر دەستڕاگەیشتنی ئاسان بۆ زائیران مسۆگەر دەکات و دەیکاتە هەڵبژاردەیەکی پێشەنگ بۆ حجزی هوتێل لە مەشهەد.\",\"type\":\"text\",\"version\":1}],\"direction\":null,\"format\":\"\",\"indent\":0,\"type\":\"paragraph\",\"version\":1,\"textFormat\":0,\"textStyle\":\"\"},{\"children\":[{\"detail\":0,\"format\":0,\"mode\":\"normal\",\"style\":\"\",\"text\":\"هوتێلەکە کۆمەڵێکی فراوان لە ئاسانکاری هەیە. ناوەندی تەندروستی مەلەوانگە، ساونا، جاکووزی و حەمامی کۆن لەخۆ دەگرێت، لەگەڵ ژووری مەساج و کەرەستەی وەرزشی بۆ پشوودان و چالاکیی جەستەیی. بۆ نانخواردن، میوانان دەتوانن چێژ لە ژینگەی جۆراوجۆر ببینن، لەوانە ڕێستۆرانتی فارسی، نێودەوڵەتی، کۆن و خواردنی خێرا، هەروەها کافێیەکی 24 کاتژمێری. ئاسانکاریی زیاتر وەک یاریگای منداڵان، دوکانی دیاری، نووسینگەی گۆڕینەوەی دراو، خزمەتگوزاریی تەکسی، پارکینگ و خزمەتگوزاریی گەشت ئەزموونەکە تەواو دەکەن. میوانان زۆر جار ستایشی ڕێکخستنی ناوخۆیی، خزمەتگوزاریی نایاب و ستافی پرۆفیشناڵی هوتێلەکە دەکەن.\",\"type\":\"text\",\"version\":1}],\"direction\":null,\"format\":\"\",\"indent\":0,\"type\":\"paragraph\",\"version\":1,\"textFormat\":0,\"textStyle\":\"\"},{\"children\":[{\"detail\":0,\"format\":0,\"mode\":\"normal\",\"style\":\"\",\"text\":\"بەهۆی شوێنە نایابەکەی، ئاسانکارییە گشتگیرەکانی و کەشە لۆکسەکەیەوە، هوتێلی نێودەوڵەتیی قەسر هەڵبژاردەیەکی متمانەپێکراوە بۆ ئەو گەشتیارانەی بەدوای شوێنی مانەوەی ئاست بەرز و ئارام لە نزیک حەرەمی پیرۆزدا دەگەڕێن.\",\"type\":\"text\",\"version\":1}],\"direction\":null,\"format\":\"\",\"indent\":0,\"type\":\"paragraph\",\"version\":1,\"textFormat\":0,\"textStyle\":\"\"}],\"direction\":\"ltr\",\"format\":\"\",\"indent\":0,\"type\":\"root\",\"version\":1,\"textFormat\":1}}", "de-DE": "{\"root\":{\"children\":[{\"children\":[{\"detail\":0,\"format\":1,\"mode\":\"normal\",\"style\":\"\",\"text\":\"Das Qasr International Hotel Maschhad\",\"type\":\"text\",\"version\":1},{\"detail\":0,\"format\":0,\"mode\":\"normal\",\"style\":\"\",\"text\":\" ist eines der ältesten und renommiertesten Fünf-Sterne-Hotels nahe dem heiligen Schrein. Seit 1977 am Anfang der Imam-Reza-Straße in Betrieb, war es dank seiner unverwechselbaren Architektur und luxuriösen Innenausstattung stets eine erste Wahl für Pilger. Nach der jüngsten Renovierung bietet das Hotel über 200 Wohneinheiten – von Einzel- und Doppelzimmern über Luxussuiten, Präsidentensuiten und Hochzeitssuiten bis zu Zimmern, deren Dekor von verschiedenen Epochen der iranischen Geschichte inspiriert ist. Die Nähe zum heiligen Schrein, zum Reza-Basar und zum 17-Schahriwar-Basar sorgt für einen bequemen Zugang für Pilger und macht es zu einer erstklassigen Wahl für Hotelbuchungen in Maschhad.\",\"type\":\"text\",\"version\":1}],\"direction\":null,\"format\":\"\",\"indent\":0,\"type\":\"paragraph\",\"version\":1,\"textFormat\":0,\"textStyle\":\"\"},{\"children\":[{\"detail\":0,\"format\":0,\"mode\":\"normal\",\"style\":\"\",\"text\":\"Das Hotel bietet eine große Auswahl an Annehmlichkeiten. Der Wellnessbereich umfasst Swimmingpool, Sauna, Whirlpool und ein traditionelles Badehaus sowie Massageräume und Fitnesseinrichtungen für Entspannung und Bewegung. Zum Essen stehen verschiedene Restaurants zur Wahl, darunter persische, internationale, traditionelle und Fast-Food-Restaurants, sowie ein rund um die Uhr geöffnetes Café. Weitere Einrichtungen wie ein Kinderspielpark, Souvenirläden, eine Wechselstube, Taxiservice, Parkplätze und Tourservice runden das Angebot ab. Gäste loben häufig die gute Organisation, den hervorragenden Service und das professionelle Personal des Hotels.\",\"type\":\"text\",\"version\":1}],\"direction\":null,\"format\":\"\",\"indent\":0,\"type\":\"paragraph\",\"version\":1,\"textFormat\":0,\"textStyle\":\"\"},{\"children\":[{\"detail\":0,\"format\":0,\"mode\":\"normal\",\"style\":\"\",\"text\":\"Dank seiner erstklassigen Lage, umfassenden Ausstattung und luxuriösen Atmosphäre ist das Qasr International Hotel eine verlässliche Wahl für Reisende, die eine hochwertige, ruhige Unterkunft nahe dem heiligen Schrein suchen.\",\"type\":\"text\",\"version\":1}],\"direction\":null,\"format\":\"\",\"indent\":0,\"type\":\"paragraph\",\"version\":1,\"textFormat\":0,\"textStyle\":\"\"}],\"direction\":\"ltr\",\"format\":\"\",\"indent\":0,\"type\":\"root\",\"version\":1,\"textFormat\":1}}", "fr-FR": "{\"root\":{\"children\":[{\"children\":[{\"detail\":0,\"format\":1,\"mode\":\"normal\",\"style\":\"\",\"text\":\"L’hôtel Qasr International Mashhad\",\"type\":\"text\",\"version\":1},{\"detail\":0,\"format\":0,\"mode\":\"normal\",\"style\":\"\",\"text\":\" est l’un des hôtels cinq étoiles les plus anciens et les plus réputés près du saint sanctuaire. En activité depuis 1977 au début de la rue Imam Reza, il a toujours été un choix de premier ordre pour les pèlerins grâce à son architecture singulière et à ses intérieurs luxueux. Récemment rénové, l’hôtel propose désormais plus de 200 unités d’hébergement, des chambres simples et doubles aux suites de luxe, suites présidentielles et suites lune de miel, en passant par des chambres dont la décoration s’inspire de différentes époques de l’histoire iranienne. Sa proximité avec le saint sanctuaire, le bazar Reza et le bazar 17 Shahrivar garantit aux pèlerins un accès facile et en fait un choix de premier plan pour réserver un hôtel à Mashhad.\",\"type\":\"text\",\"version\":1}],\"direction\":null,\"format\":\"\",\"indent\":0,\"type\":\"paragraph\",\"version\":1,\"textFormat\":0,\"textStyle\":\"\"},{\"children\":[{\"detail\":0,\"format\":0,\"mode\":\"normal\",\"style\":\"\",\"text\":\"L’hôtel propose un large éventail d’équipements. L’espace bien-être comprend une piscine, un sauna, un jacuzzi et un bain traditionnel, ainsi que des salles de massage et des installations de remise en forme pour la détente et l’activité physique. Pour les repas, les clients ont le choix entre plusieurs ambiances, dont des restaurants persan, international, traditionnel et de restauration rapide, ainsi qu’un café ouvert 24h/24. Des services complémentaires tels qu’un parc d’attractions pour enfants, des boutiques de souvenirs, un bureau de change, un service de taxi, un parking et des services d’excursions complètent l’expérience. Les clients saluent souvent la bonne organisation interne de l’hôtel, son excellent service et son personnel professionnel.\",\"type\":\"text\",\"version\":1}],\"direction\":null,\"format\":\"\",\"indent\":0,\"type\":\"paragraph\",\"version\":1,\"textFormat\":0,\"textStyle\":\"\"},{\"children\":[{\"detail\":0,\"format\":0,\"mode\":\"normal\",\"style\":\"\",\"text\":\"Grâce à son emplacement privilégié, à ses équipements complets et à son atmosphère luxueuse, l’hôtel Qasr International est un choix fiable pour les voyageurs en quête d’un hébergement haut de gamme et paisible près du saint sanctuaire.\",\"type\":\"text\",\"version\":1}],\"direction\":null,\"format\":\"\",\"indent\":0,\"type\":\"paragraph\",\"version\":1,\"textFormat\":0,\"textStyle\":\"\"}],\"direction\":\"ltr\",\"format\":\"\",\"indent\":0,\"type\":\"root\",\"version\":1,\"textFormat\":1}}", "ru-RU": "{\"root\":{\"children\":[{\"children\":[{\"detail\":0,\"format\":1,\"mode\":\"normal\",\"style\":\"\",\"text\":\"Международный отель «Каср» в Мешхеде\",\"type\":\"text\",\"version\":1},{\"detail\":0,\"format\":0,\"mode\":\"normal\",\"style\":\"\",\"text\":\" — один из старейших и самых известных пятизвёздочных отелей рядом со святыней. Работая с 1977 года в начале улицы Имама Резы, он всегда был одним из лучших вариантов для паломников благодаря выразительной архитектуре и роскошным интерьерам. После недавней реконструкции отель предлагает более 200 номеров — от одноместных и двухместных до люксов, президентских люксов, люксов для молодожёнов и номеров, оформленных в стиле разных эпох иранской истории. Близость к святыне, базару Реза и базару 17 Шахривар обеспечивает паломникам удобный доступ, что делает отель одним из лучших вариантов при бронировании гостиницы в Мешхеде.\",\"type\":\"text\",\"version\":1}],\"direction\":null,\"format\":\"\",\"indent\":0,\"type\":\"paragraph\",\"version\":1,\"textFormat\":0,\"textStyle\":\"\"},{\"children\":[{\"detail\":0,\"format\":0,\"mode\":\"normal\",\"style\":\"\",\"text\":\"Отель предлагает широкий выбор удобств. В оздоровительном центре есть бассейн, сауна, джакузи и традиционная баня, а также массажные кабинеты и тренажёрный зал для отдыха и физической активности. Гости могут выбирать между ресторанами персидской, международной и традиционной кухни, фастфудом и круглосуточной кофейней. Детский парк развлечений, сувенирные магазины, пункт обмена валюты, услуги такси, парковка и экскурсионное обслуживание дополняют впечатления. Гости часто отмечают слаженную организацию работы отеля, отличный сервис и профессиональный персонал.\",\"type\":\"text\",\"version\":1}],\"direction\":null,\"format\":\"\",\"indent\":0,\"type\":\"paragraph\",\"version\":1,\"textFormat\":0,\"textStyle\":\"\"},{\"children\":[{\"detail\":0,\"format\":0,\"mode\":\"normal\",\"style\":\"\",\"text\":\"Благодаря выгодному расположению, полному набору удобств и роскошной атмосфере международный отель «Каср» — надёжный выбор для путешественников, ищущих спокойное жильё высокого класса рядом со святыней.\",\"type\":\"text\",\"version\":1}],\"direction\":null,\"format\":\"\",\"indent\":0,\"type\":\"paragraph\",\"version\":1,\"textFormat\":0,\"textStyle\":\"\"}],\"direction\":\"ltr\",\"format\":\"\",\"indent\":0,\"type\":\"root\",\"version\":1,\"textFormat\":1}}", "tg-TJ": "{\"root\":{\"children\":[{\"children\":[{\"detail\":0,\"format\":1,\"mode\":\"normal\",\"style\":\"\",\"text\":\"Меҳмонхонаи байналмилалии «Қаср»-и Машҳад\",\"type\":\"text\",\"version\":1},{\"detail\":0,\"format\":0,\"mode\":\"normal\",\"style\":\"\",\"text\":\" яке аз қадимтарин ва маъруфтарин меҳмонхонаҳои панҷситора дар наздикии Ҳарами муқаддас аст. Аз соли 1977 дар ибтидои кӯчаи Имом Ризо фаъолият карда, он ба шарофати меъмории хос ва ороиши дохилии боҳашамат ҳамеша яке аз интихобҳои асосии зоирон будааст. Пас аз таъмири ахир меҳмонхона акнун беш аз 200 воҳиди иқоматӣ пешниҳод мекунад — аз ҳуҷраҳои якҷояву дуҷоя то сюитҳои боҳашамат, сюитҳои президентӣ, сюитҳои моҳи асал ва ҳуҷраҳое, ки ороишашон аз давраҳои гуногуни таърихи Эрон илҳом гирифтааст. Наздикӣ ба Ҳарами муқаддас, Бозори Ризо ва Бозори 17 Шаҳривар дастрасии осонро барои зоирон таъмин мекунад ва онро ба яке аз беҳтарин интихобҳо барои фармоиши меҳмонхона дар Машҳад табдил медиҳад.\",\"type\":\"text\",\"version\":1}],\"direction\":null,\"format\":\"\",\"indent\":0,\"type\":\"paragraph\",\"version\":1,\"textFormat\":0,\"textStyle\":\"\"},{\"children\":[{\"detail\":0,\"format\":0,\"mode\":\"normal\",\"style\":\"\",\"text\":\"Меҳмонхона шароити хеле васеъ дорад. Маркази солимгардонӣ ҳавзи шиноварӣ, сауна, ҷакузӣ ва ҳаммоми анъанавӣ, инчунин ҳуҷраҳои массаж ва толори варзишро барои истироҳат ва фаъолияти ҷисмонӣ дар бар мегирад. Барои хӯрокхӯрӣ меҳмонон метавонанд аз фазоҳои гуногун, аз ҷумла тарабхонаҳои эронӣ, байналмилалӣ, анъанавӣ ва фастфуд, инчунин қаҳвахонаи шабонарӯзӣ баҳра баранд. Шароити иловагӣ, аз қабили боғи фароғатии кӯдакон, мағозаҳои тӯҳфаҳо, нуқтаи мубодилаи асъор, хизматрасонии таксӣ, таваққуфгоҳ ва хизматрасониҳои сайёҳӣ таассуротро комил мегардонанд. Меҳмонон аксар вақт тартиботи дохилии меҳмонхона, хизматрасонии аъло ва кормандони касбии онро таъриф мекунанд.\",\"type\":\"text\",\"version\":1}],\"direction\":null,\"format\":\"\",\"indent\":0,\"type\":\"paragraph\",\"version\":1,\"textFormat\":0,\"textStyle\":\"\"},{\"children\":[{\"detail\":0,\"format\":0,\"mode\":\"normal\",\"style\":\"\",\"text\":\"Бо назардошти мавқеи беҳтарин, шароити ҳамаҷониба ва фазои боҳашамат, Меҳмонхонаи байналмилалии «Қаср» интихоби боэътимод барои мусофиронест, ки дар наздикии Ҳарами муқаддас манзили олӣ ва оромро меҷӯянд.\",\"type\":\"text\",\"version\":1}],\"direction\":null,\"format\":\"\",\"indent\":0,\"type\":\"paragraph\",\"version\":1,\"textFormat\":0,\"textStyle\":\"\"}],\"direction\":\"ltr\",\"format\":\"\",\"indent\":0,\"type\":\"root\",\"version\":1,\"textFormat\":1}}", "zh-CN": "{\"root\":{\"children\":[{\"children\":[{\"detail\":0,\"format\":1,\"mode\":\"normal\",\"style\":\"\",\"text\":\"马什哈德卡斯尔国际酒店\",\"type\":\"text\",\"version\":1},{\"detail\":0,\"format\":0,\"mode\":\"normal\",\"style\":\"\",\"text\":\" 是圣陵附近历史最悠久、最负盛名的五星级酒店之一。自1977年起在伊玛目礼萨街街口营业，凭借独具特色的建筑和豪华的室内装潢，一直是朝圣者的首选。酒店近期经过翻新，现拥有200多个住宿单元，从单人间、双人间到豪华套房、总统套房、蜜月套房，以及以伊朗不同历史时期为装饰灵感的客房，应有尽有。酒店靠近圣陵、礼萨巴扎和十七沙赫里瓦尔巴扎，朝圣者出行十分便捷，是预订马什哈德酒店的首选之一。\",\"type\":\"text\",\"version\":1}],\"direction\":null,\"format\":\"\",\"indent\":0,\"type\":\"paragraph\",\"version\":1,\"textFormat\":0,\"textStyle\":\"\"},{\"children\":[{\"detail\":0,\"format\":0,\"mode\":\"normal\",\"style\":\"\",\"text\":\"酒店设施齐全。健康中心设有游泳池、桑拿、按摩浴缸和传统浴室，另有按摩室和健身设施，供宾客放松身心、运动健身。餐饮方面，宾客可在波斯餐厅、国际餐厅、传统餐厅和快餐厅等多种环境中用餐，还有24小时营业的咖啡厅。儿童游乐园、纪念品商店、货币兑换处、出租车服务、停车场和旅游服务等其他设施，让入住体验更加完美。宾客常常称赞酒店内部管理有序、服务出色、员工专业。\",\"type\":\"text\",\"version\":1}],\"direction\":null,\"format\":\"\",\"indent\":0,\"type\":\"paragraph\",\"version\":1,\"textFormat\":0,\"textStyle\":\"\"},{\"children\":[{\"detail\":0,\"format\":0,\"mode\":\"normal\",\"style\":\"\",\"text\":\"凭借优越的地理位置、完善的设施和豪华的氛围，卡斯尔国际酒店是希望在圣陵附近寻找高端、宁静住宿的旅客的可靠之选。\",\"type\":\"text\",\"version\":1}],\"direction\":null,\"format\":\"\",\"indent\":0,\"type\":\"paragraph\",\"version\":1,\"textFormat\":0,\"textStyle\":\"\"}],\"direction\":\"ltr\",\"format\":\"\",\"indent\":0,\"type\":\"root\",\"version\":1,\"textFormat\":1}}"}'::jsonb),
  ('{"root":{"children":[{"children":[{"detail":0,"format":0,"mode":"normal","style":"","text":"Percook Hotel Apartment in Mashhad was opened in 2016. The advantages of staying at this property include convenient access to the railway station and a 10-minute distance to the Shiraz Street BRT lines, providing easy travel to the Holy Shrine of Imam Reza and the central market. With 24 rooms spread across 4 floors and a team of experienced and trained staff, Percook Hotel Apartment is ready to serve guests in the holy city of Mashhad.","type":"text","version":1}],"direction":null,"format":"","indent":0,"type":"paragraph","version":1,"textFormat":0,"textStyle":""},{"children":[],"direction":null,"format":"","indent":0,"type":"heading","version":1,"tag":"h3"}],"direction":"ltr","format":"","indent":0,"type":"root","version":1}}', '{"tr-TR": "{\"root\":{\"children\":[{\"children\":[{\"detail\":0,\"format\":0,\"mode\":\"normal\",\"style\":\"\",\"text\":\"Meşhed''deki Percook Apart Otel 2016''da açıldı. Bu tesiste konaklamanın avantajları arasında tren istasyonuna kolay erişim ve Şiraz Caddesi metrobüs hatlarına 10 dakikalık mesafe yer alır; bu sayede İmam Rıza Türbesi''ne ve merkez çarşıya kolayca ulaşılabilir. 4 kata yayılmış 24 odası ve deneyimli, eğitimli ekibiyle Percook Apart Otel, kutsal Meşhed şehrinde misafirlerine hizmet etmeye hazırdır.\",\"type\":\"text\",\"version\":1}],\"direction\":null,\"format\":\"\",\"indent\":0,\"type\":\"paragraph\",\"version\":1,\"textFormat\":0,\"textStyle\":\"\"},{\"children\":[],\"direction\":null,\"format\":\"\",\"indent\":0,\"type\":\"heading\",\"version\":1,\"tag\":\"h3\"}],\"direction\":\"ltr\",\"format\":\"\",\"indent\":0,\"type\":\"root\",\"version\":1}}", "es-ES": "{\"root\":{\"children\":[{\"children\":[{\"detail\":0,\"format\":0,\"mode\":\"normal\",\"style\":\"\",\"text\":\"El Apartahotel Percook de Mashhad abrió en 2016. Entre las ventajas de alojarse en este establecimiento están el cómodo acceso a la estación de tren y la cercanía, a 10 minutos, de las líneas de BRT de la calle Shiraz, lo que facilita el desplazamiento al Santuario del Imam Reza y al mercado central. Con 24 habitaciones repartidas en 4 plantas y un equipo experimentado y formado, el Apartahotel Percook está listo para atender a sus huéspedes en la santa ciudad de Mashhad.\",\"type\":\"text\",\"version\":1}],\"direction\":null,\"format\":\"\",\"indent\":0,\"type\":\"paragraph\",\"version\":1,\"textFormat\":0,\"textStyle\":\"\"},{\"children\":[],\"direction\":null,\"format\":\"\",\"indent\":0,\"type\":\"heading\",\"version\":1,\"tag\":\"h3\"}],\"direction\":\"ltr\",\"format\":\"\",\"indent\":0,\"type\":\"root\",\"version\":1}}", "ku-KU": "{\"root\":{\"children\":[{\"children\":[{\"detail\":0,\"format\":0,\"mode\":\"normal\",\"style\":\"\",\"text\":\"شوقەی هوتێلی پەرکووک لە مەشهەد لە ساڵی 2016 کرایەوە. سوودەکانی مانەوە لەم شوێنەدا بریتین لە دەستڕاگەیشتنی ئاسان بە وێستگەی شەمەندەفەر و 10 خولەک دووری لە هێڵەکانی BRTی شەقامی شیرازی، کە گەیشتن بە حەرەمی پیرۆزی ئیمام ڕەزا و بازاڕی ناوەندی ئاسان دەکات. شوقەی هوتێلی پەرکووک بە 24 ژوور لە 4 نهۆمدا و تیمێکی شارەزا و ڕاهێنراوەوە، ئامادەیە خزمەتی میوانان لە شاری پیرۆزی مەشهەد بکات.\",\"type\":\"text\",\"version\":1}],\"direction\":null,\"format\":\"\",\"indent\":0,\"type\":\"paragraph\",\"version\":1,\"textFormat\":0,\"textStyle\":\"\"},{\"children\":[],\"direction\":null,\"format\":\"\",\"indent\":0,\"type\":\"heading\",\"version\":1,\"tag\":\"h3\"}],\"direction\":\"ltr\",\"format\":\"\",\"indent\":0,\"type\":\"root\",\"version\":1}}", "de-DE": "{\"root\":{\"children\":[{\"children\":[{\"detail\":0,\"format\":0,\"mode\":\"normal\",\"style\":\"\",\"text\":\"Das Aparthotel Percook in Maschhad wurde 2016 eröffnet. Zu den Vorzügen eines Aufenthalts zählen die gute Anbindung an den Bahnhof und nur 10 Minuten zu den BRT-Linien an der Schiraz-Straße, die eine bequeme Fahrt zum heiligen Schrein des Imam Reza und zum zentralen Markt ermöglichen. Mit 24 Zimmern auf 4 Etagen und einem erfahrenen, geschulten Team steht das Aparthotel Percook den Gästen in der heiligen Stadt Maschhad gern zu Diensten.\",\"type\":\"text\",\"version\":1}],\"direction\":null,\"format\":\"\",\"indent\":0,\"type\":\"paragraph\",\"version\":1,\"textFormat\":0,\"textStyle\":\"\"},{\"children\":[],\"direction\":null,\"format\":\"\",\"indent\":0,\"type\":\"heading\",\"version\":1,\"tag\":\"h3\"}],\"direction\":\"ltr\",\"format\":\"\",\"indent\":0,\"type\":\"root\",\"version\":1}}", "fr-FR": "{\"root\":{\"children\":[{\"children\":[{\"detail\":0,\"format\":0,\"mode\":\"normal\",\"style\":\"\",\"text\":\"L’appart’hôtel Percook à Mashhad a ouvert en 2016. Séjourner dans cet établissement offre un accès pratique à la gare et se trouve à 10 minutes des lignes de BRT de la rue Shiraz, ce qui facilite les déplacements vers le saint sanctuaire de l’Imam Reza et le marché central. Avec 24 chambres réparties sur 4 étages et une équipe expérimentée et qualifiée, l’appart’hôtel Percook est prêt à accueillir ses hôtes dans la ville sainte de Mashhad.\",\"type\":\"text\",\"version\":1}],\"direction\":null,\"format\":\"\",\"indent\":0,\"type\":\"paragraph\",\"version\":1,\"textFormat\":0,\"textStyle\":\"\"},{\"children\":[],\"direction\":null,\"format\":\"\",\"indent\":0,\"type\":\"heading\",\"version\":1,\"tag\":\"h3\"}],\"direction\":\"ltr\",\"format\":\"\",\"indent\":0,\"type\":\"root\",\"version\":1}}", "ru-RU": "{\"root\":{\"children\":[{\"children\":[{\"detail\":0,\"format\":0,\"mode\":\"normal\",\"style\":\"\",\"text\":\"Апарт-отель «Перкук» в Мешхеде открылся в 2016 году. Среди преимуществ проживания здесь — удобный доступ к железнодорожному вокзалу и 10 минут до линий BRT на улице Ширази, откуда легко добраться до священного мавзолея имама Резы и центрального рынка. Апарт-отель «Перкук» с 24 номерами на 4 этажах и командой опытного, обученного персонала готов принять гостей священного города Мешхеда.\",\"type\":\"text\",\"version\":1}],\"direction\":null,\"format\":\"\",\"indent\":0,\"type\":\"paragraph\",\"version\":1,\"textFormat\":0,\"textStyle\":\"\"},{\"children\":[],\"direction\":null,\"format\":\"\",\"indent\":0,\"type\":\"heading\",\"version\":1,\"tag\":\"h3\"}],\"direction\":\"ltr\",\"format\":\"\",\"indent\":0,\"type\":\"root\",\"version\":1}}", "tg-TJ": "{\"root\":{\"children\":[{\"children\":[{\"detail\":0,\"format\":0,\"mode\":\"normal\",\"style\":\"\",\"text\":\"Апарт-меҳмонхонаи «Перкук» дар Машҳад соли 2016 ба истифода дода шуд. Аз бартариҳои иқомат дар ин маҷмаа дастрасии қулай ба истгоҳи роҳи оҳан ва 10 дақиқа масофа то хатҳои BRT-и кӯчаи Шерозӣ мебошад, ки рафтуомади осонро ба Ҳарами муқаддаси Имом Ризо ва бозори марказӣ фароҳам меорад. Апарт-меҳмонхонаи «Перкук» бо 24 ҳуҷра дар 4 ошёна ва дастаи кормандони ботаҷрибаву омӯзонидашуда омода аст ба меҳмонони шаҳри муқаддаси Машҳад хизмат кунад.\",\"type\":\"text\",\"version\":1}],\"direction\":null,\"format\":\"\",\"indent\":0,\"type\":\"paragraph\",\"version\":1,\"textFormat\":0,\"textStyle\":\"\"},{\"children\":[],\"direction\":null,\"format\":\"\",\"indent\":0,\"type\":\"heading\",\"version\":1,\"tag\":\"h3\"}],\"direction\":\"ltr\",\"format\":\"\",\"indent\":0,\"type\":\"root\",\"version\":1}}", "zh-CN": "{\"root\":{\"children\":[{\"children\":[{\"detail\":0,\"format\":0,\"mode\":\"normal\",\"style\":\"\",\"text\":\"马什哈德佩尔库克酒店式公寓于2016年开业。入住本酒店的优势包括前往火车站交通便利，距设拉齐街BRT快速公交线路仅10分钟，方便前往伊玛目礼萨圣陵和中央市场。佩尔库克酒店式公寓共4层，设有24间客房，并拥有经验丰富、训练有素的员工团队，竭诚为来到圣城马什哈德的宾客服务。\",\"type\":\"text\",\"version\":1}],\"direction\":null,\"format\":\"\",\"indent\":0,\"type\":\"paragraph\",\"version\":1,\"textFormat\":0,\"textStyle\":\"\"},{\"children\":[],\"direction\":null,\"format\":\"\",\"indent\":0,\"type\":\"heading\",\"version\":1,\"tag\":\"h3\"}],\"direction\":\"ltr\",\"format\":\"\",\"indent\":0,\"type\":\"root\",\"version\":1}}"}'::jsonb),
  ('{"root":{"children":[{"children":[{"detail":0,"format":0,"mode":"normal","style":"","text":"Sa''at Guesthouse was opened in 2019. The guesthouse is located near the Holy Shrine of Imam Reza (AS). Dear pilgrims wishing to visit the Holy Shrine of the Eighth Imam can reach the sacred shrine in less than 20 minutes on foot.","type":"text","version":1}],"direction":null,"format":"start","indent":0,"type":"paragraph","version":1,"textFormat":0,"textStyle":""},{"children":[{"detail":0,"format":0,"mode":"normal","style":"","text":"The property consists of 6 floors and 27 accommodation units, with experienced and well-trained staff ready to provide a pleasant stay for our valued guests.","type":"text","version":1}],"direction":null,"format":"start","indent":0,"type":"paragraph","version":1,"textFormat":0,"textStyle":""}],"direction":"ltr","format":"","indent":0,"type":"root","version":1}}', '{"tr-TR": "{\"root\":{\"children\":[{\"children\":[{\"detail\":0,\"format\":0,\"mode\":\"normal\",\"style\":\"\",\"text\":\"Sa''at Pansiyon 2019''da açıldı. Pansiyon, İmam Rıza (a.s.) Türbesi''nin yakınında yer alır. Sekizinci İmam''ın Türbesi''ni ziyaret etmek isteyen değerli hacılar kutsal türbeye yürüyerek 20 dakikadan kısa sürede ulaşabilir.\",\"type\":\"text\",\"version\":1}],\"direction\":null,\"format\":\"start\",\"indent\":0,\"type\":\"paragraph\",\"version\":1,\"textFormat\":0,\"textStyle\":\"\"},{\"children\":[{\"detail\":0,\"format\":0,\"mode\":\"normal\",\"style\":\"\",\"text\":\"6 kat ve 27 konaklama biriminden oluşan tesiste, değerli misafirlerimize keyifli bir konaklama sunmaya hazır deneyimli ve iyi eğitimli bir personel bulunur.\",\"type\":\"text\",\"version\":1}],\"direction\":null,\"format\":\"start\",\"indent\":0,\"type\":\"paragraph\",\"version\":1,\"textFormat\":0,\"textStyle\":\"\"}],\"direction\":\"ltr\",\"format\":\"\",\"indent\":0,\"type\":\"root\",\"version\":1}}", "es-ES": "{\"root\":{\"children\":[{\"children\":[{\"detail\":0,\"format\":0,\"mode\":\"normal\",\"style\":\"\",\"text\":\"La casa de huéspedes Sa''at abrió en 2019. Se encuentra cerca del Santuario del Imam Reza (la paz sea con él). Los queridos peregrinos que deseen visitar el Santuario del Octavo Imam pueden llegar al sagrado santuario en menos de 20 minutos a pie.\",\"type\":\"text\",\"version\":1}],\"direction\":null,\"format\":\"start\",\"indent\":0,\"type\":\"paragraph\",\"version\":1,\"textFormat\":0,\"textStyle\":\"\"},{\"children\":[{\"detail\":0,\"format\":0,\"mode\":\"normal\",\"style\":\"\",\"text\":\"El establecimiento consta de 6 plantas y 27 unidades de alojamiento, con un personal experimentado y bien formado dispuesto a ofrecer una estancia agradable a nuestros apreciados huéspedes.\",\"type\":\"text\",\"version\":1}],\"direction\":null,\"format\":\"start\",\"indent\":0,\"type\":\"paragraph\",\"version\":1,\"textFormat\":0,\"textStyle\":\"\"}],\"direction\":\"ltr\",\"format\":\"\",\"indent\":0,\"type\":\"root\",\"version\":1}}", "ku-KU": "{\"root\":{\"children\":[{\"children\":[{\"detail\":0,\"format\":0,\"mode\":\"normal\",\"style\":\"\",\"text\":\"میوانخانەی سەعات لە ساڵی 2019 کرایەوە. ئەم میوانخانەیە لە نزیک حەرەمی پیرۆزی ئیمام ڕەزا (د.خ) هەڵکەوتووە. زائیرانی بەڕێز کە دەیانەوێت سەردانی حەرەمی پیرۆزی ئیمامی هەشتەم بکەن، دەتوانن بە کەمتر لە 20 خولەک پیادەڕۆیشتن بگەنە حەرەمی پیرۆز.\",\"type\":\"text\",\"version\":1}],\"direction\":null,\"format\":\"start\",\"indent\":0,\"type\":\"paragraph\",\"version\":1,\"textFormat\":0,\"textStyle\":\"\"},{\"children\":[{\"detail\":0,\"format\":0,\"mode\":\"normal\",\"style\":\"\",\"text\":\"ئەم شوێنە لە 6 نهۆم و 27 یەکەی مانەوە پێکهاتووە، و ستافێکی شارەزا و باش ڕاهێنراو ئامادەن مانەوەیەکی خۆش بۆ میوانە بەڕێزەکانمان دابین بکەن.\",\"type\":\"text\",\"version\":1}],\"direction\":null,\"format\":\"start\",\"indent\":0,\"type\":\"paragraph\",\"version\":1,\"textFormat\":0,\"textStyle\":\"\"}],\"direction\":\"ltr\",\"format\":\"\",\"indent\":0,\"type\":\"root\",\"version\":1}}", "de-DE": "{\"root\":{\"children\":[{\"children\":[{\"detail\":0,\"format\":0,\"mode\":\"normal\",\"style\":\"\",\"text\":\"Das Gästehaus Sa''at wurde 2019 eröffnet. Es liegt nahe dem heiligen Schrein des Imam Reza (Friede sei mit ihm). Pilger, die den heiligen Schrein des Achten Imams besuchen möchten, erreichen das Heiligtum in weniger als 20 Minuten zu Fuß.\",\"type\":\"text\",\"version\":1}],\"direction\":null,\"format\":\"start\",\"indent\":0,\"type\":\"paragraph\",\"version\":1,\"textFormat\":0,\"textStyle\":\"\"},{\"children\":[{\"detail\":0,\"format\":0,\"mode\":\"normal\",\"style\":\"\",\"text\":\"Die Unterkunft verfügt über 6 Etagen und 27 Wohneinheiten; erfahrenes und gut geschultes Personal sorgt für einen angenehmen Aufenthalt unserer geschätzten Gäste.\",\"type\":\"text\",\"version\":1}],\"direction\":null,\"format\":\"start\",\"indent\":0,\"type\":\"paragraph\",\"version\":1,\"textFormat\":0,\"textStyle\":\"\"}],\"direction\":\"ltr\",\"format\":\"\",\"indent\":0,\"type\":\"root\",\"version\":1}}", "fr-FR": "{\"root\":{\"children\":[{\"children\":[{\"detail\":0,\"format\":0,\"mode\":\"normal\",\"style\":\"\",\"text\":\"La maison d’hôtes Sa’at a ouvert en 2019. Elle est située près du saint sanctuaire de l’Imam Reza (que la paix soit sur lui). Les chers pèlerins souhaitant se rendre au saint sanctuaire du huitième Imam peuvent l’atteindre en moins de 20 minutes à pied.\",\"type\":\"text\",\"version\":1}],\"direction\":null,\"format\":\"start\",\"indent\":0,\"type\":\"paragraph\",\"version\":1,\"textFormat\":0,\"textStyle\":\"\"},{\"children\":[{\"detail\":0,\"format\":0,\"mode\":\"normal\",\"style\":\"\",\"text\":\"L’établissement compte 6 étages et 27 unités d’hébergement, avec un personnel expérimenté et bien formé, prêt à offrir un séjour agréable à nos précieux hôtes.\",\"type\":\"text\",\"version\":1}],\"direction\":null,\"format\":\"start\",\"indent\":0,\"type\":\"paragraph\",\"version\":1,\"textFormat\":0,\"textStyle\":\"\"}],\"direction\":\"ltr\",\"format\":\"\",\"indent\":0,\"type\":\"root\",\"version\":1}}", "ru-RU": "{\"root\":{\"children\":[{\"children\":[{\"detail\":0,\"format\":0,\"mode\":\"normal\",\"style\":\"\",\"text\":\"Гостевой дом «Саат» открылся в 2019 году. Он расположен рядом со священным мавзолеем имама Резы (мир ему). Уважаемые паломники, желающие посетить мавзолей восьмого имама, могут дойти до святыни пешком менее чем за 20 минут.\",\"type\":\"text\",\"version\":1}],\"direction\":null,\"format\":\"start\",\"indent\":0,\"type\":\"paragraph\",\"version\":1,\"textFormat\":0,\"textStyle\":\"\"},{\"children\":[{\"detail\":0,\"format\":0,\"mode\":\"normal\",\"style\":\"\",\"text\":\"В здании 6 этажей и 27 номеров, а опытный и хорошо обученный персонал готов обеспечить нашим дорогим гостям приятное пребывание.\",\"type\":\"text\",\"version\":1}],\"direction\":null,\"format\":\"start\",\"indent\":0,\"type\":\"paragraph\",\"version\":1,\"textFormat\":0,\"textStyle\":\"\"}],\"direction\":\"ltr\",\"format\":\"\",\"indent\":0,\"type\":\"root\",\"version\":1}}", "tg-TJ": "{\"root\":{\"children\":[{\"children\":[{\"detail\":0,\"format\":0,\"mode\":\"normal\",\"style\":\"\",\"text\":\"Меҳмонсарои «Соат» соли 2019 кушода шуд. Ин меҳмонсаро дар наздикии Ҳарами муқаддаси Имом Ризо (алайҳиссалом) ҷойгир аст. Зоирони гиромӣ, ки ният доранд ба зиёрати Ҳарами муқаддаси Имоми ҳаштум мушарраф шаванд, метавонанд камтар аз 20 дақиқа пиёда ба остони муқаддас расанд.\",\"type\":\"text\",\"version\":1}],\"direction\":null,\"format\":\"start\",\"indent\":0,\"type\":\"paragraph\",\"version\":1,\"textFormat\":0,\"textStyle\":\"\"},{\"children\":[{\"detail\":0,\"format\":0,\"mode\":\"normal\",\"style\":\"\",\"text\":\"Бино аз 6 ошёна ва 27 воҳиди иқоматӣ иборат аст ва кормандони ботаҷрибаву хуб омӯзонидашуда омодаанд барои меҳмонони гиромии мо иқомати гуворо фароҳам оранд.\",\"type\":\"text\",\"version\":1}],\"direction\":null,\"format\":\"start\",\"indent\":0,\"type\":\"paragraph\",\"version\":1,\"textFormat\":0,\"textStyle\":\"\"}],\"direction\":\"ltr\",\"format\":\"\",\"indent\":0,\"type\":\"root\",\"version\":1}}", "zh-CN": "{\"root\":{\"children\":[{\"children\":[{\"detail\":0,\"format\":0,\"mode\":\"normal\",\"style\":\"\",\"text\":\"萨阿特旅馆于2019年开业，位于伊玛目礼萨（愿主赐其平安）圣陵附近。希望前往第八伊玛目圣陵朝拜的尊贵朝圣者，步行不到20分钟即可到达圣陵。\",\"type\":\"text\",\"version\":1}],\"direction\":null,\"format\":\"start\",\"indent\":0,\"type\":\"paragraph\",\"version\":1,\"textFormat\":0,\"textStyle\":\"\"},{\"children\":[{\"detail\":0,\"format\":0,\"mode\":\"normal\",\"style\":\"\",\"text\":\"旅馆共6层，设有27个住宿单元，经验丰富、训练有素的员工随时为尊贵的宾客提供愉快的住宿体验。\",\"type\":\"text\",\"version\":1}],\"direction\":null,\"format\":\"start\",\"indent\":0,\"type\":\"paragraph\",\"version\":1,\"textFormat\":0,\"textStyle\":\"\"}],\"direction\":\"ltr\",\"format\":\"\",\"indent\":0,\"type\":\"root\",\"version\":1}}"}'::jsonb),
  ('{"root":{"children":[{"children":[{"detail":0,"format":1,"mode":"normal","style":"","text":"Shad-Toos Hotel Apartment, Mashhad","type":"text","version":1}],"direction":null,"format":"","indent":0,"type":"paragraph","version":1,"textFormat":0,"textStyle":""},{"children":[{"detail":0,"format":0,"mode":"normal","style":"","text":"Established in 2003, Shad-Toos Hotel Apartment is located on Tabarsi Street, just a 2-minute walk from the Holy Shrine of Imam Reza (AS). As a highly-rated 2-star budget hotel, we offer 35 comfortable rooms, including double, triple, and quadruple options.","type":"text","version":1}],"direction":null,"format":"","indent":0,"type":"paragraph","version":1,"textFormat":0,"textStyle":""},{"children":[{"detail":0,"format":0,"mode":"normal","style":"","text":"One of the most remarkable features of Shad-Toos Hotel is its prime location directly facing the Holy Shrine, offering guests a breathtaking view of the golden dome of Imam Reza (AS).","type":"text","version":1}],"direction":null,"format":"","indent":0,"type":"paragraph","version":1,"textFormat":0,"textStyle":""},{"children":[{"detail":0,"format":0,"mode":"normal","style":"","text":"If you are looking to shop for local souvenirs or explore the city, the historic Reza Bazaar—one of the oldest markets in Mashhad—is only a 7-minute walk away, where you can find a wide variety of traditional gifts and local goods.","type":"text","version":1}],"direction":null,"format":"","indent":0,"type":"paragraph","version":1,"textFormat":0,"textStyle":""}],"direction":"ltr","format":"","indent":0,"type":"root","version":1,"textFormat":1}}', '{"tr-TR": "{\"root\":{\"children\":[{\"children\":[{\"detail\":0,\"format\":1,\"mode\":\"normal\",\"style\":\"\",\"text\":\"Shad-Toos Apart Otel, Meşhed\",\"type\":\"text\",\"version\":1}],\"direction\":null,\"format\":\"\",\"indent\":0,\"type\":\"paragraph\",\"version\":1,\"textFormat\":0,\"textStyle\":\"\"},{\"children\":[{\"detail\":0,\"format\":0,\"mode\":\"normal\",\"style\":\"\",\"text\":\"2003''te kurulan Shad-Toos Apart Otel, Tabarsi Caddesi''nde, İmam Rıza (a.s.) Türbesi''ne yalnızca 2 dakikalık yürüme mesafesinde yer alır. Yüksek puanlı 2 yıldızlı ekonomik bir otel olarak çift, üç ve dört kişilik seçenekler dahil 35 konforlu oda sunuyoruz.\",\"type\":\"text\",\"version\":1}],\"direction\":null,\"format\":\"\",\"indent\":0,\"type\":\"paragraph\",\"version\":1,\"textFormat\":0,\"textStyle\":\"\"},{\"children\":[{\"detail\":0,\"format\":0,\"mode\":\"normal\",\"style\":\"\",\"text\":\"Shad-Toos Otel''in en dikkat çekici özelliklerinden biri, doğrudan Kutsal Türbe''ye bakan ayrıcalıklı konumudur; misafirlere İmam Rıza''nın (a.s.) altın kubbesinin nefes kesici manzarasını sunar.\",\"type\":\"text\",\"version\":1}],\"direction\":null,\"format\":\"\",\"indent\":0,\"type\":\"paragraph\",\"version\":1,\"textFormat\":0,\"textStyle\":\"\"},{\"children\":[{\"detail\":0,\"format\":0,\"mode\":\"normal\",\"style\":\"\",\"text\":\"Yöresel hediyelik eşyalar almak ya da şehri keşfetmek istiyorsanız, Meşhed''in en eski çarşılarından biri olan tarihi Rıza Çarşısı yalnızca 7 dakikalık yürüme mesafesindedir; burada çok çeşitli geleneksel hediyeler ve yöresel ürünler bulabilirsiniz.\",\"type\":\"text\",\"version\":1}],\"direction\":null,\"format\":\"\",\"indent\":0,\"type\":\"paragraph\",\"version\":1,\"textFormat\":0,\"textStyle\":\"\"}],\"direction\":\"ltr\",\"format\":\"\",\"indent\":0,\"type\":\"root\",\"version\":1,\"textFormat\":1}}", "es-ES": "{\"root\":{\"children\":[{\"children\":[{\"detail\":0,\"format\":1,\"mode\":\"normal\",\"style\":\"\",\"text\":\"Apartahotel Shad-Toos, Mashhad\",\"type\":\"text\",\"version\":1}],\"direction\":null,\"format\":\"\",\"indent\":0,\"type\":\"paragraph\",\"version\":1,\"textFormat\":0,\"textStyle\":\"\"},{\"children\":[{\"detail\":0,\"format\":0,\"mode\":\"normal\",\"style\":\"\",\"text\":\"Fundado en 2003, el Apartahotel Shad-Toos se encuentra en la calle Tabarsi, a solo 2 minutos a pie del Santuario del Imam Reza (la paz sea con él). Como hotel económico de 2 estrellas muy bien valorado, ofrecemos 35 habitaciones cómodas, entre ellas dobles, triples y cuádruples.\",\"type\":\"text\",\"version\":1}],\"direction\":null,\"format\":\"\",\"indent\":0,\"type\":\"paragraph\",\"version\":1,\"textFormat\":0,\"textStyle\":\"\"},{\"children\":[{\"detail\":0,\"format\":0,\"mode\":\"normal\",\"style\":\"\",\"text\":\"Una de las características más destacadas del Hotel Shad-Toos es su ubicación privilegiada justo frente al Santuario, que ofrece a los huéspedes una vista impresionante de la cúpula dorada del Imam Reza (la paz sea con él).\",\"type\":\"text\",\"version\":1}],\"direction\":null,\"format\":\"\",\"indent\":0,\"type\":\"paragraph\",\"version\":1,\"textFormat\":0,\"textStyle\":\"\"},{\"children\":[{\"detail\":0,\"format\":0,\"mode\":\"normal\",\"style\":\"\",\"text\":\"Si quieres comprar recuerdos locales o explorar la ciudad, el histórico Bazar Reza —uno de los mercados más antiguos de Mashhad— está a solo 7 minutos a pie, y allí encontrarás una gran variedad de regalos tradicionales y productos locales.\",\"type\":\"text\",\"version\":1}],\"direction\":null,\"format\":\"\",\"indent\":0,\"type\":\"paragraph\",\"version\":1,\"textFormat\":0,\"textStyle\":\"\"}],\"direction\":\"ltr\",\"format\":\"\",\"indent\":0,\"type\":\"root\",\"version\":1,\"textFormat\":1}}", "ku-KU": "{\"root\":{\"children\":[{\"children\":[{\"detail\":0,\"format\":1,\"mode\":\"normal\",\"style\":\"\",\"text\":\"شوقەی هوتێلی شادتووس، مەشهەد\",\"type\":\"text\",\"version\":1}],\"direction\":null,\"format\":\"\",\"indent\":0,\"type\":\"paragraph\",\"version\":1,\"textFormat\":0,\"textStyle\":\"\"},{\"children\":[{\"detail\":0,\"format\":0,\"mode\":\"normal\",\"style\":\"\",\"text\":\"شوقەی هوتێلی شادتووس لە ساڵی 2003 دامەزراوە و لە شەقامی تەبەرسی هەڵکەوتووە، تەنها 2 خولەک پیادەڕۆیشتن لە حەرەمی پیرۆزی ئیمام ڕەزا (د.خ) دوورە. وەک هوتێلێکی ئابووریی 2 ئەستێرەی بەرز هەڵسەنگێنراو، 35 ژووری ئاسوودە پێشکەش دەکەین، لەوانە ژووری دوو کەسی، سێ کەسی و چوار کەسی.\",\"type\":\"text\",\"version\":1}],\"direction\":null,\"format\":\"\",\"indent\":0,\"type\":\"paragraph\",\"version\":1,\"textFormat\":0,\"textStyle\":\"\"},{\"children\":[{\"detail\":0,\"format\":0,\"mode\":\"normal\",\"style\":\"\",\"text\":\"یەکێک لە دیارترین تایبەتمەندییەکانی هوتێلی شادتووس شوێنە نایابەکەیەتی کە ڕاستەوخۆ ڕووی لە حەرەمی پیرۆزە و دیمەنێکی سەرسوڕهێنەری گومەزی زێڕینی ئیمام ڕەزا (د.خ) بە میوانان دەبەخشێت.\",\"type\":\"text\",\"version\":1}],\"direction\":null,\"format\":\"\",\"indent\":0,\"type\":\"paragraph\",\"version\":1,\"textFormat\":0,\"textStyle\":\"\"},{\"children\":[{\"detail\":0,\"format\":0,\"mode\":\"normal\",\"style\":\"\",\"text\":\"ئەگەر دەتەوێت دیاریی ناوچەیی بکڕیت یان شارەکە بگەڕێیت، بازاڕی مێژوویی ڕەزا — یەکێک لە کۆنترین بازاڕەکانی مەشهەد — تەنها 7 خولەک پیادەڕۆیشتن دوورە، کە لەوێ جۆرەها دیاریی کۆن و کاڵای ناوچەیی دەدۆزیتەوە.\",\"type\":\"text\",\"version\":1}],\"direction\":null,\"format\":\"\",\"indent\":0,\"type\":\"paragraph\",\"version\":1,\"textFormat\":0,\"textStyle\":\"\"}],\"direction\":\"ltr\",\"format\":\"\",\"indent\":0,\"type\":\"root\",\"version\":1,\"textFormat\":1}}", "de-DE": "{\"root\":{\"children\":[{\"children\":[{\"detail\":0,\"format\":1,\"mode\":\"normal\",\"style\":\"\",\"text\":\"Aparthotel Shad-Toos, Maschhad\",\"type\":\"text\",\"version\":1}],\"direction\":null,\"format\":\"\",\"indent\":0,\"type\":\"paragraph\",\"version\":1,\"textFormat\":0,\"textStyle\":\"\"},{\"children\":[{\"detail\":0,\"format\":0,\"mode\":\"normal\",\"style\":\"\",\"text\":\"Das 2003 gegründete Aparthotel Shad-Toos liegt an der Tabarsi-Straße, nur 2 Gehminuten vom heiligen Schrein des Imam Reza (Friede sei mit ihm) entfernt. Als sehr gut bewertetes, preisgünstiges 2-Sterne-Hotel bieten wir 35 komfortable Zimmer, darunter Doppel-, Dreibett- und Vierbettzimmer.\",\"type\":\"text\",\"version\":1}],\"direction\":null,\"format\":\"\",\"indent\":0,\"type\":\"paragraph\",\"version\":1,\"textFormat\":0,\"textStyle\":\"\"},{\"children\":[{\"detail\":0,\"format\":0,\"mode\":\"normal\",\"style\":\"\",\"text\":\"Eine der bemerkenswertesten Besonderheiten des Hotels Shad-Toos ist seine erstklassige Lage direkt gegenüber dem heiligen Schrein, die den Gästen einen atemberaubenden Blick auf die goldene Kuppel des Imam Reza (Friede sei mit ihm) bietet.\",\"type\":\"text\",\"version\":1}],\"direction\":null,\"format\":\"\",\"indent\":0,\"type\":\"paragraph\",\"version\":1,\"textFormat\":0,\"textStyle\":\"\"},{\"children\":[{\"detail\":0,\"format\":0,\"mode\":\"normal\",\"style\":\"\",\"text\":\"Wenn Sie lokale Souvenirs kaufen oder die Stadt erkunden möchten: Der historische Reza-Basar – einer der ältesten Märkte von Maschhad – ist nur 7 Gehminuten entfernt; dort finden Sie eine große Auswahl an traditionellen Geschenken und regionalen Waren.\",\"type\":\"text\",\"version\":1}],\"direction\":null,\"format\":\"\",\"indent\":0,\"type\":\"paragraph\",\"version\":1,\"textFormat\":0,\"textStyle\":\"\"}],\"direction\":\"ltr\",\"format\":\"\",\"indent\":0,\"type\":\"root\",\"version\":1,\"textFormat\":1}}", "fr-FR": "{\"root\":{\"children\":[{\"children\":[{\"detail\":0,\"format\":1,\"mode\":\"normal\",\"style\":\"\",\"text\":\"Appart’hôtel Shad-Toos, Mashhad\",\"type\":\"text\",\"version\":1}],\"direction\":null,\"format\":\"\",\"indent\":0,\"type\":\"paragraph\",\"version\":1,\"textFormat\":0,\"textStyle\":\"\"},{\"children\":[{\"detail\":0,\"format\":0,\"mode\":\"normal\",\"style\":\"\",\"text\":\"Fondé en 2003, l’appart’hôtel Shad-Toos est situé dans la rue Tabarsi, à seulement 2 minutes à pied du saint sanctuaire de l’Imam Reza (que la paix soit sur lui). Hôtel économique 2 étoiles très bien noté, nous proposons 35 chambres confortables, dont des chambres doubles, triples et quadruples.\",\"type\":\"text\",\"version\":1}],\"direction\":null,\"format\":\"\",\"indent\":0,\"type\":\"paragraph\",\"version\":1,\"textFormat\":0,\"textStyle\":\"\"},{\"children\":[{\"detail\":0,\"format\":0,\"mode\":\"normal\",\"style\":\"\",\"text\":\"L’un des atouts les plus remarquables de l’hôtel Shad-Toos est son emplacement privilégié juste en face du saint sanctuaire, offrant aux hôtes une vue imprenable sur le dôme doré de l’Imam Reza (que la paix soit sur lui).\",\"type\":\"text\",\"version\":1}],\"direction\":null,\"format\":\"\",\"indent\":0,\"type\":\"paragraph\",\"version\":1,\"textFormat\":0,\"textStyle\":\"\"},{\"children\":[{\"detail\":0,\"format\":0,\"mode\":\"normal\",\"style\":\"\",\"text\":\"Si vous souhaitez acheter des souvenirs locaux ou explorer la ville, le bazar historique Reza — l’un des plus anciens marchés de Mashhad — n’est qu’à 7 minutes à pied ; vous y trouverez un grand choix de cadeaux traditionnels et de produits locaux.\",\"type\":\"text\",\"version\":1}],\"direction\":null,\"format\":\"\",\"indent\":0,\"type\":\"paragraph\",\"version\":1,\"textFormat\":0,\"textStyle\":\"\"}],\"direction\":\"ltr\",\"format\":\"\",\"indent\":0,\"type\":\"root\",\"version\":1,\"textFormat\":1}}", "ru-RU": "{\"root\":{\"children\":[{\"children\":[{\"detail\":0,\"format\":1,\"mode\":\"normal\",\"style\":\"\",\"text\":\"Апарт-отель Шад-Тус, Мешхед\",\"type\":\"text\",\"version\":1}],\"direction\":null,\"format\":\"\",\"indent\":0,\"type\":\"paragraph\",\"version\":1,\"textFormat\":0,\"textStyle\":\"\"},{\"children\":[{\"detail\":0,\"format\":0,\"mode\":\"normal\",\"style\":\"\",\"text\":\"Апарт-отель «Шад-Тус», основанный в 2003 году, расположен на улице Табарси, всего в 2 минутах ходьбы от священного мавзолея имама Резы (мир ему). Мы — бюджетный двухзвёздочный отель с высоким рейтингом и предлагаем 35 комфортабельных номеров, включая двух-, трёх- и четырёхместные.\",\"type\":\"text\",\"version\":1}],\"direction\":null,\"format\":\"\",\"indent\":0,\"type\":\"paragraph\",\"version\":1,\"textFormat\":0,\"textStyle\":\"\"},{\"children\":[{\"detail\":0,\"format\":0,\"mode\":\"normal\",\"style\":\"\",\"text\":\"Одна из главных особенностей отеля «Шад-Тус» — выгодное расположение прямо напротив святыни: гостям открывается захватывающий вид на золотой купол мавзолея имама Резы (мир ему).\",\"type\":\"text\",\"version\":1}],\"direction\":null,\"format\":\"\",\"indent\":0,\"type\":\"paragraph\",\"version\":1,\"textFormat\":0,\"textStyle\":\"\"},{\"children\":[{\"detail\":0,\"format\":0,\"mode\":\"normal\",\"style\":\"\",\"text\":\"Если вы хотите купить местные сувениры или осмотреть город, исторический базар Реза — один из старейших рынков Мешхеда — всего в 7 минутах ходьбы; здесь вы найдёте большой выбор традиционных подарков и местных товаров.\",\"type\":\"text\",\"version\":1}],\"direction\":null,\"format\":\"\",\"indent\":0,\"type\":\"paragraph\",\"version\":1,\"textFormat\":0,\"textStyle\":\"\"}],\"direction\":\"ltr\",\"format\":\"\",\"indent\":0,\"type\":\"root\",\"version\":1,\"textFormat\":1}}", "tg-TJ": "{\"root\":{\"children\":[{\"children\":[{\"detail\":0,\"format\":1,\"mode\":\"normal\",\"style\":\"\",\"text\":\"Апарт-меҳмонхонаи Шоди Тӯс, Машҳад\",\"type\":\"text\",\"version\":1}],\"direction\":null,\"format\":\"\",\"indent\":0,\"type\":\"paragraph\",\"version\":1,\"textFormat\":0,\"textStyle\":\"\"},{\"children\":[{\"detail\":0,\"format\":0,\"mode\":\"normal\",\"style\":\"\",\"text\":\"Апарт-меҳмонхонаи «Шоди Тӯс», ки соли 2003 таъсис ёфтааст, дар кӯчаи Табарсӣ, ҳамагӣ 2 дақиқа пиёда аз Ҳарами муқаддаси Имом Ризо (алайҳиссалом) ҷойгир аст. Ҳамчун меҳмонхонаи арзони дуситора бо баҳои баланд, мо 35 ҳуҷраи бароҳат, аз ҷумла ҳуҷраҳои дуҷоя, сеҷоя ва чорҷоя пешниҳод мекунем.\",\"type\":\"text\",\"version\":1}],\"direction\":null,\"format\":\"\",\"indent\":0,\"type\":\"paragraph\",\"version\":1,\"textFormat\":0,\"textStyle\":\"\"},{\"children\":[{\"detail\":0,\"format\":0,\"mode\":\"normal\",\"style\":\"\",\"text\":\"Яке аз хусусиятҳои барҷастаи меҳмонхонаи «Шоди Тӯс» мавқеи беҳтарини он рӯ ба рӯи Ҳарами муқаддас аст, ки ба меҳмонон манзараи ҳайратангези гунбази тиллоии Имом Ризо (алайҳиссалом)-ро пешкаш мекунад.\",\"type\":\"text\",\"version\":1}],\"direction\":null,\"format\":\"\",\"indent\":0,\"type\":\"paragraph\",\"version\":1,\"textFormat\":0,\"textStyle\":\"\"},{\"children\":[{\"detail\":0,\"format\":0,\"mode\":\"normal\",\"style\":\"\",\"text\":\"Агар шумо мехоҳед тӯҳфаҳои маҳаллӣ харед ё шаҳрро тамошо кунед, Бозори таърихии Ризо — яке аз қадимтарин бозорҳои Машҳад — ҳамагӣ 7 дақиқа пиёда дур аст ва дар он ҷо интихоби васеи тӯҳфаҳои анъанавӣ ва молҳои маҳаллиро пайдо мекунед.\",\"type\":\"text\",\"version\":1}],\"direction\":null,\"format\":\"\",\"indent\":0,\"type\":\"paragraph\",\"version\":1,\"textFormat\":0,\"textStyle\":\"\"}],\"direction\":\"ltr\",\"format\":\"\",\"indent\":0,\"type\":\"root\",\"version\":1,\"textFormat\":1}}", "zh-CN": "{\"root\":{\"children\":[{\"children\":[{\"detail\":0,\"format\":1,\"mode\":\"normal\",\"style\":\"\",\"text\":\"马什哈德沙德图斯酒店式公寓\",\"type\":\"text\",\"version\":1}],\"direction\":null,\"format\":\"\",\"indent\":0,\"type\":\"paragraph\",\"version\":1,\"textFormat\":0,\"textStyle\":\"\"},{\"children\":[{\"detail\":0,\"format\":0,\"mode\":\"normal\",\"style\":\"\",\"text\":\"沙德图斯酒店式公寓成立于2003年，位于塔巴尔西街，步行仅2分钟即可到达伊玛目礼萨（愿主赐其平安）圣陵。作为一家广受好评的二星级经济型酒店，我们提供35间舒适客房，包括双人房、三人房和四人房。\",\"type\":\"text\",\"version\":1}],\"direction\":null,\"format\":\"\",\"indent\":0,\"type\":\"paragraph\",\"version\":1,\"textFormat\":0,\"textStyle\":\"\"},{\"children\":[{\"detail\":0,\"format\":0,\"mode\":\"normal\",\"style\":\"\",\"text\":\"沙德图斯酒店最显著的特色之一是其绝佳位置——正对圣陵，宾客可欣赏伊玛目礼萨（愿主赐其平安）圣陵金色穹顶的壮丽景色。\",\"type\":\"text\",\"version\":1}],\"direction\":null,\"format\":\"\",\"indent\":0,\"type\":\"paragraph\",\"version\":1,\"textFormat\":0,\"textStyle\":\"\"},{\"children\":[{\"detail\":0,\"format\":0,\"mode\":\"normal\",\"style\":\"\",\"text\":\"如果您想选购当地特产纪念品或游览城市，步行仅7分钟即可到达马什哈德最古老的市场之一——历史悠久的礼萨巴扎，在这里可以买到种类繁多的传统礼品和当地商品。\",\"type\":\"text\",\"version\":1}],\"direction\":null,\"format\":\"\",\"indent\":0,\"type\":\"paragraph\",\"version\":1,\"textFormat\":0,\"textStyle\":\"\"}],\"direction\":\"ltr\",\"format\":\"\",\"indent\":0,\"type\":\"root\",\"version\":1,\"textFormat\":1}}"}'::jsonb),
  ('{"root":{"children":[{"children":[{"detail":0,"format":0,"mode":"normal","style":"","text":"“Si Barg Hotel in Mashhad is one of the old hotels with approximately 25 years of experience in the hospitality industry in the city. In 2008, it underwent renovation to enhance the quality of services and guest comfort. This accommodation complex, built on 5 floors, features around 200 rooms and suites with desirable amenities. Furthermore, due to its location on one of the city’s main streets, it is situated away from the hustle and bustle while offering easy access to shopping and commercial centers. Its proximity to the metro line facilitates convenient travel to the holy shrine. The three-star Si Barg Hotel has an experienced and trained staff ready to host our esteemed guests.”","type":"text","version":1}],"direction":null,"format":"","indent":0,"type":"paragraph","version":1,"textFormat":0,"textStyle":""},{"children":[],"direction":null,"format":"","indent":0,"type":"heading","version":1,"tag":"h3"}],"direction":"ltr","format":"","indent":0,"type":"root","version":1}}', '{"tr-TR": "{\"root\":{\"children\":[{\"children\":[{\"detail\":0,\"format\":0,\"mode\":\"normal\",\"style\":\"\",\"text\":\"“Meşhed''deki Si Barg Oteli, şehirde otelcilik sektöründe yaklaşık 25 yıllık deneyime sahip eski otellerden biridir. 2008''de hizmet kalitesini ve misafir konforunu artırmak için yenilenmiştir. 5 kat üzerine inşa edilen bu konaklama kompleksi, cazip olanaklara sahip yaklaşık 200 oda ve süit sunar. Ayrıca şehrin ana caddelerinden birinde yer aldığından şehrin karmaşasından uzaktır ve alışveriş ile ticaret merkezlerine kolay erişim sağlar. Metro hattına yakınlığı kutsal türbeye rahat ulaşımı kolaylaştırır. Üç yıldızlı Si Barg Oteli, saygıdeğer misafirlerimizi ağırlamaya hazır deneyimli ve eğitimli bir personele sahiptir.”\",\"type\":\"text\",\"version\":1}],\"direction\":null,\"format\":\"\",\"indent\":0,\"type\":\"paragraph\",\"version\":1,\"textFormat\":0,\"textStyle\":\"\"},{\"children\":[],\"direction\":null,\"format\":\"\",\"indent\":0,\"type\":\"heading\",\"version\":1,\"tag\":\"h3\"}],\"direction\":\"ltr\",\"format\":\"\",\"indent\":0,\"type\":\"root\",\"version\":1}}", "es-ES": "{\"root\":{\"children\":[{\"children\":[{\"detail\":0,\"format\":0,\"mode\":\"normal\",\"style\":\"\",\"text\":\"«El Hotel Si Barg de Mashhad es uno de los hoteles veteranos de la ciudad, con aproximadamente 25 años de experiencia en el sector hotelero. En 2008 se renovó para mejorar la calidad de los servicios y la comodidad de los huéspedes. Este complejo de alojamiento, construido en 5 plantas, cuenta con unas 200 habitaciones y suites con servicios atractivos. Además, al estar situado en una de las calles principales de la ciudad, queda alejado del bullicio y ofrece un fácil acceso a centros comerciales y de negocios. Su proximidad a la línea de metro facilita los desplazamientos al santo santuario. El Hotel Si Barg, de tres estrellas, cuenta con un personal experimentado y formado, listo para recibir a nuestros estimados huéspedes».\",\"type\":\"text\",\"version\":1}],\"direction\":null,\"format\":\"\",\"indent\":0,\"type\":\"paragraph\",\"version\":1,\"textFormat\":0,\"textStyle\":\"\"},{\"children\":[],\"direction\":null,\"format\":\"\",\"indent\":0,\"type\":\"heading\",\"version\":1,\"tag\":\"h3\"}],\"direction\":\"ltr\",\"format\":\"\",\"indent\":0,\"type\":\"root\",\"version\":1}}", "ku-KU": "{\"root\":{\"children\":[{\"children\":[{\"detail\":0,\"format\":0,\"mode\":\"normal\",\"style\":\"\",\"text\":\"«هوتێلی سی بەرگی مەشهەد یەکێکە لە هوتێلە کۆنەکان بە نزیکەی 25 ساڵ ئەزموون لە بواری هوتێلداری لەم شارەدا. لە ساڵی 2008 بۆ باشترکردنی کوالیتیی خزمەتگوزارییەکان و ئاسوودەیی میوانان نۆژەن کرایەوە. ئەم کۆمەڵگە مانەوەیە کە لە 5 نهۆم دروست کراوە، نزیکەی 200 ژوور و سویتی بە ئاسانکاریی گونجاوەوە هەیە. هەروەها، بەهۆی هەڵکەوتنی لە یەکێک لە شەقامە سەرەکییەکانی شار، لە قەرەباڵغی و ژاوەژاو دوورە و لە هەمان کاتدا دەستڕاگەیشتنی ئاسانی بە ناوەندەکانی بازاڕکردن و بازرگانی هەیە. نزیکیی لە هێڵی مێترۆ هاتوچۆی ئاسان بۆ حەرەمی پیرۆز دابین دەکات. هوتێلی سێ ئەستێرەی سی بەرگ ستافێکی شارەزا و ڕاهێنراوی هەیە کە ئامادەن میوانداریی میوانە بەڕێزەکانمان بکەن.»\",\"type\":\"text\",\"version\":1}],\"direction\":null,\"format\":\"\",\"indent\":0,\"type\":\"paragraph\",\"version\":1,\"textFormat\":0,\"textStyle\":\"\"},{\"children\":[],\"direction\":null,\"format\":\"\",\"indent\":0,\"type\":\"heading\",\"version\":1,\"tag\":\"h3\"}],\"direction\":\"ltr\",\"format\":\"\",\"indent\":0,\"type\":\"root\",\"version\":1}}", "de-DE": "{\"root\":{\"children\":[{\"children\":[{\"detail\":0,\"format\":0,\"mode\":\"normal\",\"style\":\"\",\"text\":\"„Das Si Barg Hotel in Maschhad ist eines der traditionsreichen Hotels der Stadt mit rund 25 Jahren Erfahrung im Gastgewerbe. 2008 wurde es renoviert, um die Servicequalität und den Gästekomfort zu verbessern. Der Komplex erstreckt sich über 5 Etagen und bietet rund 200 Zimmer und Suiten mit angenehmer Ausstattung. Dank seiner Lage an einer der Hauptstraßen der Stadt liegt es abseits von Lärm und Trubel und bietet dennoch bequemen Zugang zu Einkaufs- und Geschäftszentren. Die Nähe zur Metrolinie ermöglicht eine bequeme Fahrt zum heiligen Schrein. Das Drei-Sterne-Hotel Si Barg verfügt über erfahrenes und geschultes Personal, das unsere geschätzten Gäste gern beherbergt.“\",\"type\":\"text\",\"version\":1}],\"direction\":null,\"format\":\"\",\"indent\":0,\"type\":\"paragraph\",\"version\":1,\"textFormat\":0,\"textStyle\":\"\"},{\"children\":[],\"direction\":null,\"format\":\"\",\"indent\":0,\"type\":\"heading\",\"version\":1,\"tag\":\"h3\"}],\"direction\":\"ltr\",\"format\":\"\",\"indent\":0,\"type\":\"root\",\"version\":1}}", "fr-FR": "{\"root\":{\"children\":[{\"children\":[{\"detail\":0,\"format\":0,\"mode\":\"normal\",\"style\":\"\",\"text\":\"« L’hôtel Si Barg à Mashhad est l’un des hôtels anciens de la ville, fort d’environ 25 ans d’expérience dans l’hôtellerie. En 2008, il a été rénové afin d’améliorer la qualité des services et le confort des clients. Ce complexe hôtelier de 5 étages compte environ 200 chambres et suites dotées d’équipements agréables. Par ailleurs, situé sur l’une des grandes artères de la ville, il se tient à l’écart de l’agitation tout en offrant un accès facile aux centres commerciaux et d’affaires. La proximité de la ligne de métro facilite les déplacements vers le saint sanctuaire. L’hôtel trois étoiles Si Barg dispose d’un personnel expérimenté et qualifié, prêt à accueillir nos chers hôtes. »\",\"type\":\"text\",\"version\":1}],\"direction\":null,\"format\":\"\",\"indent\":0,\"type\":\"paragraph\",\"version\":1,\"textFormat\":0,\"textStyle\":\"\"},{\"children\":[],\"direction\":null,\"format\":\"\",\"indent\":0,\"type\":\"heading\",\"version\":1,\"tag\":\"h3\"}],\"direction\":\"ltr\",\"format\":\"\",\"indent\":0,\"type\":\"root\",\"version\":1}}", "ru-RU": "{\"root\":{\"children\":[{\"children\":[{\"detail\":0,\"format\":0,\"mode\":\"normal\",\"style\":\"\",\"text\":\"«Отель „Си Барг“ в Мешхеде — один из старых отелей города, около 25 лет работающий в гостиничной сфере. В 2008 году он был реконструирован для повышения качества обслуживания и комфорта гостей. В этом пятиэтажном комплексе около 200 номеров и люксов с хорошими удобствами. Кроме того, благодаря расположению на одной из главных улиц города он находится вдали от суеты и при этом обеспечивает удобный доступ к торговым и коммерческим центрам. Близость к линии метро облегчает поездки к священному мавзолею. Опытный и обученный персонал трёхзвёздочного отеля „Си Барг“ готов принять наших уважаемых гостей.»\",\"type\":\"text\",\"version\":1}],\"direction\":null,\"format\":\"\",\"indent\":0,\"type\":\"paragraph\",\"version\":1,\"textFormat\":0,\"textStyle\":\"\"},{\"children\":[],\"direction\":null,\"format\":\"\",\"indent\":0,\"type\":\"heading\",\"version\":1,\"tag\":\"h3\"}],\"direction\":\"ltr\",\"format\":\"\",\"indent\":0,\"type\":\"root\",\"version\":1}}", "tg-TJ": "{\"root\":{\"children\":[{\"children\":[{\"detail\":0,\"format\":0,\"mode\":\"normal\",\"style\":\"\",\"text\":\"«Меҳмонхонаи „Сӣ Барг“ дар Машҳад яке аз меҳмонхонаҳои қадимии шаҳр бо тақрибан 25 сол таҷриба дар соҳаи меҳмондорӣ мебошад. Соли 2008 барои баланд бардоштани сифати хизматрасонӣ ва роҳати меҳмонон таъмир гардид. Ин маҷмааи иқоматӣ, ки дар 5 ошёна бино ёфтааст, тақрибан 200 ҳуҷра ва сюит бо шароити мувофиқ дорад. Илова бар ин, ба туфайли ҷойгиршавӣ дар яке аз кӯчаҳои асосии шаҳр, он дур аз ғавғо қарор дошта, дастрасии осон ба марказҳои савдою тиҷоратиро фароҳам меорад. Наздикӣ ба хатти метро рафтуомадро ба Ҳарами муқаддас осон мекунад. Меҳмонхонаи сеситораи «Сӣ Барг» кормандони ботаҷрибаву омӯзонидашуда дорад, ки омодаанд меҳмонони гиромии моро пазироӣ кунанд.»\",\"type\":\"text\",\"version\":1}],\"direction\":null,\"format\":\"\",\"indent\":0,\"type\":\"paragraph\",\"version\":1,\"textFormat\":0,\"textStyle\":\"\"},{\"children\":[],\"direction\":null,\"format\":\"\",\"indent\":0,\"type\":\"heading\",\"version\":1,\"tag\":\"h3\"}],\"direction\":\"ltr\",\"format\":\"\",\"indent\":0,\"type\":\"root\",\"version\":1}}", "zh-CN": "{\"root\":{\"children\":[{\"children\":[{\"detail\":0,\"format\":0,\"mode\":\"normal\",\"style\":\"\",\"text\":\"“马什哈德西巴尔格酒店是该市一家老牌酒店，拥有约25年的酒店业经验。2008年，酒店进行了翻新，以提升服务质量和宾客舒适度。这座住宿综合楼共5层，拥有约200间客房和套房，设施完善。此外，酒店位于城市主干道之一，既远离喧嚣，又可便捷前往购物和商业中心。酒店靠近地铁线路，前往圣陵十分方便。三星级西巴尔格酒店拥有经验丰富、训练有素的员工，竭诚欢迎各位尊贵的宾客。”\",\"type\":\"text\",\"version\":1}],\"direction\":null,\"format\":\"\",\"indent\":0,\"type\":\"paragraph\",\"version\":1,\"textFormat\":0,\"textStyle\":\"\"},{\"children\":[],\"direction\":null,\"format\":\"\",\"indent\":0,\"type\":\"heading\",\"version\":1,\"tag\":\"h3\"}],\"direction\":\"ltr\",\"format\":\"\",\"indent\":0,\"type\":\"root\",\"version\":1}}"}'::jsonb),
  ('{"root":{"children":[{"children":[{"detail":0,"format":0,"mode":"normal","style":"","text":"Newly built and luxurious 150 m² three-bedroom units.","type":"text","version":1}],"direction":null,"format":"","indent":0,"type":"paragraph","version":1,"textFormat":0,"textStyle":""}],"direction":"ltr","format":"","indent":0,"type":"root","version":1}}', '{"tr-TR": "{\"root\":{\"children\":[{\"children\":[{\"detail\":0,\"format\":0,\"mode\":\"normal\",\"style\":\"\",\"text\":\"Yeni yapılmış, lüks, 150 m² üç yatak odalı daireler.\",\"type\":\"text\",\"version\":1}],\"direction\":null,\"format\":\"\",\"indent\":0,\"type\":\"paragraph\",\"version\":1,\"textFormat\":0,\"textStyle\":\"\"}],\"direction\":\"ltr\",\"format\":\"\",\"indent\":0,\"type\":\"root\",\"version\":1}}", "es-ES": "{\"root\":{\"children\":[{\"children\":[{\"detail\":0,\"format\":0,\"mode\":\"normal\",\"style\":\"\",\"text\":\"Unidades de tres dormitorios de 150 m², nuevas y lujosas.\",\"type\":\"text\",\"version\":1}],\"direction\":null,\"format\":\"\",\"indent\":0,\"type\":\"paragraph\",\"version\":1,\"textFormat\":0,\"textStyle\":\"\"}],\"direction\":\"ltr\",\"format\":\"\",\"indent\":0,\"type\":\"root\",\"version\":1}}", "ku-KU": "{\"root\":{\"children\":[{\"children\":[{\"detail\":0,\"format\":0,\"mode\":\"normal\",\"style\":\"\",\"text\":\"یەکەی 150 م²ی سێ ژووری نووستن، تازە دروستکراو و لۆکس.\",\"type\":\"text\",\"version\":1}],\"direction\":null,\"format\":\"\",\"indent\":0,\"type\":\"paragraph\",\"version\":1,\"textFormat\":0,\"textStyle\":\"\"}],\"direction\":\"ltr\",\"format\":\"\",\"indent\":0,\"type\":\"root\",\"version\":1}}", "de-DE": "{\"root\":{\"children\":[{\"children\":[{\"detail\":0,\"format\":0,\"mode\":\"normal\",\"style\":\"\",\"text\":\"Neu gebaute, luxuriöse Wohneinheiten mit drei Schlafzimmern und 150 m².\",\"type\":\"text\",\"version\":1}],\"direction\":null,\"format\":\"\",\"indent\":0,\"type\":\"paragraph\",\"version\":1,\"textFormat\":0,\"textStyle\":\"\"}],\"direction\":\"ltr\",\"format\":\"\",\"indent\":0,\"type\":\"root\",\"version\":1}}", "fr-FR": "{\"root\":{\"children\":[{\"children\":[{\"detail\":0,\"format\":0,\"mode\":\"normal\",\"style\":\"\",\"text\":\"Logements neufs et luxueux de 150 m² avec trois chambres.\",\"type\":\"text\",\"version\":1}],\"direction\":null,\"format\":\"\",\"indent\":0,\"type\":\"paragraph\",\"version\":1,\"textFormat\":0,\"textStyle\":\"\"}],\"direction\":\"ltr\",\"format\":\"\",\"indent\":0,\"type\":\"root\",\"version\":1}}", "ru-RU": "{\"root\":{\"children\":[{\"children\":[{\"detail\":0,\"format\":0,\"mode\":\"normal\",\"style\":\"\",\"text\":\"Новые роскошные апартаменты площадью 150 м² с тремя спальнями.\",\"type\":\"text\",\"version\":1}],\"direction\":null,\"format\":\"\",\"indent\":0,\"type\":\"paragraph\",\"version\":1,\"textFormat\":0,\"textStyle\":\"\"}],\"direction\":\"ltr\",\"format\":\"\",\"indent\":0,\"type\":\"root\",\"version\":1}}", "tg-TJ": "{\"root\":{\"children\":[{\"children\":[{\"detail\":0,\"format\":0,\"mode\":\"normal\",\"style\":\"\",\"text\":\"Воҳидҳои навсохт ва боҳашамати 150 м² бо се хобгоҳ.\",\"type\":\"text\",\"version\":1}],\"direction\":null,\"format\":\"\",\"indent\":0,\"type\":\"paragraph\",\"version\":1,\"textFormat\":0,\"textStyle\":\"\"}],\"direction\":\"ltr\",\"format\":\"\",\"indent\":0,\"type\":\"root\",\"version\":1}}", "zh-CN": "{\"root\":{\"children\":[{\"children\":[{\"detail\":0,\"format\":0,\"mode\":\"normal\",\"style\":\"\",\"text\":\"全新豪华的150平方米三居室单元。\",\"type\":\"text\",\"version\":1}],\"direction\":null,\"format\":\"\",\"indent\":0,\"type\":\"paragraph\",\"version\":1,\"textFormat\":0,\"textStyle\":\"\"}],\"direction\":\"ltr\",\"format\":\"\",\"indent\":0,\"type\":\"root\",\"version\":1}}"}'::jsonb);

